const TurboType = {
  SEQUENCE_FLOW: 1,
  START_EVENT: 2,
  END_EVENT: 3,
  USER_TASK: 4,
  SERVICE_TASK: 5,
  EXCLUSIVE_GATEWAY: 6,
};

function convertFlowElementToEdge(element) {
  const { incoming, outgoing, properties, key } = element;
  const { text, startPoint, endPoint, pointsList, logicFlowType } = properties;
  const edge = {
    id: key,
    type: logicFlowType,
    sourceNodeId: incoming[0],
    targetNodeId: outgoing[0],
    text,
    startPoint,
    endPoint,
    pointsList,
    properties: {},
  };
  const excludeProperties = ['startPoint', 'endPoint', 'pointsList', 'text', 'logicFlowType'];
  Object.keys(element.properties).forEach(property => {
    if (excludeProperties.indexOf(property) === -1) {
      edge.properties[property] = element.properties[property];
    }
  });
  return edge;
}

function convertFlowElementToNode(element) {
  const { properties, key } = element;
  const { x, y, text, logicFlowType } = properties;
  const node = {
    id: key,
    type: logicFlowType,
    x,
    y,
    text,
    properties: {},
  };
  const excludeProperties = ['x', 'y', 'text', 'logicFlowType'];
  Object.keys(element.properties).forEach(property => {
    if (excludeProperties.indexOf(property) === -1) {
      node.properties[property] = element.properties[property];
    }
  });
  return node;
}

export function toLogicFlowData(data) {
  const lfData: {
    // TODO type
    nodes: any[];
    edges: any[];
  } = {
    nodes: [],
    edges: [],
  };
  const list = data.flowElementList;
  list &&
    list.length > 0 &&
    list.forEach(element => {
      if (element.type === TurboType.SEQUENCE_FLOW) {
        const edge = convertFlowElementToEdge(element);
        lfData.edges.push(edge);
      } else {
        const node = convertFlowElementToNode(element);
        lfData.nodes.push(node);
      }
    });
  return lfData;
}

import nodeConfig from './config';
import { buildBitUUID } from '/@/utils/uuid';

// const isEmpty = data => data === null || data === undefined || data === '';
const isEmptyArray = data => (Array.isArray(data) ? data.length === 0 : true);

export class NodeUtils {
  /**
   * 判断节点类型
   * @param {Node} node - 节点数据
   * @returns Boolean
   */
  static isConditionNode(node) {
    return node && node.type === 'condition';
  }
  static isCopyNode(node) {
    return node && node.type === 'copy';
  }
  static isStartNode(node) {
    return node && node.type === 'start';
  }
  static isApproverNode(node) {
    return node && node.type === 'approver';
  }
  static isTimerNode(node) {
    return node && node.type === 'timer';
  }
  static isSubFlowNode(node) {
    return node && node.type === 'subFlow';
  }
  static isInterflowNode(node) {
    return node && node.type === 'approver' && node.isInterflow;
  }
  static isBranchFlowNode(node) {
    return node && node.type === 'approver' && node.isBranchFlow;
  }
  /**
   * 创建指定节点
   * @param { String } type - 节点类型
   * @param { Object } previousNodeId - 父节点id
   * @returns { Object } 节点数据
   */
  static createNode(type, previousNodeId?) {
    const res = JSON.parse(JSON.stringify(nodeConfig[type]));
    res.nodeId = buildBitUUID();
    if (type !== 'start' && type !== 'timer') res.properties.title += res.nodeId;
    res.prevId = previousNodeId;
    return res;
  }
  /**
   * 获取指定节点的父节点（前一个节点）
   * @param { String } prevId - 父节点id
   * @param { Object } processData - 流程图全部数据
   * @returns { Object } 父节点
   */
  static getPreviousNode(prevId, processData) {
    if (processData.nodeId === prevId) return processData;
    if (processData.childNode) {
      const r1 = this.getPreviousNode(prevId, processData.childNode);
      if (r1) {
        return r1;
      }
    }
    if (processData.conditionNodes) {
      for (const c of processData.conditionNodes) {
        const r2 = this.getPreviousNode(prevId, c);
        if (r2) {
          return r2;
        }
      }
    }
  }

  /**
   * 删除节点
   * @param { Object  } nodeData - 被删除节点的数据
   * @param { Object  } processData - 流程图的所有节点数据
   */
  static deleteNode(nodeData, processData, checkEmpty = true) {
    const prevNode = this.getPreviousNode(nodeData.prevId, processData);
    if (checkEmpty && prevNode.type === 'empty') {
      if (this.isConditionNode(nodeData) || this.isInterflowNode(nodeData) || this.isBranchFlowNode(nodeData)) {
        const willDelBranch = prevNode.conditionNodes.length === 2;
        const target = willDelBranch ? prevNode : nodeData;
        this.deleteNode(target, processData, willDelBranch);
      } else {
        if (isEmptyArray(prevNode.conditionNodes)) {
          this.deleteNode(prevNode, processData);
        }
        this.deleteNode(nodeData, processData, false);
      }
      // this.deleteNode( prevNode, processData )
      // !this.isConditionNode(nodeData) && this.deleteNode(nodeData, processData)
      return;
    }
    const concatChild = (prev, delNode) => {
      prev.childNode = delNode.childNode;
      isEmptyArray(prev.conditionNodes) && (prev.conditionNodes = delNode.conditionNodes);
      prev.childNode && (prev.childNode.prevId = prev.nodeId);
      prev.conditionNodes && prev.conditionNodes.forEach(c => (c.prevId = prev.nodeId));
    };
    if (this.isConditionNode(nodeData) || this.isInterflowNode(nodeData) || this.isBranchFlowNode(nodeData)) {
      const cons = prevNode.conditionNodes;
      const index = cons.findIndex(c => c.nodeId === nodeData.nodeId);
      if (cons.length > 2) {
        cons.splice(index, 1);
      } else {
        const anotherCon = cons[+!index];
        delete prevNode.conditionNodes;
        delete prevNode.conditionType;
        if (prevNode.childNode) {
          let endNode = anotherCon;
          while (endNode.childNode) {
            endNode = endNode.childNode;
          }
          endNode.childNode = prevNode.childNode;
          endNode.childNode.prevId = endNode.nodeId;
        }
        concatChild(prevNode, anotherCon);
        if (prevNode.childNode && prevNode.childNode.type === 'empty') {
          this.deleteNode(prevNode.childNode, prevNode);
        }
      }
      // 重新编排优先级
      cons.forEach((c, i) => (c.properties.priority = i));
      return;
    }
    concatChild(prevNode, nodeData);
  }
  // TODO:
  // static copyNode ( nodeData, processData ) {
  //   let prevNode = this.getPreviousNode( nodeData.prevId, processData )
  //   let index = prevNode.conditionNodes.findIndex( c => c.nodeId === nodeData.nodeId )

  // }
  /**
   * 添加审计节点（普通节点 approver）
   * @param { Object } data - 目标节点数据，在该数据节点之后添加审计节点
   * @param { Object } isBranchAction - 目标节点数据，是否是条件分支
   * @param { Object } newChildNode - 传入的新的节点 用户操作均为空  删除操作/添加抄送人 会传入该参数 以模拟添加节点
   */
  static addApprovalNode(data, isBranchAction, newChildNode: any = undefined) {
    const oldChildNode = data.childNode;
    newChildNode = newChildNode || this.createNode('approver', data.nodeId);
    data.childNode = newChildNode;
    if (oldChildNode) {
      newChildNode.childNode = oldChildNode;
      oldChildNode.prevId = newChildNode.nodeId;
    }
    const conditionNodes = data.conditionNodes;
    if (Array.isArray(conditionNodes) && !isBranchAction && conditionNodes.length) {
      newChildNode.conditionNodes = conditionNodes.map(c => {
        c.prevId = newChildNode.nodeId;
        return c;
      });
      delete data.conditionNodes;
    }
    if (oldChildNode && oldChildNode.type === 'empty' && newChildNode.type !== 'empty' && oldChildNode.conditionNodes.length === 0) {
      this.deleteNode(oldChildNode, data);
    }
  }
  /**
   * 添加空节点
   * @param { Object } data - 空节点的父级节点
   * @return { Object } emptyNode - 空节点数据
   */
  static addEmptyNode(data, _isNew) {
    const emptyNode = this.createNode('empty', data.nodeId);
    this.addApprovalNode(data, true, emptyNode);
    return emptyNode;
  }

  static addCopyNode(data, isBranchAction) {
    // 复用addApprovalNode  因为抄送人和审批人基本一致
    this.addApprovalNode(data, isBranchAction, this.createNode('copy', data.nodeId));
  }

  static addTimerNode(data, isBranchAction) {
    // 复用addApprovalNode  因为和审批人基本一致
    this.addApprovalNode(data, isBranchAction, this.createNode('timer', data.nodeId));
  }
  static addSubFlowNode(data, isBranchAction) {
    // 复用addApprovalNode  因为和审批人基本一致
    this.addApprovalNode(data, isBranchAction, this.createNode('subFlow', data.nodeId));
  }
  /**
   * 添加条件节点 condition 通过点击添加条件进入该操作
   * @param { Object } data - 目标节点所在分支数据，在该分支最后添加条件节点
   */
  static appendConditionNode(data, isSwerve) {
    const conditions = data.conditionNodes;
    const node = this.createNode('condition', data.nodeId);
    if (isSwerve) {
      node.properties.title = '转向' + node.properties.title;
      node.properties.conditionType = 1;
    }
    const defaultNodeIndex = conditions.findIndex(node => node.properties.isDefault);
    node.properties.priority = conditions.length;
    if (defaultNodeIndex > -1) {
      conditions.splice(-1, 0, node); // 插在倒数第二个
      //更新优先级
      node.properties.priority = conditions.length - 2;
      conditions[conditions.length - 1].properties.priority = conditions.length - 1;
    } else {
      conditions.push(node);
    }
    this.setDefaultCondition(node, data);
  }
  // 添加分流/合流 branch
  static appendInterflowNode(data) {
    const conditions = data.conditionNodes;
    const node = this.createNode('interflow', data.nodeId);
    const defaultNodeIndex = conditions.findIndex(node => node.properties.isDefault);
    node.properties.priority = conditions.length;
    if (defaultNodeIndex > -1) {
      conditions.splice(-1, 0, node); // 插在倒数第二个
      //更新优先级
      node.properties.priority = conditions.length - 2;
      conditions[conditions.length - 1].properties.priority = conditions.length - 1;
    } else {
      conditions.push(node);
    }
  }
  // 添加选择分支 branch
  static appendBranchFlowNode(data) {
    const conditions = data.conditionNodes;
    const node = this.createNode('branchFlow', data.nodeId);
    const defaultNodeIndex = conditions.findIndex(node => node.properties.isDefault);
    node.properties.priority = conditions.length;
    if (defaultNodeIndex > -1) {
      conditions.splice(-1, 0, node); // 插在倒数第二个
      //更新优先级
      node.properties.priority = conditions.length - 2;
      conditions[conditions.length - 1].properties.priority = conditions.length - 1;
    } else {
      conditions.push(node);
    }
  }
  /**
   * 添加条件分支 branch
   * @param { Object } data - 目标节点所在节点数据，在该节点最后添加分支节点
   */
  static appendBranch(data, isBottomBtnOfBranch) {
    // isBottomBtnOfBranch 用户点击的是分支树下面的按钮
    let nodeData = data;
    // 由于conditionNodes是数组 不能添加下级分支 故在两个分支树之间添加一个不会显示的正常节点 兼容此种情况
    if (Array.isArray(data.conditionNodes) && data.conditionNodes.length) {
      if (isBottomBtnOfBranch) {
        // 添加一个模拟用的空白节点并返回这个节点，作为新分支的父节点
        nodeData = this.addEmptyNode(nodeData, true);
      } else {
        const emptyNode = this.addEmptyNode(nodeData, true);
        emptyNode.conditionNodes = nodeData.conditionNodes;
        emptyNode.conditionType = 'condition';
        emptyNode.conditionNodes.forEach(n => {
          n.prevId = emptyNode.nodeId;
        });
      }
    }
    const conditionNodes = [this.createNode('condition', nodeData.nodeId), this.createNode('condition', nodeData.nodeId)].map((c, i) => {
      c.properties.priority = i;
      return c;
    });
    nodeData.conditionNodes = conditionNodes;
    nodeData.conditionType = 'condition';
  }
  static appendInterflowBranch(data, isBottomBtnOfBranch) {
    // isBottomBtnOfBranch 用户点击的是分支树下面的按钮
    let nodeData = data;
    // 由于conditionNodes是数组 不能添加下级分支 故在两个分支树之间添加一个不会显示的正常节点 兼容此种情况
    if (Array.isArray(data.conditionNodes) && data.conditionNodes.length) {
      if (isBottomBtnOfBranch) {
        // 添加一个模拟用的空白节点并返回这个节点，作为新分支的父节点
        nodeData = this.addEmptyNode(nodeData, true);
      } else {
        const emptyNode = this.addEmptyNode(nodeData, true);
        emptyNode.conditionNodes = nodeData.conditionNodes;
        emptyNode.conditionType = 'interflow';
        emptyNode.conditionNodes.forEach(n => {
          n.prevId = emptyNode.nodeId;
        });
      }
    }
    const conditionNodes = [this.createNode('interflow', nodeData.nodeId), this.createNode('interflow', nodeData.nodeId)];
    nodeData.conditionNodes = conditionNodes;
    nodeData.conditionType = 'interflow';
  }
  // 新增选择分支节点
  static appendBranchFlowBranch(data, isBottomBtnOfBranch) {
    // isBottomBtnOfBranch 用户点击的是分支树下面的按钮
    let nodeData = data;
    // 由于conditionNodes是数组 不能添加下级分支 故在两个分支树之间添加一个不会显示的正常节点 兼容此种情况
    if (Array.isArray(data.conditionNodes) && data.conditionNodes.length) {
      if (isBottomBtnOfBranch) {
        // 添加一个模拟用的空白节点并返回这个节点，作为新分支的父节点
        nodeData = this.addEmptyNode(nodeData, true);
      } else {
        const emptyNode = this.addEmptyNode(nodeData, true);
        emptyNode.conditionNodes = nodeData.conditionNodes;
        emptyNode.conditionType = 'branchFlow';
        emptyNode.conditionNodes.forEach(n => {
          n.prevId = emptyNode.nodeId;
        });
      }
    }
    const conditionNodes = [this.createNode('branchFlow', nodeData.nodeId), this.createNode('branchFlow', nodeData.nodeId)];
    nodeData.conditionNodes = conditionNodes;
    nodeData.conditionType = 'branchFlow';
  }
  /**
   * 重设节点优先级（条件节点）
   * @param {Node} cNode - 当前节点
   * @param {Number} oldPriority - 替换前的优先级（在数组中的顺序）
   * @param {Node} processData - 整个流程图节点数据
   */
  static resortPriorityByCNode(cNode, oldPriority, processData) {
    // 当前节点为默认节点 取消修改优先级
    if (cNode.properties.isDefault) {
      cNode.properties.priority = oldPriority;
      return;
    }
    const prevNode = this.getPreviousNode(cNode.prevId, processData);
    const newPriority = cNode.properties.priority;
    // 替换节点为默认节点 取消修改优先级
    if (prevNode.conditionNodes[newPriority].properties.isDefault) {
      cNode.properties.priority = oldPriority;
      return;
    }
    const delNode = prevNode.conditionNodes.splice(newPriority, 1, cNode)[0];
    delNode.properties.priority = oldPriority;
    prevNode.conditionNodes[oldPriority] = delNode;
  }

  /**
   * 提升条件节点优先级——排序在前
   * @param { Object } data - 目标节点数据
   * @param { Object  } processData - 流程图的所有节点数据
   */
  static increasePriority(data, processData) {
    if (data.properties.isDefault) {
      // 默认节点不能修改优先级
      return;
    }
    // 分支节点数据 包含该分支所有的条件节点
    const prevNode = this.getPreviousNode(data.prevId, processData);
    const branchData = prevNode.conditionNodes;
    const index = branchData.findIndex(c => c === data);
    if (index) {
      // 和前一个数组项交换位置 Array.prototype.splice会返回包含被删除的项的集合（数组）
      branchData[index - 1].properties.priority = index;
      branchData[index].properties.priority = index - 1;
      branchData[index - 1] = branchData.splice(index, 1, branchData[index - 1])[0];
    }
  }
  /**
   * 降低条件节点优先级——排序在后
   * @param { Object } data - 目标节点数据
   * @param { Object  } processData - 流程图的所有节点数据
   */
  static decreasePriority(data, processData) {
    // 分支节点数据 包含该分支所有的条件节点
    const prevNode = this.getPreviousNode(data.prevId, processData);
    const branchData = prevNode.conditionNodes;
    const index = branchData.findIndex(c => c.nodeId === data.nodeId);
    if (index < branchData.length - 1) {
      const lastNode = branchData[index + 1];
      if (lastNode.properties.isDefault) {
        // 默认节点不能修改优先级
        return;
      }
      // 和后一个数组项交换位置 Array.prototype.splice会返回包含被删除的项的集合（数组）
      lastNode.properties.priority = index;
      branchData[index].properties.priority = index + 1;
      branchData[index + 1] = branchData.splice(index, 1, branchData[index + 1])[0];
    }
  }
  /**
   * 当有其他条件节点设置条件后 检查并设置最后一个节点为默认节点
   * @param {Node} cNode  - 当前节点
   * @param {Node} processData - 整个流程图节点数据或父级节点数据
   */
  static setDefaultCondition(cNode, processData) {
    const DEFAULT_TEXT = '其他情况进入此流程';
    const conditions = this.getPreviousNode(cNode.prevId, processData).conditionNodes;
    const hasCondition = node => node.properties && (node.properties.initiator || !isEmptyArray(node.properties.conditions));
    const clearDefault = node => {
      node.properties.isDefault = false;
      node.content === DEFAULT_TEXT && (node.content = '请设置条件');
    };
    const setDefault = node => {
      node.properties.isDefault = true;
      node.content = DEFAULT_TEXT;
    };
    let count = 0;
    conditions.slice(0, -1).forEach(node => {
      hasCondition(node) && count++;
      clearDefault(node);
    });
    const lastNode = conditions[conditions.length - 1];
    count > 0 && !hasCondition(lastNode) ? setDefault(lastNode) : clearDefault(lastNode);
  }
  /**
   * 校验单个节点必填项完整性
   * @param {Node} node - 节点数据
   */
  static checkNode(node, _parent?) {
    let valid = true;
    const props = node.properties;
    this.isStartNode(node) && !props.formId && (valid = false);

    if (this.isConditionNode(node)) {
      if (!props.isDefault && isEmptyArray(props.conditions)) valid = false;
      if (props.conditionType == 1 && !props.swerveNode) valid = false;
    }

    this.isSubFlowNode(node) && (!props.flowId || (props.initiateType === 6 && isEmptyArray(props.initiator))) && (valid = false);

    this.isApproverNode(node) && (!props.assigneeType || props.assigneeType === 6) && isEmptyArray(props.approvers) && (valid = false);
    return valid;
  }
  /**
   * 判断所有节点是否信息完整
   * @param {Node} processData - 整个流程图数据
   * @returns {Boolean}
   */
  static checkAllNode(processData) {
    let valid = true;
    const loop = (node, callback, parent?) => {
      !this.checkNode(node, parent) && callback();
      if (node.childNode) loop(node.childNode, callback, parent);
      if (!isEmptyArray(node.conditionNodes)) {
        node.conditionNodes.forEach(n => loop(n, callback, node));
      }
    };
    loop(processData, () => (valid = false));
    return valid;
  }
}

/**
 * 添模拟数据
 */
export function getMockData() {
  const startNode = NodeUtils.createNode('start');
  startNode.childNode = NodeUtils.createNode('approver', startNode.nodeId);
  return startNode;
}

import type { FormProps, FormActionType, UseFormReturnType, FormSchema } from '../types/form';
import type { NamePath } from 'ant-design-vue/lib/form/interface';
import type { DynamicProps } from '/#/utils';
import { ref, onUnmounted, unref, nextTick, watch } from 'vue';
import { isProdMode } from '/@/utils/env';
import { error } from '/@/utils/log';
import { getDynamicProps } from '/@/utils';

export declare type ValidateFields = (nameList?: NamePath[]) => Promise<Recordable>;

type Props = Partial<DynamicProps<FormProps>>;

export function useForm(props?: Props): UseFormReturnType {
  const formRef = ref<Nullable<FormActionType>>(null);
  const loadedRef = ref<Nullable<boolean>>(false);

  async function getForm() {
    const form = unref(formRef);
    if (!form) {
      error('The form instance has not been obtained, please make sure that the form has been rendered when performing the form operation!');
    }
    await nextTick();
    return form as FormActionType;
  }

  function register(instance: FormActionType) {
    isProdMode() &&
      onUnmounted(() => {
        formRef.value = null;
        loadedRef.value = null;
      });
    if (unref(loadedRef) && isProdMode() && instance === unref(formRef)) return;

    formRef.value = instance;
    loadedRef.value = true;

    watch(
      () => props,
      () => {
        props && instance.setProps(getDynamicProps(props));
      },
      {
        immediate: true,
        deep: true,
      },
    );
  }

  const methods: FormActionType = {
    scrollToField: async (name: NamePath, options?: ScrollOptions | undefined) => {
      const form = await getForm();
      form.scrollToField(name, options);
    },
    setProps: async (formProps: Partial<FormProps>) => {
      const form = await getForm();
      form.setProps(formProps);
    },

    updateSchema: async (data: Partial<FormSchema> | Partial<FormSchema>[]) => {
      const form = await getForm();
      form.updateSchema(data);
    },

    resetSchema: async (data: Partial<FormSchema> | Partial<FormSchema>[]) => {
      const form = await getForm();
      form.resetSchema(data);
    },

    clearValidate: async (name?: string | string[]) => {
      const form = await getForm();
      form.clearValidate(name);
    },

    resetFields: async () => {
      getForm().then(async form => {
        await form.resetFields();
      });
    },

    removeSchemaByField: async (field: string | string[]) => {
      unref(formRef)?.removeSchemaByField(field);
    },

    // TODO promisify
    getFieldsValue: <T>() => {
      return unref(formRef)?.getFieldsValue() as T;
    },

    setFieldsValue: async <T extends Recordable<any>>(values: T) => {
      const form = await getForm();
      form.setFieldsValue<T>(values);
    },

    appendSchemaByField: async (schema: FormSchema | FormSchema[], prefixField: string | undefined, first: boolean) => {
      const form = await getForm();
      form.appendSchemaByField(schema, prefixField, first);
    },

    submit: async (): Promise<any> => {
      const form = await getForm();
      return form.submit();
    },

    validate: async (nameList?: NamePath[]): Promise<Recordable> => {
      const form = await getForm();
      return form.validate(nameList);
    },

    validateFields: async (nameList?: NamePath[]): Promise<Recordable> => {
      const form = await getForm();
      return form.validateFields(nameList);
    },
  };

  return [register, methods];
}

import type { ComputedRef, Ref } from 'vue';
import type { FormProps, FormSchema, FormActionType } from '../types/form';
import type { NamePath } from 'ant-design-vue/lib/form/interface';
import { unref, toRaw, nextTick } from 'vue';
import { isArray, isFunction, isObject, isString, isDef, isNullOrUnDef, isEmpty } from '/@/utils/is';
import { deepMerge } from '/@/utils';
import { dateItemType, handleInputNumberValue, defaultValueComponents, noFieldComponents } from '../helper';
import { cloneDeep, uniqBy } from 'lodash-es';
import { error } from '/@/utils/log';

interface UseFormActionContext {
  emit: EmitType;
  getProps: ComputedRef<FormProps>;
  getSchema: ComputedRef<FormSchema[]>;
  formModel: Recordable;
  defaultValueRef: Ref<Recordable>;
  fullValueRef: Ref<Recordable>;
  formElRef: Ref<FormActionType>;
  schemaRef: Ref<FormSchema[]>;
  handleFormValues: Fn;
  isInitedDefaultRef: Ref<boolean>;
}
export function useFormEvents({
  emit,
  getProps,
  formModel,
  getSchema,
  defaultValueRef,
  fullValueRef,
  formElRef,
  schemaRef,
  handleFormValues,
  isInitedDefaultRef,
}: UseFormActionContext) {
  async function resetFields(): Promise<void> {
    fullValueRef.value = {};
    const { resetFunc, submitOnReset } = unref(getProps);
    resetFunc && isFunction(resetFunc) && (await resetFunc());

    const formEl = unref(formElRef);
    if (!formEl) return;

    Object.keys(formModel).forEach(key => {
      const schema = unref(getSchema).find(item => item.field === key);
      const isInput = schema?.component && defaultValueComponents.includes(schema.component);
      const defaultValue = cloneDeep(defaultValueRef.value[key]);
      formModel[key] = isInput ? defaultValue || '' : defaultValue;
    });
    nextTick(() => clearValidate());

    emit('reset', toRaw(formModel));
    submitOnReset && handleSubmit();
  }

  /**
   * @description: Set form value
   */
  async function setFieldsValue(values: Recordable): Promise<void> {
    fullValueRef.value = { ...fullValueRef.value, ...values };
    const fields = unref(getSchema)
      .map(item => item.field)
      .filter(Boolean);

    // key 支持 a.b.c 的嵌套写法
    const delimiter = '.';
    const nestKeyArray = fields.filter(item => item.indexOf(delimiter) >= 0);

    const validKeys: string[] = [];
    Object.keys(values).forEach(key => {
      const schema = unref(getSchema).find(item => item.field === key);
      let value = values[key];

      const hasKey = Reflect.has(values, key);

      value = handleInputNumberValue(schema?.component, value);
      // 0| '' is allow
      if (hasKey && fields.includes(key)) {
        formModel[key] = value;
        validKeys.push(key);
      } else {
        nestKeyArray.forEach((nestKey: string) => {
          try {
            const value = nestKey.split('.').reduce((out, item) => out[item], values);
            if (isDef(value)) {
              formModel[nestKey] = value;
              validKeys.push(nestKey);
            }
          } catch (e) {
            // key not exist
            if (isDef(defaultValueRef.value[nestKey])) {
              formModel[nestKey] = cloneDeep(defaultValueRef.value[nestKey]);
            }
          }
        });
      }
    });
    validateFields(validKeys).catch(_ => {});
  }
  /**
   * @description: Delete based on field name
   */
  async function removeSchemaByField(fields: string | string[]): Promise<void> {
    const schemaList: FormSchema[] = cloneDeep(unref(getSchema));
    if (!fields) {
      return;
    }

    let fieldList: string[] = isString(fields) ? [fields] : fields;
    if (isString(fields)) {
      fieldList = [fields];
    }
    for (const field of fieldList) {
      _removeSchemaByField(field, schemaList);
    }
    schemaRef.value = schemaList;
  }

  /**
   * @description: Delete based on field name
   */
  function _removeSchemaByField(field: string, schemaList: FormSchema[]): void {
    if (isString(field)) {
      const index = schemaList.findIndex(schema => schema.field === field);
      if (index !== -1) {
        delete formModel[field];
        schemaList.splice(index, 1);
      }
    }
  }

  /**
   * @description: Insert after a certain field, if not insert the last
   */
  async function appendSchemaByField(schema: FormSchema | FormSchema[], prefixField?: string, first = false) {
    const schemaList: FormSchema[] = cloneDeep(unref(getSchema));
    const addSchemaIds: string[] = Array.isArray(schema) ? schema.map(item => item.field) : [schema.field];
    if (schemaList.find(item => addSchemaIds.includes(item.field))) {
      error('There are schemas that have already been added');
      return;
    }
    const index = schemaList.findIndex(schema => schema.field === prefixField);
    const _schemaList = isObject(schema) ? [schema as FormSchema] : (schema as FormSchema[]);
    if (!prefixField || index === -1 || first) {
      first ? schemaList.unshift(..._schemaList) : schemaList.push(..._schemaList);
      schemaRef.value = schemaList;
      _setDefaultValue(schema);
      return;
    }
    if (index !== -1) {
      schemaList.splice(index + 1, 0, ..._schemaList);
    }
    _setDefaultValue(schema);

    schemaRef.value = schemaList;
  }

  async function resetSchema(data: Partial<FormSchema> | Partial<FormSchema>[]) {
    let updateData: Partial<FormSchema>[] = [];
    if (isObject(data)) {
      updateData.push(data as FormSchema);
    }
    if (isArray(data)) {
      updateData = [...data];
    }

    const hasField = updateData.every(item => noFieldComponents.includes(item.component as string) || (Reflect.has(item, 'field') && item.field));

    if (!hasField) {
      error('All children of the form Schema array that need to be updated must contain the `field` field');
      return;
    }
    schemaRef.value = updateData as FormSchema[];
  }

  async function updateSchema(data: Partial<FormSchema> | Partial<FormSchema>[]) {
    let updateData: Partial<FormSchema>[] = [];
    if (isObject(data)) {
      updateData.push(data as FormSchema);
    }
    if (isArray(data)) {
      updateData = [...data];
    }

    const hasField = updateData.every(item => noFieldComponents.includes(item.component as string) || (Reflect.has(item, 'field') && item.field));

    if (!hasField) {
      error('All children of the form Schema array that need to be updated must contain the `field` field');
      return;
    }
    const schema: FormSchema[] = [];
    unref(getSchema).forEach(val => {
      let _val;
      updateData.forEach(item => {
        if (val.field === item.field) {
          _val = item;
        }
      });
      if (_val !== undefined && val.field === _val.field) {
        const newSchema = deepMerge(val, _val);
        if (Reflect.has(_val, 'componentProps') && Reflect.has(_val.componentProps, 'options')) {
          newSchema.componentProps.options = _val.componentProps.options;
        }
        schema.push(newSchema as FormSchema);
      } else {
        schema.push(val);
      }
    });
    _setDefaultValue(schema);

    schemaRef.value = uniqBy(schema, 'field');
    isInitedDefaultRef.value = false;
  }

  function _setDefaultValue(data: FormSchema | FormSchema[]) {
    let schemas: FormSchema[] = [];
    if (isObject(data)) {
      schemas.push(data as FormSchema);
    }
    if (isArray(data)) {
      schemas = [...data];
    }

    const obj: Recordable = {};
    const currentFieldsValue = getFieldsValue();
    schemas.forEach(item => {
      if (
        !noFieldComponents.includes(item.component) &&
        Reflect.has(item, 'field') &&
        item.field &&
        !isNullOrUnDef(item.defaultValue) &&
        (!(item.field in currentFieldsValue) || isNullOrUnDef(currentFieldsValue[item.field]) || isEmpty(currentFieldsValue[item.field]))
      ) {
        obj[item.field] = item.defaultValue;
      }
    });
    setFieldsValue(obj);
  }

  function getFieldsValue(): Recordable {
    const formEl = unref(formElRef);
    if (!formEl) return {};
    return handleFormValues(toRaw(unref(formModel)));
  }

  /**
   * @description: Is it time
   */
  function itemIsDateType(key: string) {
    return unref(getSchema).some(item => {
      return item.field === key ? dateItemType.includes(item.component) : false;
    });
  }

  async function validateFields(nameList?: NamePath[] | undefined) {
    return unref(formElRef)?.validateFields(nameList);
  }

  async function validate(nameList?: NamePath[] | undefined) {
    try {
      const values = await unref(formElRef)?.validate(nameList);
      return { ...fullValueRef.value, ...values };
    } catch (error: any) {
      if (!error.errorFields.length) {
        return { ...fullValueRef.value, ...error.values };
      } else {
        return false;
      }
    }
  }

  async function clearValidate(name?: string | string[]) {
    await unref(formElRef)?.clearValidate(name);
  }

  async function scrollToField(name: NamePath, options?: ScrollOptions | undefined) {
    await unref(formElRef)?.scrollToField(name, options);
  }

  /**
   * @description: Form submission
   */
  async function handleSubmit(e?: Event): Promise<void> {
    e && e.preventDefault();
    const { submitFunc } = unref(getProps);
    if (submitFunc && isFunction(submitFunc)) {
      await submitFunc();
      return;
    }
    const formEl = unref(formElRef);
    if (!formEl) return;
    try {
      const values = await validate();
      const res = handleFormValues(values);
      emit('submit', res);
    } catch (error: any) {
      if (error?.outOfDate === false && error?.errorFields) {
        return;
      }
      throw new Error(error);
    }
  }

  return {
    handleSubmit,
    clearValidate,
    validate,
    validateFields,
    getFieldsValue,
    updateSchema,
    resetSchema,
    appendSchemaByField,
    removeSchemaByField,
    resetFields,
    setFieldsValue,
    scrollToField,
    itemIsDateType,
  };
}

import { isArray, isFunction, isObject, isString, isNullOrUnDef } from '/@/utils/is';
import { dateUtil } from '/@/utils/dateUtil';
import { unref } from 'vue';
import type { Ref, ComputedRef } from 'vue';
import type { FormProps, FormSchema } from '../types/form';
import { cloneDeep, set } from 'lodash-es';

interface UseFormValuesContext {
  defaultValueRef: Ref<any>;
  getSchema: ComputedRef<FormSchema[]>;
  getProps: ComputedRef<FormProps>;
  formModel: Recordable;
}

/**
 * @desription deconstruct array-link key. This method will mutate the target.
 */
function tryDeconstructArray(key: string, value: any, target: Recordable) {
  const pattern = /^\[(.+)\]$/;
  if (pattern.test(key)) {
    const match = key.match(pattern);
    if (match && match[1]) {
      const keys = match[1].split(',');
      value = Array.isArray(value) ? value : [value];
      keys.forEach((k, index) => {
        set(target, k.trim(), value[index]);
      });
      return true;
    }
  }
}

/**
 * @desription deconstruct object-link key. This method will mutate the target.
 */
function tryDeconstructObject(key: string, value: any, target: Recordable) {
  const pattern = /^\{(.+)\}$/;
  if (pattern.test(key)) {
    const match = key.match(pattern);
    if (match && match[1]) {
      const keys = match[1].split(',');
      value = isObject(value) ? value : {};
      keys.forEach(k => {
        set(target, k.trim(), value[k.trim()]);
      });
      return true;
    }
  }
}

export function useFormValues({ defaultValueRef, getSchema, formModel, getProps }: UseFormValuesContext) {
  // Processing form values
  function handleFormValues(values: Recordable) {
    if (!isObject(values)) {
      return {};
    }
    const res: Recordable = {};
    for (const item of Object.entries(values)) {
      let [, value] = item;
      const [key] = item;
      if (!key || (isArray(value) && value.length === 0) || isFunction(value)) {
        continue;
      }
      const transformDateFunc = unref(getProps).transformDateFunc;
      if (isObject(value)) {
        value = transformDateFunc?.(value);
      }

      if (isArray(value) && value[0]?.format && value[1]?.format) {
        value = value.map(item => transformDateFunc?.(item));
      }
      // Remove spaces
      if (isString(value)) {
        // remove params from URL
        if (value === '') {
          value = undefined;
        } else {
          value = value.trim();
        }
      }
      if (!tryDeconstructArray(key, value, res) && !tryDeconstructObject(key, value, res)) {
        // 没有解构成功的，按原样赋值
        set(res, key, value);
      }
    }
    return handleRangeTimeValue(res);
  }

  /**
   * @description: Processing time interval parameters
   */
  function handleRangeTimeValue(values: Recordable) {
    const fieldMapToTime = unref(getProps).fieldMapToTime;

    if (!fieldMapToTime || !Array.isArray(fieldMapToTime)) {
      return values;
    }

    for (const [field, [startTimeKey, endTimeKey], format = ''] of fieldMapToTime) {
      if (!field || !startTimeKey || !endTimeKey) {
        continue;
      }
      // If the value to be converted is empty, remove the field
      if (!values[field]) {
        Reflect.deleteProperty(values, field);
        continue;
      }

      const [startTime, endTime]: string[] = values[field];
      if (format) {
        const [startTimeFormat, endTimeFormat] = Array.isArray(format) ? format : [format, format];
        values[startTimeKey] = dateUtil(startTime).format(startTimeFormat);
        values[endTimeKey] = dateUtil(endTime).format(endTimeFormat);
      } else {
        values[startTimeKey] = startTime;
        values[endTimeKey] = endTime;
      }

      Reflect.deleteProperty(values, field);
    }
    return values;
  }

  function initDefault() {
    const schemas = unref(getSchema);
    const obj: Recordable = {};
    schemas.forEach(item => {
      const { defaultValue } = item;
      if (!isNullOrUnDef(defaultValue)) {
        obj[item.field] = defaultValue;

        if (formModel[item.field] === undefined) {
          formModel[item.field] = defaultValue;
        }
      }
    });
    defaultValueRef.value = cloneDeep(obj);
  }

  return { handleFormValues, initDefault };
}

import type { NamePath } from 'ant-design-vue/lib/form/interface';
import type { ColProps } from 'ant-design-vue/lib/grid/Col';
import type { HTMLAttributes, VNodeChild } from 'vue';

export interface FormItem {
  /**
   * Used with label, whether to display : after label text.
   * @default true
   * @type boolean
   */
  colon?: boolean;

  /**
   * The extra prompt message. It is similar to help. Usage example: to display error message and prompt message at the same time.
   * @type any (string | slot)
   */
  extra?: string | VNodeChild | JSX.Element;

  /**
   * Used with validateStatus, this option specifies the validation status icon. Recommended to be used only with Input.
   * @default false
   * @type boolean
   */
  hasFeedback?: boolean;

  /**
   * The prompt message. If not provided, the prompt message will be generated by the validation rule.
   * @type any (string | slot)
   */
  help?: string | VNodeChild | JSX.Element;

  /**
   * Label test
   * @type any (string | slot)
   */
  label?: string | VNodeChild | JSX.Element;

  /**
   * The layout of label. You can set span offset to something like {span: 3, offset: 12} or sm: {span: 3, offset: 12} same as with <Col>
   * @type Col
   */
  labelCol?: ColProps & HTMLAttributes;

  /**
   * Whether provided or not, it will be generated by the validation rule.
   * @default false
   * @type boolean
   */
  required?: boolean;

  /**
   * The validation status. If not provided, it will be generated by validation rule. options: 'success' 'warning' 'error' 'validating'
   * @type string
   */
  validateStatus?: '' | 'success' | 'warning' | 'error' | 'validating';

  /**
   * The layout for input controls, same as labelCol
   * @type Col
   */
  wrapperCol?: ColProps;
  /**
   * Set sub label htmlFor.
   */
  htmlFor?: string;
  /**
   * text align of label
   */
  labelAlign?: 'left' | 'right';
  /**
   * a key of model. In the setting of validate and resetFields method, the attribute is required
   */
  name?: NamePath;
  /**
   * validation rules of form
   */
  rules?: object | object[];
  /**
   * Whether to automatically associate form fields. In most cases, you can setting automatic association.
   * If the conditions for automatic association are not met, you can manually associate them. See the notes below.
   */
  autoLink?: boolean;
  /**
   * Whether stop validate on first rule of error for this field.
   */
  validateFirst?: boolean;
  /**
   * When to validate the value of children node
   */
  validateTrigger?: string | string[] | false;
}

/**
 * 将字符串形式的正则表达式安全解析为 RegExp 对象
 * 支持 "/pattern/flags" 格式，避免使用 eval()
 */
export function safeParseRegex(pattern: string | RegExp): RegExp | null {
  if (pattern instanceof RegExp) return pattern;
  if (typeof pattern !== 'string') return null;
  const match = pattern.match(/^\/(.+)\/([gimsuyd]*)$/);
  if (!match) return null;
  try {
    return new RegExp(match[1], match[2]);
  } catch {
    return null;
  }
}

/**
 * 安全检测字符串是否为有效的正则表达式格式
 * 替代 Object.prototype.toString.call(eval(val)) === '[object RegExp]'
 */
export function isValidRegex(val: string): boolean {
  return safeParseRegex(val) !== null;
}

import { defineComponent, h, ref, unref, onMounted, getCurrentInstance } from 'vue';
import { cloneDeep, upperFirst } from 'lodash-es';
import { componentMap } from '/@/components/Form/src/componentMap';
import type { ComponentType } from '/@/components/Form/src/types/index';
import { getRealProps } from './transform';

export default defineComponent({
  props: {
    conf: {
      type: Object,
      required: true,
    },
    formData: {
      type: Object,
      default: () => {},
    },
    size: {
      type: String,
      default: 'default',
    },
    relations: Object,
  },
  setup(props, { emit, expose }) {
    const tableRef = ref<any>(null);

    expose({ tableRef });
    function buildVModel(dataObject, defaultValue) {
      dataObject.value = defaultValue;
      const obj = dataObject.on ?? {};
      obj['update:value'] = val => {
        emit('update:value', val);
      };
      dataObject.on = obj;
    }

    function emitEvents(confClone) {
      ['on', 'nativeOn'].forEach(attr => {
        const eventKeyList = Object.keys(confClone[attr] || {});
        eventKeyList.forEach(key => {
          if (typeof key === 'string') {
            confClone[attr][key] = (...arg) => emit(key, arg);
          }
        });
      });
    }

    function buildDataObject(confClone, dataObject, formData) {
      const jnpfKey = confClone.__config__.jnpfKey;
      Object.keys(confClone).forEach(key => {
        const val = confClone[key];
        if (key === '__vModel__') {
          buildVModel(dataObject, confClone.__config__.defaultValue);
        } else if (dataObject[key] !== undefined) {
          if (dataObject[key] === null || dataObject[key] instanceof RegExp || ['boolean', 'string', 'number', 'function'].includes(typeof dataObject[key])) {
            dataObject[key] = val;
          } else if (Array.isArray(dataObject[key])) {
            dataObject[key] = [...dataObject[key], ...val];
          } else {
            dataObject[key] = { ...dataObject[key], ...val };
          }
        } else {
          dataObject[key] = val;
        }
      });
      if (['calculate', 'table', 'barcode', 'qrcode', 'popupSelect', 'popupTableSelect', 'autoComplete'].includes(jnpfKey)) {
        dataObject['formData'] = formData;
      }
      if (['table'].includes(jnpfKey)) {
        dataObject['relations'] = props.relations;
        dataObject['vModel'] = confClone.__vModel__;
        dataObject['ref'] = 'tableRef';
      }
      if (['relationForm', 'popupSelect'].includes(jnpfKey)) {
        dataObject['field'] = confClone.__config__.tableName
          ? confClone.__vModel__ + '_jnpfTable_' + confClone.__config__.tableName + (confClone.__config__.isSubTable ? '0' : '1')
          : confClone.__vModel__;
      }
      // 清理属性
      clearAttrs(dataObject);
    }

    function clearAttrs(dataObject) {
      delete dataObject.__config__;
      delete dataObject.__slot__;
      delete dataObject.__methods__;
      delete dataObject.on;
    }
    onMounted(() => {
      const instance = getCurrentInstance();
      tableRef.value = unref(instance?.refs?.tableRef);
    });

    return () => {
      const dataObject = {};
      const confClone = cloneDeep(props.conf);
      // 将字符串类型的事件，发送为消息
      emitEvents(confClone);
      // 将json表单配置转化为vue render可以识别的数据对象(dataObject)
      buildDataObject(confClone, dataObject, props.formData);
      const jnpfKey = upperFirst(props.conf.__config__.jnpfKey) === 'Table' ? 'InputTable' : upperFirst(props.conf.__config__.jnpfKey);
      const Comp = componentMap.get(jnpfKey as ComponentType) as ReturnType<typeof defineComponent>;
      if (!Comp) return null;
      const realDataObject = getRealProps(dataObject, props.conf.__config__.jnpfKey);
      return h(Comp, realDataObject as any);
    };
  },
});

import { cloneDeep, upperFirst, lowerFirst } from 'lodash-es';
import { useInputList, useDateList, useSelectList } from '/@/components/FormGenerator/src/helper/config';
import { safeParseRegex } from '/@/components/FormGenerator/src/helper/regexp';

export const getRealProps = (data, jnpfKey) => {
  if (Reflect.has(data, 'clearable')) {
    data.allowClear = data.clearable;
    delete data.clearable;
  }
  if (Reflect.has(data, 'filterable')) {
    data.showSearch = data.filterable;
    delete data.filterable;
  }
  if (Reflect.has(data, 'props')) {
    data.fieldNames = data.props;
    delete data.props;
  }
  if (jnpfKey === 'switch') {
    data.checkedValue = data.activeValue;
    data.unCheckedValue = data.inactiveValue;
    delete data.activeValue;
    delete data.inactiveValue;
  }
  if (jnpfKey === 'card') {
    data.title = data.header;
    delete data.title;
    data.hoverable = data.shadow === 'hover';
    delete data.shadow;
  }
  return data;
};
export const getFormSchemaItem = data => {
  const item = getRealProps(data, data.__config__.jnpfKey);
  const componentProps = cloneDeep(item);
  // delete componentProps.__config__;
  delete componentProps.on;
  delete componentProps.__vModel__;
  // if (Reflect.has(item.__config__, 'children')) {
  //   componentProps.children = item.__config__.children;
  // }

  const rules: any[] = [];
  const regList = item.__config__.regList;
  if (regList) {
    for (let i = 0; i < regList.length; i++) {
      const p = regList[i].pattern;
      rules.push({
        pattern: p ? safeParseRegex(p) : undefined,
        message: regList[i].message,
        trigger: item.__config__.trigger,
      });
    }
  }

  const schema = {
    field: item.prop,
    label: item.label,
    defaultValue: item.__config__.defaultValue,
    component: upperFirst(item.__config__.jnpfKey),
    componentProps,
    labelWidth: item.__config__.labelWidth || null,
    required: item.__config__.required || false,
    colProps: { span: item.__config__.span || 24 },
    className: item.__config__.className,
    value: item.value,
    rules,
    __config__: item.__config__,
  };
  return schema;
};
export const getFormSchemas = (list: any[]) => {
  const schemas: any[] = [];
  const list1: any[] = [];
  const loop = list => {
    for (let i = 0; i < list.length; i++) {
      const schema = getFormSchemaItem(list[i]);
      list1.push({ ...list[i], schema });
      schemas.push(schema);
    }
  };
  loop(list);
  return schemas;
};
export const getFormConfig = formConf => {
  return {
    labelWidth: formConf.labelWidth,
    schemas: getFormSchemas(formConf.fields),
    layout: formConf.labelPosition === 'top' ? 'vertical' : 'horizontal',
    labelAlign: formConf.labelPosition === 'right' ? 'right' : 'left',
    disabled: formConf.disabled,
  };
};
export const getSearchFormSchemas = (list: any[]) => {
  const schemas: any[] = getFormSchemas(list);
  for (let i = 0; i < schemas.length; i++) {
    const e = schemas[i];
    const delList = ['className', 'colProps', 'labelWidth', 'required', 'rules', 'defaultValue'];
    for (let i = 0; i < delList.length; i++) {
      delete e[delList[i]];
    }
    if (useInputList.includes(lowerFirst(e.component))) {
      e.component = 'Input';
      e.componentProps = { placeholder: '请输入' + e.label, allowClear: true };
    }
    if (useDateList.includes(lowerFirst(e.component))) {
      e.component = 'DateRange';
      e.componentProps = { format: 'YYYY-MM-DD HH:mm:ss' };
    }
    if (e.component === 'Switch') {
      e.componentProps = {
        checkedValue: e.componentProps.checkedValue,
        unCheckedValue: e.componentProps.unCheckedValue,
      };
    }
    if (useSelectList.includes(lowerFirst(e.component))) {
      e.component = 'Select';
      e.componentProps = {
        options: e.componentProps.options,
        showSearch: true,
        multiple: e.componentProps.searchMultiple || false,
        fieldNames: e.componentProps.fieldNames,
        placeholder: '请选择' + e.label,
      };
    }
    if (['InputNumber', 'Calculate', 'Rate', 'Slider'].includes(e.component)) {
      let precision = e.componentProps.precision;
      if ((!e.componentProps.precision && e.component === 'Calculate') || e.component === 'Slider') precision = 0;
      if (e.component === 'Rate') precision = e.componentProps.allowHalf ? 1 : 0;
      if (!e.__config__.isFromParam) e.component = 'NumberRange';
      e.componentProps = { precision };
    }
    if (e.component === 'Cascader') {
      e.componentProps = {
        options: e.componentProps.options,
        showSearch: true,
        multiple: e.componentProps.searchMultiple || false,
        fieldNames: e.componentProps.fieldNames,
        showAllLevels: e.componentProps.showAllLevels,
        placeholder: '请选择' + e.label,
      };
    }
    if (e.component === 'TimePicker') {
      e.component = 'TimeRange';
      e.componentProps = { format: e.componentProps.format };
    }
    if (e.component === 'DatePicker') {
      if (!e.__config__.isFromParam) e.component = 'DateRange';
      e.componentProps = { format: e.componentProps.format || 'yyyy-MM-dd HH:mm:ss' };
    }
    if (e.component === 'AreaSelect') {
      e.componentProps = { placeholder: '请选择' + e.label, level: e.componentProps.level };
    }
    if (e.component === 'TreeSelect') {
      e.componentProps = {
        options: e.componentProps.options,
        showSearch: true,
        multiple: e.componentProps.searchMultiple || false,
        fieldNames: e.componentProps.fieldNames,
        placeholder: '请选择' + e.label,
      };
    }
    if (['CreateUser', 'ModifyUser'].includes(e.component)) {
      e.component = 'UserSelect';
      e.componentProps = { placeholder: '请选择' + e.label };
    }
    if (e.component === 'CurrOrganize') {
      e.component = 'OrganizeSelect';
      e.componentProps = { multiple: e.componentProps.searchMultiple || false, placeholder: '请选择' + e.label };
    }
    if (e.component === 'CurrPosition') {
      e.component = 'PosSelect';
      e.componentProps = { multiple: e.componentProps.searchMultiple || false, placeholder: '请选择' + e.label };
    }
    if (['OrganizeSelect', 'DepSelect', 'PosSelect', 'RoleSelect', 'GroupSelect', 'UsersSelect'].includes(e.component)) {
      e.componentProps = {
        selectType: e.componentProps.selectType,
        ableIds: e.componentProps.ableIds,
        multiple: e.componentProps.searchMultiple || false,
        placeholder: '请选择' + e.label,
      };
    }
    if (e.component === 'UserSelect') {
      e.componentProps = {
        selectType: e.componentProps.selectType != 'all' && e.componentProps.selectType != 'custom' ? 'all' : e.componentProps.selectType,
        ableIds: e.componentProps.ableIds,
        multiple: e.componentProps.searchMultiple || false,
        placeholder: '请选择' + e.label,
      };
    }
    if (e.component === 'AutoComplete') {
      e.componentProps = {
        total: e.componentProps.total,
        interfaceId: e.componentProps.interfaceId,
        relationField: e.componentProps.relationField,
        templateJson: e.componentProps.templateJson,
        placeholder: '请输入' + e.label,
      };
    }
  }
  if (list.some(o => o.isKeyword)) {
    const keywordItem = {
      field: 'jnpfKeyword',
      label: '关键词',
      component: 'Input',
      componentProps: { placeholder: '请输入关键词', allowClear: true },
      value: undefined,
      __config__: { jnpfKey: 'input' },
    };
    schemas.unshift(keywordItem);
  }
  return schemas;
};

/**
 * 将用户输入的连续单个数字合并为一个数
 * @param {Array} expressions - 记录计算表达式的数组
 * @returns {Array} 新的数组
 */
export const mergeNumberOfExps = expressions => {
  const res: any = [];
  const isNumChar = n => /^[\d|\.]$/.test(n);
  for (let i = 0; i < expressions.length; i++) {
    if (i > 0 && isNumChar(expressions[i - 1]) && isNumChar(expressions[i])) {
      res[res.length - 1] += expressions[i];
      continue;
    }
    res.push(expressions[i]);
  }
  return res;
};
/**
 * 校验表达式是否符合计算法则
 * @param {Array} expressions - 合并数字后的表达式数组
 * @returns {Boolean}
 */
export const validExp = (expressions, mergeNum = true) => {
  const temp = mergeNum ? mergeNumberOfExps(expressions) : expressions;
  const arr = temp.filter(t => !'()'.includes(t));
  // 去括号后 length应该为奇数  并且第一个字符和最后一个字符应该为数字而非计算符号
  if (temp.length % 2 === 0 || arr.length % 2 === 0 || Number.isNaN(+arr[0]) || Number.isNaN(+arr[arr.length - 1])) {
    return false;
  }
  for (let i = 0; i < arr.length - 1; i += 2) {
    if (typeof +arr[i] !== 'number' || !Number.isNaN(+arr[i + 1])) return false;
  }
  return true;
};
/**
 * 中缀转后缀（逆波兰 Reverse Polish Notation）
 * @param {Array} exps - 中缀表达式数组
 */
export const toRPN = exps => {
  const s1: any[] = []; // 符号栈
  const s2: any[] = []; // 输出栈
  const getTopVal = stack => (stack.length > 0 ? stack[stack.length - 1] : null);
  const levelCompare = (c1, c2) => {
    const getIndex = c => ['+-', '×÷', '()'].findIndex(t => t.includes(c));
    return getIndex(c1) - getIndex(c2);
  };
  exps.forEach(t => {
    if (typeof t === 'string' && Number.isNaN(Number(t))) {
      // 是符号
      if (t === '(') {
        s1.push(t);
      } else if (t === ')') {
        let popVal;
        do {
          popVal = s1.pop();
          popVal !== '(' && s2.push(popVal);
        } while (s1.length && popVal !== '(');
      } else {
        let topVal = getTopVal(s1);
        if (!topVal) {
          // s1 为空 直接push
          s1.push(t);
        } else {
          while (topVal && topVal !== '(' && levelCompare(topVal, t) >= 0) {
            // 优先级 >= t 弹出到s2
            s2.push(s1.pop());
            topVal = getTopVal(s1);
          }
          s1.push(t);
        }
      }
      return;
    }
    s2.push(t); // 数字直接入栈
  });
  while (s1.length) {
    s2.push(s1.pop());
  }
  return s2;
};
/**
 * 计算后缀表达式的值
 * @param {Array} rpnExps - 后缀表达式
 */
export const calcRPN = rpnExps => {
  rpnExps = rpnExps.concat();
  const calc = (x, y, type) => {
    const a1 = Number(x),
      a2 = Number(y);
    switch (type) {
      case '+':
        return a1 + a2;
      case '-':
        return a1 - a2;
      case '×':
        return a1 * a2;
      case '÷':
        return a1 / a2;
    }
  };
  for (let i = 2; i < rpnExps.length; i++) {
    if ('+-×÷'.includes(rpnExps[i])) {
      const val = calc(rpnExps[i - 2], rpnExps[i - 1], rpnExps[i]);
      rpnExps.splice(i - 2, 3, val);
      i = i - 2;
    }
  }
  return rpnExps[0];
};

import { inject, computed, unref } from 'vue';
import { buildBitUUID } from '/@/utils/uuid';
import { getDictionaryDataSelector } from '/@/api/systemData/dictionary';
import { getDataInterfaceRes } from '/@/api/systemData/dataInterface';
import { noAllowRelationList, noAllowSelectList } from '/@/components/FormGenerator/src/helper/config';
import { getParamList } from '/@/utils/jnpf';

export function useDynamic(activeData, initFieldData?) {
  const dataTypeOptions = [
    { id: 'static', fullName: '静态数据' },
    { id: 'dictionary', fullName: '数据字典' },
    { id: 'dynamic', fullName: '远端数据' },
  ];
  const valueOptions = [
    { id: 'id', fullName: 'id' },
    { id: 'enCode', fullName: 'enCode' },
  ];
  const sizeOptions = [
    { id: 'large', fullName: '较大' },
    { id: 'default', fullName: '中等' },
    { id: 'small', fullName: '较小' },
  ];
  const optionTypeOptions = [
    { id: 'default', fullName: '默认' },
    { id: 'button', fullName: '按钮' },
  ];
  const getShowType: (() => string | undefined) | undefined = inject('getShowType');
  const showType = computed(() => (getShowType as () => string | undefined)());
  const getDrawingList: (() => any[]) | undefined = inject('getDrawingList');
  const drawingList = computed(() => (getDrawingList as () => any[])());
  const defaultValue = computed(() => {
    if (activeData.__config__.jnpfKey === 'checkbox' || activeData.__config__.jnpfKey === 'cascader' || activeData.multiple) return [];
    return '';
  });
  const formFieldsOptions = computed(() => {
    const list: any[] = [];
    const loop = (data, parent?) => {
      if (!data) return;
      if (data.__config__ && isIncludesTable(data) && data.__config__.children && Array.isArray(data.__config__.children)) {
        loop(data.__config__.children, data);
      }
      if (Array.isArray(data)) data.forEach(d => loop(d, parent));
      if (data.__vModel__ && !noAllowRelationList.includes(data.__config__.jnpfKey) && data.__vModel__ !== activeData.__vModel__) {
        const isTableChild = parent && parent.__config__ && parent.__config__.jnpfKey === 'table';
        list.push({
          id: isTableChild ? parent.__vModel__ + '-' + data.__vModel__ : data.__vModel__,
          fullName: isTableChild ? parent.__config__.label + '-' + data.__config__.label : data.__config__.label,
          ...data,
          disabled: false,
        });
      }
    };
    loop(unref(drawingList));
    return list;
  });

  const formFieldsSelectOptions = computed(() => {
    const list: any[] = [];
    const loop = (data, parent?) => {
      if (!data) return;
      if (data.__config__ && isIncludesTable(data) && data.__config__.children && Array.isArray(data.__config__.children)) {
        loop(data.__config__.children, data);
      }
      if (Array.isArray(data)) data.forEach(d => loop(d, parent));
      if (data.__vModel__ && !noAllowSelectList.includes(data.__config__.jnpfKey) && data.__vModel__ !== activeData.__vModel__) {
        const isTableChild = parent && parent.__config__ && parent.__config__.jnpfKey === 'table';
        list.push({
          id: isTableChild ? parent.__vModel__ + '-' + data.__vModel__ : data.__vModel__,
          fullName: isTableChild ? parent.__config__.label + '-' + data.__config__.label : data.__config__.label,
          ...data,
          disabled: false,
        });
      }
    };
    loop(unref(drawingList));
    return list;
  });

  const isIncludesTable = data => {
    if ((!data.__config__.layout || data.__config__.layout === 'rowFormItem') && data.__config__.jnpfKey !== 'table') return true;
    if (activeData.__config__.isSubTable) return activeData.__config__.parentVModel === data.__vModel__;
    return data.__config__.jnpfKey !== 'table';
  };

  const onDataTypeChange = () => {
    activeData.__config__.defaultValue = unref(defaultValue);
    activeData.options = [];
    activeData.props.value = 'id';
    activeData.props.label = 'fullName';
    if (Reflect.has(activeData.props, 'children')) activeData.props.children = 'children';
    activeData.__config__.dictionaryType = '';
    activeData.__config__.propsUrl = '';
    activeData.__config__.propsName = '';
    activeData.__config__.templateJson = [];
  };
  const onDictionaryTypeChange = val => {
    activeData.__config__.defaultValue = unref(defaultValue);
    if (!val) return (activeData.options = []);
    getDictionaryDataSelector(val)
      .then(res => {
        activeData.options = res.data.list;
      })
      .catch(() => {
        activeData.options = [];
      });
  };
  const onPropsUrlChange = (val, row) => {
    activeData.__config__.defaultValue = unref(defaultValue);
    if (!val) {
      activeData.__config__.propsUrl = '';
      activeData.__config__.propsName = '';
      activeData.__config__.templateJson = [];
      activeData.options = [];
      initFieldData && initFieldData();
      return;
    }
    if (activeData.__config__.propsUrl === val) return;
    const list = row.parameterJson ? JSON.parse(row.parameterJson) : [];
    activeData.__config__.propsUrl = val;
    activeData.__config__.propsName = row.fullName;
    activeData.__config__.templateJson = list.map(o => ({ ...o, relationField: '', sourceType: 1 }));
    const query = { paramList: getParamList(activeData.__config__.templateJson) };
    getDataInterfaceRes(val, query)
      .then(res => {
        activeData.options = Array.isArray(res.data) ? res.data : [];
        initFieldData && initFieldData();
      })
      .catch(() => {
        activeData.__config__.propsUrl = '';
        activeData.__config__.propsName = '';
        activeData.__config__.templateJson = [];
        activeData.options = [];
        initFieldData && initFieldData();
      });
  };
  const onRelationFieldChange = (val, row) => {
    if (!val) return (row.jnpfKey = '');
    const list = unref(formFieldsOptions).filter(o => o.id === val);
    if (!list.length) return (row.jnpfKey = '');
    const item = list[0];
    row.jnpfKey = item.__config__.jnpfKey;
  };
  const onMultipleChange = val => {
    activeData.__config__.defaultValue = val ? [] : '';
  };
  const addSelectItem = () => {
    const uuid = buildBitUUID();
    activeData.options.push({
      fullName: '选项' + uuid,
      id: uuid,
    });
  };
  const onBatchOperateConfirm = options => {
    activeData.options = options;
  };

  return {
    showType,
    onDataTypeChange,
    onDictionaryTypeChange,
    onPropsUrlChange,
    formFieldsOptions,
    formFieldsSelectOptions,
    onRelationFieldChange,
    sizeOptions,
    optionTypeOptions,
    dataTypeOptions,
    valueOptions,
    addSelectItem,
    onMultipleChange,
    onBatchOperateConfirm,
  };
}

import { useDebounceFn } from '@vueuse/core';
import { getDataInterfaceInfo } from '/@/api/systemData/dataInterface';
import { reactive, toRefs } from 'vue';

export function useField(activeData) {
  interface State {
    options: any[];
    allOptions: any[];
  }

  const state = reactive<State>({
    options: [],
    allOptions: [],
  });
  const { options, allOptions } = toRefs(state);
  const debounceOnSearch = useDebounceFn(onSearch, 300);

  function onSearch(searchText: string) {
    state.options = state.allOptions.filter(o => o.value.toLowerCase().indexOf(searchText.toLowerCase()) !== -1);
  }
  function onFocus(searchText) {
    onSearch(searchText);
  }
  function initFieldData() {
    const jnpfKey = activeData.__config__.jnpfKey;
    const list = ['popupTableSelect', 'popupSelect', 'autoComplete'];
    if (list.includes(jnpfKey)) {
      if (!activeData.interfaceId) return (state.allOptions = []);
    } else {
      if (activeData.__config__.dataType !== 'dynamic' || !activeData.__config__.propsUrl) return (state.allOptions = []);
    }
    const url = list.includes(jnpfKey) ? activeData.interfaceId : activeData.__config__.propsUrl;
    getDataInterfaceInfo(url).then(res => {
      const data = res.data;
      const list = data.fieldJson ? JSON.parse(data.fieldJson) : [];
      state.allOptions = list.map(o => ({ ...o, value: o.defaultValue }));
    });
  }

  return {
    options,
    allOptions,
    debounceOnSearch,
    onFocus,
    initFieldData,
  };
}

import nodeConfig from './config.js';
import { buildBitUUID } from '/@/utils/uuid.js';

// const isEmpty = data => data === null || data === undefined || data === '';
const isEmptyArray = data => (Array.isArray(data) ? data.length === 0 : true);

export class NodeUtils {
  /**
   * 判断节点类型
   * @param {Node} node - 节点数据
   * @returns Boolean
   */
  static isConditionNode(node) {
    return node && node.type === 'condition';
  }
  static isInterflowNode(node) {
    return node && node.type === 'approver' && node.isInterflow;
  }
  static isBranchFlowNode(node) {
    return node && node.type === 'approver' && node.isBranchFlow;
  }
  static isStartNode(node) {
    return node && node.type === 'start';
  }
  static isGetDataNode(node) {
    return node && node.type === 'getData';
  }
  static isAddDataNode(node) {
    return node && node.type === 'addData';
  }
  static isUpdateDataNode(node) {
    return node && node.type === 'updateData';
  }
  static isDeleteDataNode(node) {
    return node && node.type === 'deleteData';
  }
  static isDataInterfaceNode(node) {
    return node && node.type === 'dataInterface';
  }
  static isMessageNode(node) {
    return node && node.type === 'message';
  }
  static isLaunchFlowNode(node) {
    return node && node.type === 'launchFlow';
  }
  /**
   * 创建指定节点
   * @param { String } type - 节点类型
   * @param { Object } previousNodeId - 父节点id
   * @returns { Object } 节点数据
   */
  static createNode(type, previousNodeId?) {
    const res = JSON.parse(JSON.stringify(nodeConfig[type]));
    res.nodeId = buildBitUUID();
    // if (type !== 'start' && type !== 'timer') res.properties.title += res.nodeId;
    res.prevId = previousNodeId;
    return res;
  }
  /**
   * 获取指定节点的父节点（前一个节点）
   * @param { String } prevId - 父节点id
   * @param { Object } processData - 流程图全部数据
   * @returns { Object } 父节点
   */
  static getPreviousNode(prevId, processData) {
    if (processData.nodeId === prevId) return processData;
    if (processData.childNode) {
      const r1 = this.getPreviousNode(prevId, processData.childNode);
      if (r1) {
        return r1;
      }
    }
    if (processData.conditionNodes) {
      for (const c of processData.conditionNodes) {
        const r2 = this.getPreviousNode(prevId, c);
        if (r2) {
          return r2;
        }
      }
    }
  }

  /**
   * 删除节点
   * @param { Object  } nodeData - 被删除节点的数据
   * @param { Object  } processData - 流程图的所有节点数据
   */
  static deleteNode(nodeData, processData, checkEmpty = true) {
    const prevNode = this.getPreviousNode(nodeData.prevId, processData);
    if (checkEmpty && prevNode.type === 'empty') {
      if (this.isConditionNode(nodeData) || this.isInterflowNode(nodeData) || this.isBranchFlowNode(nodeData)) {
        const willDelBranch = prevNode.conditionNodes.length === 2;
        const target = willDelBranch ? prevNode : nodeData;
        this.deleteNode(target, processData, willDelBranch);
      } else {
        if (isEmptyArray(prevNode.conditionNodes)) {
          this.deleteNode(prevNode, processData);
        }
        this.deleteNode(nodeData, processData, false);
      }
      // this.deleteNode( prevNode, processData )
      // !this.isConditionNode(nodeData) && this.deleteNode(nodeData, processData)
      return;
    }
    const concatChild = (prev, delNode) => {
      prev.childNode = delNode.childNode;
      isEmptyArray(prev.conditionNodes) && (prev.conditionNodes = delNode.conditionNodes);
      prev.childNode && (prev.childNode.prevId = prev.nodeId);
      prev.conditionNodes && prev.conditionNodes.forEach(c => (c.prevId = prev.nodeId));
    };
    if (this.isConditionNode(nodeData) || this.isInterflowNode(nodeData) || this.isBranchFlowNode(nodeData)) {
      const cons = prevNode.conditionNodes;
      const index = cons.findIndex(c => c.nodeId === nodeData.nodeId);
      if (cons.length > 2) {
        cons.splice(index, 1);
      } else {
        const anotherCon = cons[+!index];
        delete prevNode.conditionNodes;
        delete prevNode.conditionType;
        if (prevNode.childNode) {
          let endNode = anotherCon;
          while (endNode.childNode) {
            endNode = endNode.childNode;
          }
          endNode.childNode = prevNode.childNode;
          endNode.childNode.prevId = endNode.nodeId;
        }
        concatChild(prevNode, anotherCon);
        if (prevNode.childNode && prevNode.childNode.type === 'empty') {
          this.deleteNode(prevNode.childNode, prevNode);
        }
      }
      // 重新编排优先级
      cons.forEach((c, i) => (c.properties.priority = i));
      return;
    }
    concatChild(prevNode, nodeData);
  }
  // TODO:
  // static copyNode ( nodeData, processData ) {
  //   let prevNode = this.getPreviousNode( nodeData.prevId, processData )
  //   let index = prevNode.conditionNodes.findIndex( c => c.nodeId === nodeData.nodeId )

  // }
  /**
   * 添加审计节点（普通节点 approver）
   * @param { Object } data - 目标节点数据，在该数据节点之后添加审计节点
   * @param { Object } isBranchAction - 目标节点数据，是否是条件分支
   * @param { Object } newChildNode - 传入的新的节点 用户操作均为空  删除操作/添加抄送人 会传入该参数 以模拟添加节点
   */
  static addApprovalNode(data, isBranchAction, newChildNode: any = undefined) {
    const oldChildNode = data.childNode;
    newChildNode = newChildNode || this.createNode('addData', data.nodeId);
    data.childNode = newChildNode;
    if (oldChildNode) {
      newChildNode.childNode = oldChildNode;
      oldChildNode.prevId = newChildNode.nodeId;
    }
    const conditionNodes = data.conditionNodes;
    if (Array.isArray(conditionNodes) && !isBranchAction && conditionNodes.length) {
      newChildNode.conditionNodes = conditionNodes.map(c => {
        c.prevId = newChildNode.nodeId;
        return c;
      });
      delete data.conditionNodes;
    }
    if (oldChildNode && oldChildNode.type === 'empty' && newChildNode.type !== 'empty' && oldChildNode.conditionNodes.length === 0) {
      this.deleteNode(oldChildNode, data);
    }
  }
  /**
   * 添加空节点
   * @param { Object } data - 空节点的父级节点
   * @return { Object } emptyNode - 空节点数据
   */
  static addEmptyNode(data, _isNew) {
    const emptyNode = this.createNode('empty', data.nodeId);
    this.addApprovalNode(data, true, emptyNode);
    return emptyNode;
  }

  static addAddDataNode(data, isBranchAction) {
    this.addApprovalNode(data, isBranchAction, this.createNode('addData', data.nodeId));
  }
  static addUpdateDataNode(data, isBranchAction) {
    this.addApprovalNode(data, isBranchAction, this.createNode('updateData', data.nodeId));
  }
  static addDeleteDataNode(data, isBranchAction) {
    this.addApprovalNode(data, isBranchAction, this.createNode('deleteData', data.nodeId));
  }
  static addDataInterfaceNode(data, isBranchAction) {
    this.addApprovalNode(data, isBranchAction, this.createNode('dataInterface', data.nodeId));
  }
  static addMessageNode(data, isBranchAction) {
    this.addApprovalNode(data, isBranchAction, this.createNode('message', data.nodeId));
  }
  static addLaunchFlowNode(data, isBranchAction) {
    this.addApprovalNode(data, isBranchAction, this.createNode('launchFlow', data.nodeId));
  }
  /**
   * 添加条件节点 condition 通过点击添加条件进入该操作
   * @param { Object } data - 目标节点所在分支数据，在该分支最后添加条件节点
   */
  static appendConditionNode(data) {
    const conditions = data.conditionNodes;
    const node = this.createNode('condition', data.nodeId);
    const defaultNodeIndex = conditions.findIndex(node => node.properties.isDefault);
    node.properties.priority = conditions.length;
    if (defaultNodeIndex > -1) {
      conditions.splice(-1, 0, node); // 插在倒数第二个
      //更新优先级
      node.properties.priority = conditions.length - 2;
      conditions[conditions.length - 1].properties.priority = conditions.length - 1;
    } else {
      conditions.push(node);
    }
    this.setDefaultCondition(node, data);
  }
  // 添加分流/合流 branch
  static appendInterflowNode(data) {
    const conditions = data.conditionNodes;
    const node = this.createNode('interflow', data.nodeId);
    const defaultNodeIndex = conditions.findIndex(node => node.properties.isDefault);
    node.properties.priority = conditions.length;
    if (defaultNodeIndex > -1) {
      conditions.splice(-1, 0, node); // 插在倒数第二个
      //更新优先级
      node.properties.priority = conditions.length - 2;
      conditions[conditions.length - 1].properties.priority = conditions.length - 1;
    } else {
      conditions.push(node);
    }
  }
  // 添加选择分支 branch
  static appendBranchFlowNode(data) {
    const conditions = data.conditionNodes;
    const node = this.createNode('branchFlow', data.nodeId);
    const defaultNodeIndex = conditions.findIndex(node => node.properties.isDefault);
    node.properties.priority = conditions.length;
    if (defaultNodeIndex > -1) {
      conditions.splice(-1, 0, node); // 插在倒数第二个
      //更新优先级
      node.properties.priority = conditions.length - 2;
      conditions[conditions.length - 1].properties.priority = conditions.length - 1;
    } else {
      conditions.push(node);
    }
  }
  /**
   * 添加条件分支 branch
   * @param { Object } data - 目标节点所在节点数据，在该节点最后添加分支节点
   */
  static appendBranch(data, isBottomBtnOfBranch) {
    // isBottomBtnOfBranch 用户点击的是分支树下面的按钮
    let nodeData = data;
    // 由于conditionNodes是数组 不能添加下级分支 故在两个分支树之间添加一个不会显示的正常节点 兼容此种情况
    if (Array.isArray(data.conditionNodes) && data.conditionNodes.length) {
      if (isBottomBtnOfBranch) {
        // 添加一个模拟用的空白节点并返回这个节点，作为新分支的父节点
        nodeData = this.addEmptyNode(nodeData, true);
      } else {
        const emptyNode = this.addEmptyNode(nodeData, true);
        emptyNode.conditionNodes = nodeData.conditionNodes;
        emptyNode.conditionType = 'condition';
        emptyNode.conditionNodes.forEach(n => {
          n.prevId = emptyNode.nodeId;
        });
      }
    }
    const conditionNodes = [this.createNode('condition', nodeData.nodeId), this.createNode('condition', nodeData.nodeId)].map((c, i) => {
      c.properties.priority = i;
      return c;
    });
    nodeData.conditionNodes = conditionNodes;
    nodeData.conditionType = 'condition';
  }
  static appendInterflowBranch(data, isBottomBtnOfBranch) {
    // isBottomBtnOfBranch 用户点击的是分支树下面的按钮
    let nodeData = data;
    // 由于conditionNodes是数组 不能添加下级分支 故在两个分支树之间添加一个不会显示的正常节点 兼容此种情况
    if (Array.isArray(data.conditionNodes) && data.conditionNodes.length) {
      if (isBottomBtnOfBranch) {
        // 添加一个模拟用的空白节点并返回这个节点，作为新分支的父节点
        nodeData = this.addEmptyNode(nodeData, true);
      } else {
        const emptyNode = this.addEmptyNode(nodeData, true);
        emptyNode.conditionNodes = nodeData.conditionNodes;
        emptyNode.conditionType = 'interflow';
        emptyNode.conditionNodes.forEach(n => {
          n.prevId = emptyNode.nodeId;
        });
      }
    }
    const conditionNodes = [this.createNode('interflow', nodeData.nodeId), this.createNode('interflow', nodeData.nodeId)];
    nodeData.conditionNodes = conditionNodes;
    nodeData.conditionType = 'interflow';
  }
  // 新增选择分支节点
  static appendBranchFlowBranch(data, isBottomBtnOfBranch) {
    // isBottomBtnOfBranch 用户点击的是分支树下面的按钮
    let nodeData = data;
    // 由于conditionNodes是数组 不能添加下级分支 故在两个分支树之间添加一个不会显示的正常节点 兼容此种情况
    if (Array.isArray(data.conditionNodes) && data.conditionNodes.length) {
      if (isBottomBtnOfBranch) {
        // 添加一个模拟用的空白节点并返回这个节点，作为新分支的父节点
        nodeData = this.addEmptyNode(nodeData, true);
      } else {
        const emptyNode = this.addEmptyNode(nodeData, true);
        emptyNode.conditionNodes = nodeData.conditionNodes;
        emptyNode.conditionType = 'branchFlow';
        emptyNode.conditionNodes.forEach(n => {
          n.prevId = emptyNode.nodeId;
        });
      }
    }
    const conditionNodes = [this.createNode('branchFlow', nodeData.nodeId), this.createNode('branchFlow', nodeData.nodeId)];
    nodeData.conditionNodes = conditionNodes;
    nodeData.conditionType = 'branchFlow';
  }
  /**
   * 重设节点优先级（条件节点）
   * @param {Node} cNode - 当前节点
   * @param {Number} oldPriority - 替换前的优先级（在数组中的顺序）
   * @param {Node} processData - 整个流程图节点数据
   */
  static resortPriorityByCNode(cNode, oldPriority, processData) {
    // 当前节点为默认节点 取消修改优先级
    if (cNode.properties.isDefault) {
      cNode.properties.priority = oldPriority;
      return;
    }
    const prevNode = this.getPreviousNode(cNode.prevId, processData);
    const newPriority = cNode.properties.priority;
    // 替换节点为默认节点 取消修改优先级
    if (prevNode.conditionNodes[newPriority].properties.isDefault) {
      cNode.properties.priority = oldPriority;
      return;
    }
    const delNode = prevNode.conditionNodes.splice(newPriority, 1, cNode)[0];
    delNode.properties.priority = oldPriority;
    prevNode.conditionNodes[oldPriority] = delNode;
  }

  /**
   * 提升条件节点优先级——排序在前
   * @param { Object } data - 目标节点数据
   * @param { Object  } processData - 流程图的所有节点数据
   */
  static increasePriority(data, processData) {
    if (data.properties.isDefault) {
      // 默认节点不能修改优先级
      return;
    }
    // 分支节点数据 包含该分支所有的条件节点
    const prevNode = this.getPreviousNode(data.prevId, processData);
    const branchData = prevNode.conditionNodes;
    const index = branchData.findIndex(c => c === data);
    if (index) {
      // 和前一个数组项交换位置 Array.prototype.splice会返回包含被删除的项的集合（数组）
      branchData[index - 1].properties.priority = index;
      branchData[index].properties.priority = index - 1;
      branchData[index - 1] = branchData.splice(index, 1, branchData[index - 1])[0];
    }
  }
  /**
   * 降低条件节点优先级——排序在后
   * @param { Object } data - 目标节点数据
   * @param { Object  } processData - 流程图的所有节点数据
   */
  static decreasePriority(data, processData) {
    // 分支节点数据 包含该分支所有的条件节点
    const prevNode = this.getPreviousNode(data.prevId, processData);
    const branchData = prevNode.conditionNodes;
    const index = branchData.findIndex(c => c.nodeId === data.nodeId);
    if (index < branchData.length - 1) {
      const lastNode = branchData[index + 1];
      if (lastNode.properties.isDefault) {
        // 默认节点不能修改优先级
        return;
      }
      // 和后一个数组项交换位置 Array.prototype.splice会返回包含被删除的项的集合（数组）
      lastNode.properties.priority = index;
      branchData[index].properties.priority = index + 1;
      branchData[index + 1] = branchData.splice(index, 1, branchData[index + 1])[0];
    }
  }
  /**
   * 当有其他条件节点设置条件后 检查并设置最后一个节点为默认节点
   * @param {Node} cNode  - 当前节点
   * @param {Node} processData - 整个流程图节点数据或父级节点数据
   */
  static setDefaultCondition(cNode, processData) {
    const DEFAULT_TEXT = '其他情况进入此流程';
    const conditions = this.getPreviousNode(cNode.prevId, processData).conditionNodes;
    const hasCondition = node => node.properties && (node.properties.initiator || !isEmptyArray(node.properties.conditions));
    const clearDefault = node => {
      node.properties.isDefault = false;
      node.content === DEFAULT_TEXT && (node.content = '请设置条件');
    };
    const setDefault = node => {
      node.properties.isDefault = true;
      node.content = DEFAULT_TEXT;
    };
    let count = 0;
    conditions.slice(0, -1).forEach(node => {
      hasCondition(node) && count++;
      clearDefault(node);
    });
    const lastNode = conditions[conditions.length - 1];
    count > 0 && !hasCondition(lastNode) ? setDefault(lastNode) : clearDefault(lastNode);
  }
  /**
   * 校验单个节点必填项完整性
   * @param {Node} node - 节点数据
   */
  static checkNode(node, _parent?) {
    let valid = true;
    const props = node.properties;
    this.isStartNode(node) &&
      ((props.integrateType == 1 && !props.formId) ||
        (props.integrateType == 2 && (!props.cron || !props.startTime)) ||
        (props.integrateType == 3 && !props.formFieldList.length)) &&
      (valid = false);
    this.isGetDataNode(node) && !props.formId && (valid = false);
    this.isAddDataNode(node) && !props.formId && (valid = false);
    this.isUpdateDataNode(node) && !props.formId && (valid = false);
    this.isDeleteDataNode(node) && !props.formId && (valid = false);
    this.isDataInterfaceNode(node) && !props.formId && (valid = false);
    this.isLaunchFlowNode(node) && !props.flowId && (valid = false);
    this.isMessageNode(node) && (!props.msgId || !props.msgUserIds.length) && (valid = false);
    return valid;
  }
  /**
   * 判断所有节点是否信息完整
   * @param {Node} processData - 整个流程图数据
   * @returns {Boolean}
   */
  static checkAllNode(processData) {
    let valid = true;
    const loop = (node, callback, parent?) => {
      !this.checkNode(node, parent) && callback();
      if (node.childNode) loop(node.childNode, callback, parent);
      if (!isEmptyArray(node.conditionNodes)) {
        node.conditionNodes.forEach(n => loop(n, callback, node));
      }
    };
    loop(processData, () => (valid = false));
    return valid;
  }
}

