import CardHeader from '../../Portal/CardHeader/index.vue';
import * as echarts from 'echarts';
import { getDataInterfaceRes } from '/@/api/systemData/dataInterface';
import { reactive, toRefs, watch, Ref, inject, nextTick } from 'vue';
import { chartData as defaultChartData } from '../helper/dataMap';
import { useECharts } from '/@/hooks/web/useECharts';
import { getParamList } from '/@/utils/jnpf';

export function useEChart(activeData, chartRef) {
  interface State {
    currOption: any;
    chartData: any[];
  }
  const state = reactive<State>({
    currOption: {},
    chartData: [],
  });
  const { chartData, currOption } = toRefs(state);
  const { setOptions, resize } = useECharts(chartRef as Ref<HTMLDivElement>);
  const emitter: any = inject('emitter');

  watch(
    () => activeData.option,
    () => {
      initChartData();
    },
    { deep: true },
  );
  watch(
    () => activeData.dataType,
    val => {
      activeData.option.defaultValue = [];
      state.chartData = [];
      if (val == 'static') initStaticData(activeData.option.styleType);
      initBarType();
    },
  );
  watch(
    () => activeData.option.styleType,
    val => {
      if (activeData.dataType == 'static') initStaticData(val);
      initBarType();
    },
  );
  watch(
    () => activeData.option.defaultValue,
    val => {
      if (activeData.dataType !== 'static') return;
      setTimeout(() => {
        state.chartData = val;
        initChartData();
        initBarType();
      }, 0);
    },
  );
  watch(
    () => activeData.propsApi,
    val => {
      if (activeData.dataType === 'static' || !val) return;
      const query = { paramList: getParamList(activeData.templateJson) };
      getDataInterfaceRes(val, query).then(res => {
        state.chartData = res.data;
        initChartData();
        initBarType();
      });
    },
  );

  function init() {
    if (activeData.dataType === 'dynamic') {
      if (!activeData.propsApi) return;
      const query = { paramList: getParamList(activeData.templateJson) };
      getDataInterfaceRes(activeData.propsApi, query).then(res => {
        state.chartData = res.data;
        initChartData();
      });
    } else {
      setTimeout(() => {
        state.chartData = activeData.option.defaultValue;
        initChartData();
      }, 0);
    }
    emitter.on('eChart' + activeData.i, () => {
      nextTick(() => resize());
    });
  }
  function initChartData() {
    const jnpfKey = activeData.jnpfKey;
    const styleType = activeData.option.styleType;
    const option = activeData.option;
    const optionData = JSON.parse(JSON.stringify(state.chartData)) || [];
    const typeArr = Array.from(new Set(optionData.map(item => item.type)));
    const axisData = Array.from(new Set(optionData.map(item => item.name)));
    const seriesData: any[] = [];
    typeArr.forEach((title, index) => {
      const type = getType(title);
      const obj = {
        name: title,
        type: type,
        stack: styleType == 5 || styleType == 6 || styleType == 7 || (styleType != 4 && jnpfKey == 'lineChart') ? title : 'total',
      };
      const chartArr = optionData.filter(item => title === item.type);
      if (jnpfKey == 'pieChart') {
        obj['data'] = chartArr.map(item => {
          return {
            value: item.value,
            name: item.name,
          };
        });
        if (option.sortable) getPieData(obj['data']);
        if (option.showZero) obj['data'] = obj['data'].filter(item => item.value != 0);
      } else if (jnpfKey == 'radarChart') {
        const typeList = chartArr.map(item => item.type);
        const element = {
          value: chartArr.map(item => item.value),
          name: typeList && typeList.length ? typeList[0] : '',
          areaStyle: {
            color: getColor(index),
            opacity: option.seriesAreaStyleOpacity,
          },
        };
        obj['data'] = [element];
        obj['colorBy'] = 'series';
      } else {
        obj['data'] = chartArr.map(item => item.value);
      }
      seriesData.push(obj);
    });
    const xAxis: any = {
      type: option.category == 'category' ? 'category' : 'value',
      show: option.xAxisShow,
      inverse: option.xAxisInverse,
      data: axisData,
      name: option.xAxisName,
      nameTextStyle: {
        color: option.xAxisNameTextStyleColor,
        fontSize: option.xAxisNameTextStyleFontSize,
        fontWeight: option.xAxisNameTextStyleFontWeight ? 'bolder' : '',
      },
      splitLine: {
        show: option.xAxisSplitLineShow,
        lineStyle: {
          color: option.xAxisSplitLineLineStyleColor,
        },
      },
      axisLabel: {
        rotate: option.xAxisAxisLabelRotate,
        color: option.AxisTextStyleColor ? option.AxisTextStyleColor : option.xAxisAxisLabelTextStyleColor,
        fontSize: option.xAxisAxisLabelTextStyleFontSize,
        fontWeight: option.xAxisAxisLabelTextFontWeight ? 'bolder' : '',
      },
      axisLine: {
        show: option.xAxisShow,
        lineStyle: {
          color: option.AxisLineStyleColor ? option.AxisLineStyleColor : option.xAxisAxisLineLineStyleColor,
        },
      },
    };
    const yAxis = [
      {
        type: option.category == 'category' ? 'value' : 'category',
        show: option.yAxisShow,
        inverse: option.yAxisInverse,
        data: axisData,
        name: option.yAxisName,
        nameTextStyle: {
          color: option.yAxisNameTextStyleColor,
          fontSize: option.yAxisNameTextStyleFontSize,
          fontWeight: option.yAxisNameTextStyleFontWeight ? 'bolder' : '',
        },
        splitLine: {
          show: option.yAxisSplitLineShow,
          lineStyle: {
            color: option.yAxisSplitLineLineStyleColor,
          },
        },
        axisLabel: {
          interval: option.yAxisAxisLabelInterval,
          rotate: option.yAxisAxisLabelRotate,
          color: option.AxisTextStyleColor ? option.AxisTextStyleColor : option.yAxisAxisLabelTextStyleColor,
          fontSize: option.yAxisAxisLabelTextStyleFontSize,
          fontWeight: option.yAxisAxisLabelTextFontWeight ? 'bolder' : '',
        },
        axisLine: {
          show: option.yAxisShow,
          lineStyle: {
            color: option.AxisLineStyleColor ? option.AxisLineStyleColor : option.yAxisAxisLineLineStyleColor,
          },
        },
      },
    ];
    const newOption: any = {
      //标题
      title: {
        show: option.titleText || option.titleSubtext,
        text: option.titleText,
        textStyle: {
          color: option.titleTextStyleColor,
          fontSize: option.titleTextStyleFontSize,
          fontWeight: option.titleTextStyleFontWeight ? 'bolder' : '',
        },
        subtext: option.titleSubtext,
        subtextStyle: {
          color: option.titleSubtextStyleColor,
          fontSize: option.titleSubtextStyleFontSize,
          fontWeight: option.titleSubtextStyleFontWeight ? 'bolder' : '',
        },
        left: option.titleLeft,
        backgroundColor: option.titleText || option.titleSubtext ? option.titleBgColor || '#fff' : '#fff',
      },
      //提示
      tooltip: {
        show: option.tooltipShow,
        backgroundColor: option.tooltipBgColor,
        textStyle: {
          color: option.tooltipTextStyleColor,
          fontSize: option.tooltipTextStyleFontSize,
          fontWeight: option.tooltipTextStyleFontWeight ? 'bolder' : '',
        },
      },
      //网格
      grid: {
        left: option.gridLeft,
        top: option.gridTop,
        right: option.gridRight,
        bottom: option.gridBottom,
        containLabel: true,
      },
      //图例
      legend: {
        show: option.legendShow,
        orient: option.legendOrient,
        textStyle: {
          fontSize: option.legendTextStyleFontSize || 12,
        },
        top: option.legendTop + '%',
        right: option.legendLeft + '%',
      },
      series: (() => {
        const list: any[] = (seriesData || []).map((ele: any, index) => {
          const label: any = {
            show: option.seriesLabelShow,
            position: jnpfKey == 'pieChart' ? option.seriesLabelPosition : 'top',
            fontSize: option.seriesLabelFontSize,
            fontWeight: option.seriesLabelFontWeight ? 'bolder' : 'normal',
            color: option.seriesLabelColor,
            backgroundColor: option.seriesLabelBgColor,
          };
          const itemStyle: any = {
            borderRadius: option.seriesItemStyleBarBorderRadius,
          };
          if (jnpfKey == 'barChart' || jnpfKey == 'lineChart' || jnpfKey == 'radarChart') itemStyle.color = getColor(index);
          if (jnpfKey == 'lineChart') {
            ele.smooth = styleType == 2;
            ele.step = styleType == 3;
            ele.lineStyle = {
              width: option.seriesLineStyleWidth,
            };
            ele.symbolSize = option.seriesSymbolRotate;
            if (option.areaStyle) ele.areaStyle = {};
          }
          if (jnpfKey == 'pieChart') {
            if (styleType == 1) ele.radius = '60%';
            if (styleType == 2) ele.radius = ['30%', '60%'];
            if (option.roseType) ele.roseType = 'area';
            if (option.seriesLabelShowInfo && option.seriesLabelShowInfo.length) {
              if (option.seriesLabelShowInfo.includes('count') && option.seriesLabelShowInfo.includes('percent')) {
                label.formatter = '{b}: {c} ({d}%)';
              } else if (option.seriesLabelShowInfo.includes('count')) {
                label.formatter = '{b}: {c} ';
              } else if (option.seriesLabelShowInfo.includes('percent')) {
                label.formatter = '{b}: ({d}%) ';
              }
            }
            if (option.colorList && option.colorList.length) {
              const colorList: any[] = [];
              option.colorList.map((_item, index) => {
                const color = getColor(index) || '#71B6F5';
                colorList.push(color);
              });
              ele.color = colorList;
            }
            ele.center = [option.seriesCenterLeft + '%', option.seriesCenterTop + '%'];
          }
          return Object.assign(ele, {
            name: ele.name,
            type: ele.type,
            data: ele.data,
            stack: ele.stack,
            showBackground: styleType == 4 ? true : false,
            barWidth: option.seriesBarWidth,
            itemStyle,
            label,
          });
        });
        return list;
      })(),
    };
    if (jnpfKey == 'barChart' || jnpfKey == 'lineChart') {
      if (jnpfKey == 'lineChart' && option.areaStyle) xAxis.boundaryGap = false;
      newOption.xAxis = xAxis;
      newOption.yAxis = yAxis;
    } else if (jnpfKey == 'radarChart') {
      newOption.radar = [];
      typeArr.map(item => {
        const indicator = axisData.map(items => {
          const maxObj = optionData.find(element => {
            return element.type == item && element.name == items;
          });
          return {
            name: items,
            max: maxObj ? maxObj.max : '',
          };
        });
        const radarObj = {
          indicator: indicator,
          shape: option.styleType == 1 ? 'polygon' : 'circle',
          axisName: {
            fontSize: option.radarAxisNameFontSize,
            fontWeight: option.radarAxisNameFontWeight ? 'bolder' : 'normal',
            color: option.radarAxisNameColor,
          },
          center: [option.radarCenterLeft + '%', option.radarCenterTop + '%'],
        };
        newOption.radar.push(radarObj);
      });
    } else if (jnpfKey == 'pieChart') {
      if (option.seriesLabelShowInfo.includes('count') && option.seriesLabelShowInfo.includes('percent')) {
        newOption.tooltip.formatter = '{b}: {c} ({d}%)';
      } else if (option.seriesLabelShowInfo.includes('count')) {
        newOption.tooltip.formatter = '{b}: {c}';
      } else if (option.seriesLabelShowInfo.includes('percent')) {
        newOption.tooltip.formatter = '{b}: {d}%';
      } else {
        newOption.tooltip.formatter = '{b}';
      }
    }
    state.currOption = newOption;
    setOptions(newOption, true);
  }
  function getType(title) {
    const jnpfKey = activeData.jnpfKey;
    const option = activeData.option;
    if (jnpfKey == 'barChart') {
      if (option.styleType == 7) {
        const arr = option.barType.find(ele => title == ele.title);
        if (arr && arr.type) return arr.type;
      }
      return 'bar';
    } else if (jnpfKey == 'lineChart') {
      return 'line';
    } else if (jnpfKey == 'pieChart') {
      return 'pie';
    } else if (jnpfKey == 'radarChart') {
      return 'radar';
    }
  }
  function getColor(index) {
    const option = activeData.option;
    const barColor = option.colorList || [];
    if (barColor[index]) {
      const color1 = barColor[index].color1;
      const color2 = barColor[index].color2;
      if (color2 && color1)
        return new echarts.graphic.LinearGradient(0, 0, 0, 1, [
          { offset: 0, color: color1 },
          { offset: 1, color: color2 },
        ]);
      return color1;
    }
  }
  function getPieData(list) {
    for (let i = 0; i < list.length - 1; i++) {
      for (let j = 0; j < list.length - 1; j++) {
        if (list[j].value > list[j + 1].value) {
          const t = list[j];
          list[j] = list[j + 1];
          list[j + 1] = t;
        }
      }
    }
  }
  function initStaticData(val) {
    const jnpfKey = activeData.jnpfKey;
    activeData.option.defaultValue = [];
    if (jnpfKey == 'barChart') {
      if (val == 1 || val == 4) activeData.option.defaultValue = defaultChartData.baseBarData;
      if (val == 2 || val == 5) activeData.option.defaultValue = defaultChartData.mulBarData;
      if (val == 6) activeData.option.defaultValue = defaultChartData.plusMinusBarData;
      if (val == 7) {
        activeData.option.defaultValue = defaultChartData.brokenColumnBarData;
        initBarType();
      }
    } else if (jnpfKey == 'lineChart') {
      if (val == 1 || val == 2 || val == 3) activeData.option.defaultValue = defaultChartData.baseBarData;
      if (val == 4) activeData.option.defaultValue = defaultChartData.mulBarData;
    } else if (jnpfKey == 'pieChart') {
      activeData.option.defaultValue = defaultChartData.baseBarData;
    } else if (jnpfKey == 'radarChart') {
      activeData.option.defaultValue = defaultChartData.radarData;
    }
  }
  function initBarType() {
    const option = activeData.option;
    if (option.styleType !== 7) return;
    const optionData = state.chartData || [];
    if (!Array.isArray(optionData)) return;
    option.barType = [];
    const typeArr = Array.from(new Set(optionData.map(item => item.type)));
    typeArr.map((item, index) => {
      if (item) {
        option.barType.push({
          title: item,
          type: index == 1 ? 'line' : 'bar',
        });
      }
    });
  }

  return {
    CardHeader,
    chartData,
    currOption,
    init,
  };
}

/**
 * AgentScope — Agent 视图机制（P0 审判令一）
 *
 * 每个 Agent 注册一个固定的 AgentScope，定义其可读、可写的 IR 节点类型。
 * Agent 只能操作自己视图范围内的节点，跨视图修改通过 OrchestratorAgent 协调。
 *
 * @module ai/agents/agent-scope
 * @version 1.0.0
 */

import type { FormPageIR } from '../../ir/types';

// ============================================================
// 类型定义
// ============================================================

/** IR 节点类型（与 types.ts 中的定义一致） */
export type IRNodeType =
  | 'Requirement'
  | 'ModuleDefinition'
  | 'TableDefinition'
  | 'Component'
  | 'DataSource'
  | 'WorkflowStep'
  | 'RuleNode'
  | 'CompileConfig'
  | 'Field'
  | 'Expression'
  | 'Action'
  | 'Validation';

export interface AgentScope {
  /** Agent 名称 */
  agentName: string;
  /** 该 Agent 负责产出的节点类型 */
  ownedNodeTypes: IRNodeType[];
  /** 该 Agent 可读的节点类型。包含 '*' 时表示概览读取全部（不展开内部字段） */
  readableNodeTypes: (IRNodeType | '*')[];
  /** 分治编辑时可写的节点类型 */
  writableNodeTypes: IRNodeType[];
}

export interface AgentSlice {
  /** 切片内的 IR 节点 */
  nodes: unknown[];
  /** 这些节点在整体 IR 中的角色描述 */
  context: string;
  /** Agent 可修改的节点 ID 列表（从 writableNodeTypes 推导） */
  writableNodeIds: string[];
}

// ============================================================
// 6 个 Agent 的静态注册表（编译时常量）
// ============================================================

export const AGENT_SCOPES: AgentScope[] = [
  {
    agentName: 'RequirementAnalystAgent',
    ownedNodeTypes: ['Requirement'],
    readableNodeTypes: ['*'],
    writableNodeTypes: ['Requirement'],
  },
  {
    agentName: 'ArchitectAgent',
    ownedNodeTypes: ['ModuleDefinition', 'TableDefinition'],
    readableNodeTypes: ['Requirement', 'ModuleDefinition'],
    writableNodeTypes: ['ModuleDefinition', 'TableDefinition'],
  },
  {
    agentName: 'UIAgent',
    ownedNodeTypes: ['Component'],
    readableNodeTypes: ['Component', 'DataSource', 'Requirement'],
    writableNodeTypes: ['Component'],
  },
  {
    agentName: 'DatabaseAgent',
    ownedNodeTypes: ['TableDefinition', 'DataSource'],
    readableNodeTypes: ['TableDefinition', 'DataSource', 'Requirement'],
    writableNodeTypes: ['TableDefinition', 'DataSource'],
  },
  {
    agentName: 'WorkflowAgent',
    ownedNodeTypes: ['WorkflowStep'],
    readableNodeTypes: ['WorkflowStep', 'Component'],
    writableNodeTypes: ['WorkflowStep'],
  },
  {
    agentName: 'RuleEngineAgent',
    ownedNodeTypes: ['RuleNode'],
    readableNodeTypes: ['RuleNode', 'Component', 'Requirement'],
    writableNodeTypes: ['RuleNode'],
  },
];

// ============================================================
// 切片提取
// ============================================================

/**
 * 从 IR 中按 Scope 过滤提取切片。
 *
 * 当 readableNodeTypes 包含 '*' 时，返回所有节点的摘要视图
 * （只包含 nodeId + type + name，不展开内部字段）。
 */
export function extractSlice(ir: FormPageIR, scope: AgentScope): AgentSlice {
  const allNodes = collectAllNodes(ir);
  const readableTypes = scope.readableNodeTypes;

  // 判断是否需要摘要视图
  const needsSummary = readableTypes.includes('*');

  let nodes: unknown[];
  if (needsSummary) {
    // 摘要视图：所有节点只暴露 id + type + name
    nodes = allNodes.map((n: Record<string, unknown>) => ({
      id: n.id,
      type: (n as Record<string, unknown>).type,
      name: (n as Record<string, unknown>).name,
    }));
  } else {
    // 精确过滤：只返回 readableNodeTypes 中指定的类型
    nodes = allNodes.filter((n: Record<string, unknown>) => readableTypes.includes((n as Record<string, unknown>).type as IRNodeType));
  }

  // 从 writableNodeTypes 推导可写节点 ID
  const writableNodeIds = allNodes
    .filter((n: Record<string, unknown>) => scope.writableNodeTypes.includes((n as Record<string, unknown>).type as IRNodeType))
    .map((n: Record<string, unknown>) => n.id as string);

  // 生成上下文描述
  const context =
    `Agent [${scope.agentName}] 切片：${nodes.length} 个可读节点，${writableNodeIds.length} 个可写节点。` +
    `可写类型：${scope.writableNodeTypes.join(', ')}。` +
    `可读类型：${needsSummary ? '全部（摘要视图）' : scope.readableNodeTypes.join(', ')}。`;

  return { nodes, context, writableNodeIds };
}

// ============================================================
// 内部工具
// ============================================================

/** 从 FormPageIR 中收集所有可枚举的节点 */
function collectAllNodes(ir: FormPageIR): unknown[] {
  const nodes: unknown[] = [];

  // fields
  if (ir.fields) {
    for (const f of ir.fields) {
      nodes.push({ id: f.id || '', type: 'Field', name: f.label || '' });
    }
  }

  // databaseFields → DataSource
  if (ir.databaseFields) {
    for (const d of ir.databaseFields) {
      nodes.push({ id: d.name || '', type: 'DataSource', name: d.name || '' });
    }
  }

  // expressions
  if (ir.expressions) {
    for (const e of ir.expressions) {
      nodes.push({ id: e.id || '', type: 'Expression', name: e.name || '' });
    }
  }

  // listConfig → Component
  if (ir.listConfig) {
    nodes.push({
      id: `${ir.id}_list`,
      type: 'Component',
      name: `${ir.name}_list`,
    });
    if (ir.listConfig.columns) {
      for (const c of ir.listConfig.columns) {
        nodes.push({ id: c.field || '', type: 'Field', name: c.label || c.field || '' });
      }
    }
  }

  // workflow → WorkflowStep
  if (ir.workflow?.templateList) {
    for (const t of ir.workflow.templateList) {
      nodes.push({ id: t.id || '', type: 'WorkflowStep', name: t.name || '' });
    }
  }

  return nodes;
}

/**
 * 智能体基类
 *
 * 所有智能体（需求分析师、架构师、UI/UX 设计师、数据库设计师）的抽象基类。
 * 提供：
 *   - LLM 调用封装（execute / executeStream）
 *   - Prompt 变量填充（buildSystemPrompt）
 *   - 响应解析（parseResponse — 3 种 JSON 格式）
 *   - 置信度评估（evaluateConfidence）
 *
 * 子类只需定义 AgentResponse 的具体类型并调用 execute<T>()。
 *
 * @version 1.0.0
 * @module ai/agents/base
 */

import type { LLMGateway, ChatResponse } from '../llm/types';
import type { PromptTemplate } from '../llm/prompts';

// ============================================================
// 上下文类型
// ============================================================

/** 智能体执行上下文（供 resolveVariable 使用） */
export interface AgentContext {
  /** 对话历史 */
  messages?: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>;
  /** DKEE 知识图谱数据 */
  knowledgeGraph?: Record<string, unknown>;
  /** 企业架构基线（EAB）快照 */
  eab?: Record<string, unknown>;
  /** 当前 IR（架构师产出后，UI/DB 智能体继续加工） */
  currentIR?: Record<string, unknown>;
  /** 当前业务领域 */
  domain?: string;
  /** 扩展字段 */
  [key: string]: unknown;
}

/** 智能体响应（泛型，子类指定具体 T） */
export interface AgentResponse<T = unknown> {
  /** 结构化数据 */
  data: T;
  /** LLM 原始文本（调试用） */
  rawText: string;
  /** Token 用量 */
  usage: ChatResponse['usage'];
  /** 请求延迟（毫秒） */
  latency: number;
  /** 响应置信度（0-1），< 0.6 建议人工审核 */
  confidence: number;
}

// ============================================================
// BaseAgent
// ============================================================

export abstract class BaseAgent {
  protected llm: LLMGateway;
  protected template: PromptTemplate;

  constructor(llm: LLMGateway, template: PromptTemplate) {
    this.llm = llm;
    this.template = template;
  }

  // ============================================================
  // 核心方法
  // ============================================================

  /**
   * 执行智能体（非流式）。
   *
   * 流程：buildSystemPrompt → llm.chat → parseResponse → evaluateConfidence
   *
   * @param userInput - 用户输入
   * @param context - 执行上下文
   * @returns AgentResponse<T>
   */
  protected async execute<T>(userInput: string, context: AgentContext): Promise<AgentResponse<T>> {
    const systemPrompt = this.buildSystemPrompt(context);

    const response = await this.llm.chat({
      messages: [{ role: 'system', content: systemPrompt }, ...(context.messages ?? []), { role: 'user', content: userInput }],
      responseFormat: 'json',
    });

    const data = this.parseResponse<T>(response.content);
    const confidence = this.evaluateConfidence(data, response);

    return {
      data,
      rawText: response.content,
      usage: response.usage,
      latency: response.latency,
      confidence,
    };
  }

  /**
   * 执行智能体（流式）。
   *
   * 收集完整响应后解析，但实时 yield 增量文本给调用方展示"AI 思考过程"。
   *
   * @param userInput - 用户输入
   * @param context - 执行上下文
   * @returns 异步生成器
   */
  protected async *executeStream(userInput: string, context: AgentContext): AsyncGenerator<string, void, undefined> {
    const systemPrompt = this.buildSystemPrompt(context);

    let fullContent = '';

    for await (const chunk of this.llm.chatStream({
      messages: [{ role: 'system', content: systemPrompt }, ...(context.messages ?? []), { role: 'user', content: userInput }],
    })) {
      fullContent += chunk;
      yield chunk;
    }

    const data = this.parseResponse<unknown>(fullContent);
    const confidence = this.evaluateConfidence(data, {
      content: fullContent,
      usage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
      model: '',
      provider: '',
      latency: 0,
    });

    yield `\n\n---\n**置信度:** ${(confidence * 100).toFixed(0)}%`;

    // 最终产出
    const finalResponse: AgentResponse<unknown> = {
      data,
      rawText: fullContent,
      usage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
      latency: 0,
      confidence,
    };

    // 通过 hack 返回最终对象（generator 不能 return 值给 for-await 消费方，
    // 调用方通过 lastValue 模式获取）
    yield `\n__AGENT_RESPONSE__${JSON.stringify(finalResponse)}`;
  }

  // ============================================================
  // Prompt 构建
  // ============================================================

  /**
   * 构建 System Prompt。
   *
   * 扫描模板中的 {{variableName}} 占位符，
   * 调用 resolveVariable 获取实际值后替换。
   *
   * @param context - 执行上下文
   * @returns 填充后的 System Prompt
   */
  protected buildSystemPrompt(context: AgentContext): string {
    let result = this.template.template;

    for (const variable of this.template.variables) {
      const placeholder = `{{${variable.name}}}`;
      if (result.includes(placeholder)) {
        const value = this.resolveVariable(variable.name, context);
        result = result.replaceAll(placeholder, value);
      }
    }

    return result;
  }

  /**
   * 解析变量值。
   *
   * 优先级：
   *   1. AgentContext 中直接匹配的 key
   *   2. PromptVariable.defaultValue
   *   3. 空字符串
   *
   * @param name - 变量名
   * @param context - 执行上下文
   * @returns 变量值字符串
   */
  protected resolveVariable(name: string, context: AgentContext): string {
    // 尝试从上下文直接取值
    const value = context[name];
    if (value !== undefined && value !== null) {
      if (typeof value === 'string') return value;
      return JSON.stringify(value);
    }

    // fallback 到 PromptTemplate 变量的默认值
    const variable = this.template.variables.find(v => v.name === name);
    if (variable?.defaultValue !== undefined) {
      return variable.defaultValue;
    }

    return '';
  }

  // ============================================================
  // 响应解析（3 种格式）
  // ============================================================

  /**
   * 解析 LLM 响应为结构化数据。
   *
   * 依次尝试三种格式：
   *   1. 纯 JSON — 直接 JSON.parse
   *   2. Markdown 包裹 — 提取 ```json ... ``` 块
   *   3. 混合文本 — 提取第一个 {...} 块
   *
   * 全部失败则抛出异常。
   *
   * @param content - LLM 原始响应内容
   * @returns 解析后的数据
   * @throws 无法提取 JSON 时抛出
   */
  protected parseResponse<T>(content: string): T {
    const trimmed = content.trim();

    // 尝试 1：纯 JSON
    if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
      try {
        return JSON.parse(trimmed) as T;
      } catch {
        // 继续尝试其他格式
      }
    }

    // 尝试 2：Markdown 包裹的 JSON
    const jsonBlockMatch = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonBlockMatch) {
      try {
        return JSON.parse(jsonBlockMatch[1].trim()) as T;
      } catch {
        // 继续尝试
      }
    }

    // 尝试 3：混合文本中的第一个完整 JSON 对象
    const firstBrace = trimmed.indexOf('{');
    if (firstBrace !== -1) {
      // 从第一个 { 开始，追踪嵌套层级找到匹配的 }
      let depth = 0;
      let endIndex = -1;
      for (let i = firstBrace; i < trimmed.length; i++) {
        if (trimmed[i] === '{') depth++;
        if (trimmed[i] === '}') {
          depth--;
          if (depth === 0) {
            endIndex = i;
            break;
          }
        }
      }
      if (endIndex !== -1) {
        const jsonCandidate = trimmed.slice(firstBrace, endIndex + 1);
        try {
          return JSON.parse(jsonCandidate) as T;
        } catch {
          // 最后尝试失败
        }
      }
    }

    throw new Error(`[BaseAgent] 无法从 LLM 响应中提取 JSON。响应前 200 字符: ${trimmed.slice(0, 200)}`);
  }

  // ============================================================
  // 置信度评估
  // ============================================================

  /**
   * 评估响应置信度（0-1）。
   *
   * 基础分 0.7。
   * + 0.1：响应长度 > 50 字符
   * + 0.1：数据包含 3+ 个 key
   * 上限 1.0。
   *
   * @param data - 解析后的数据
   * @param _response - LLM 原始响应（保留，后续扩展用）
   * @returns 置信度分数
   */
  protected evaluateConfidence(data: unknown, _response: ChatResponse): number {
    let score = 0.7;

    // 数据完整性
    if (data !== null && typeof data === 'object') {
      const keys = Object.keys(data as Record<string, unknown>);
      if (keys.length >= 3) {
        score += 0.1;
      }
    }

    // 上限
    return Math.min(score, 1.0);
  }
}

/**
 * 数据库设计智能体
 *
 * 根据领域模型生成数据库表结构、迁移 SQL 和 API 端点。
 * 自动注入多租户字段和审计字段，强制校验命名规范。
 *
 * 硬性约束（不可违反）：
 *   - 表名：{MODULE_PREFIX}_{ENTITY} UPPER_SNAKE_CASE
 *   - 列名：F_ UPPER_SNAKE_CASE
 *   - 主键：F_ID BIGINT（雪花 ID）
 *   - 每表必含：F_TENANT_ID + 审计字段 + F_IS_DELETED
 *
 * @version 1.0.0
 * @module ai/agents/database
 */

import type { LLMGateway } from '../llm/types';
import { DATABASE_DESIGNER_PROMPT } from '../llm/prompts';
import { BaseAgent, type AgentContext, type AgentResponse } from './base';

// ============================================================
// 输出类型
// ============================================================

export interface DatabaseDesign {
  /** 数据库设计概述 */
  overview: string;
  /** 表结构定义 */
  tables: Array<{
    name: string;
    comment: string;
    columns: Array<{
      name: string;
      type: string;
      length?: number | null;
      nullable: boolean;
      defaultValue?: string | null;
      comment: string;
      isAudit?: boolean;
      isTenant?: boolean;
    }>;
    indexes: Array<{
      name: string;
      columns: string[];
      unique: boolean;
    }>;
  }>;
  /** 迁移 SQL */
  migrationSql: string;
  /** API 端点 */
  apis: Array<{
    path: string;
    method: 'GET' | 'POST' | 'PUT' | 'DELETE';
    description: string;
    requestType?: string;
    responseType?: string;
    requireAuth: boolean;
    permissionCode?: string;
  }>;
}

// ============================================================
// 审计字段（与 ArchitectAgent 保持一致）
// ============================================================

const TENANT_COLUMN = {
  name: 'F_TENANT_ID',
  type: 'NVARCHAR',
  length: 50,
  nullable: false,
  defaultValue: null,
  comment: '租户ID',
  isTenant: true,
};

const AUDIT_COLUMNS = [
  { name: 'F_CREATE_USER_ID', type: 'NVARCHAR', length: 50, nullable: true, defaultValue: null, comment: '创建用户', isAudit: true },
  { name: 'F_CREATE_TIME', type: 'DATETIME', nullable: false, defaultValue: 'GETDATE()', comment: '创建时间', isAudit: true },
  { name: 'F_MODIFY_USER_ID', type: 'NVARCHAR', length: 50, nullable: true, defaultValue: null, comment: '修改用户', isAudit: true },
  { name: 'F_MODIFY_TIME', type: 'DATETIME', nullable: true, defaultValue: null, comment: '修改时间', isAudit: true },
  { name: 'F_IS_DELETED', type: 'BIT', nullable: false, defaultValue: '0', comment: '逻辑删除', isAudit: true },
];

// ============================================================
// DatabaseAgent
// ============================================================

export class DatabaseAgent extends BaseAgent {
  constructor(llm: LLMGateway) {
    super(llm, DATABASE_DESIGNER_PROMPT);
  }

  /**
   * 设计数据库。
   *
   * 流程：LLM 生成 → 注入租户/审计字段 → 校验命名规范 → 校验 API 端点
   *
   * @param domainModel - JSON 序列化的领域模型
   * @param context - 执行上下文
   * @returns 数据库设计方案
   */
  async design(domainModel: string, context: AgentContext = {}): Promise<AgentResponse<DatabaseDesign>> {
    const result = await this.execute<DatabaseDesign>(domainModel, context);

    // 自动注入多租户和审计字段
    result.data = this.injectAuditFields(result.data);

    // 校验并修正命名规范
    result.data = this.normalizeNaming(result.data);

    // 校验 API 端点
    result.data = this.validateApis(result.data);

    return result;
  }

  // ============================================================
  // 自动注入
  // ============================================================

  /**
   * 自动注入 TENANT_ID + 审计字段 + IS_DELETED。
   */
  private injectAuditFields(design: DatabaseDesign): DatabaseDesign {
    for (const table of design.tables) {
      const columnNames = table.columns.map(c => c.name.toUpperCase());

      // 注入主键 F_ID
      const hasId = columnNames.includes('F_ID') || columnNames.includes('ID');
      if (!hasId) {
        table.columns.unshift({
          name: 'F_ID',
          type: 'BIGINT',
          nullable: false,
          comment: '主键（雪花ID）',
        });
      }

      // 注入 F_TENANT_ID（紧跟主键）
      const hasTenantId = columnNames.includes('F_TENANT_ID') || columnNames.includes('TENANT_ID');
      if (!hasTenantId) {
        const idIndex = table.columns.findIndex(c => c.name.toUpperCase() === 'F_ID' || c.name.toUpperCase() === 'ID');
        const insertAt = idIndex >= 0 ? idIndex + 1 : 0;
        table.columns.splice(insertAt, 0, { ...TENANT_COLUMN });
      }

      // 注入审计字段（追加到末尾）
      for (const auditCol of AUDIT_COLUMNS) {
        const exists = columnNames.includes(auditCol.name.toUpperCase());
        if (!exists) {
          table.columns.push({ ...auditCol });
        }
      }
    }

    return design;
  }

  /**
   * 校验并修正命名规范。
   */
  private normalizeNaming(design: DatabaseDesign): DatabaseDesign {
    for (const table of design.tables) {
      // 表名：UPPER_SNAKE_CASE
      if (table.name !== table.name.toUpperCase()) {
        console.warn(`[DatabaseAgent] 表名 "${table.name}" → "${table.name.toUpperCase()}"（已规范化）`);
        table.name = table.name.toUpperCase();
      }

      // 列名：F_ UPPER_SNAKE_CASE
      for (const column of table.columns) {
        // 确保 F_ 前缀
        if (!column.name.toUpperCase().startsWith('F_')) {
          const oldName = column.name;
          column.name = `F_${column.name.replace(/^F_/i, '')}`;
          console.warn(`[DatabaseAgent] 列名 "${oldName}" → "${column.name}"（已加 F_ 前缀）`);
        }
        // 确保大写
        if (column.name !== column.name.toUpperCase()) {
          const oldName = column.name;
          column.name = column.name.toUpperCase();
          console.warn(`[DatabaseAgent] 列名 "${oldName}" → "${column.name}"（已大写规范化）`);
        }
      }

      // 索引命名：IDX_{TABLE}_{COLUMN}
      for (const index of table.indexes) {
        if (!index.name.toUpperCase().startsWith('IDX_')) {
          index.name = `IDX_${table.name}_${index.columns.join('_')}`;
        }
        index.name = index.name.toUpperCase();
      }
    }

    return design;
  }

  /**
   * 校验 API 端点基本格式。
   */
  private validateApis(design: DatabaseDesign): DatabaseDesign {
    for (const api of design.apis) {
      // 确保路径以 /api/ 开头
      if (!api.path.startsWith('/api/')) {
        api.path = `/api${api.path.startsWith('/') ? '' : '/'}${api.path}`;
      }
      // 确保方法为大写
      api.method = api.method.toUpperCase() as 'GET' | 'POST' | 'PUT' | 'DELETE';
      // 默认需要认证
      if (api.requireAuth === undefined) {
        api.requireAuth = true;
      }
    }
    return design;
  }
}

/**
 * DKEE v1.0 — 领域知识进化引擎
 *
 * 观察人类操作 → 提炼领域模式 → 沉淀知识图谱 → 下次主动调用。
 *
 * 核心原理：
 *   1. 观察 — 追踪用户在专家模式下的创建/修改/删除操作
 *   2. 提炼 — 当同一领域累计 3+ 次操作时，提取领域模式
 *   3. 沉淀 — 将模式写入知识图谱（in-memory + localStorage持久化）
 *   4. 召回 — AI 执行前按领域关键词搜索相关模式
 *
 * @version 1.0.0
 * @module ai/dkee/v1
 */

// ============================================================
// 类型
// ============================================================

/** 领域模式 */
export interface DomainPattern {
  id: string;
  name: string;
  domain: string;
  description: string;
  source: 'ai-discovered' | 'human-created' | 'self-play' | 'hybrid';
  pattern: {
    entities: Array<{ name: string; fields: Array<{ name: string; type: string }> }>;
    rules: Array<{ name: string; condition: string; action: string }>;
    components: string[];
  };
  usageCount: number;
  successRate: number;
  version: number;
  createdAt: string;
  updatedAt: string;
}

/** 人类操作事件 */
export interface HumanAction {
  type: 'create' | 'modify' | 'delete';
  target: string;
  before: unknown;
  after: unknown;
}

/** 操作分组（按领域聚合） */
interface _ActionGroup {
  domain: string;
  actions: HumanAction[];
}

// ============================================================
// 知识图谱存储（in-memory + localStorage）
// ============================================================

const STORAGE_KEY = 'jnpf_dkee_patterns';

let knowledgeGraph: DomainPattern[] = [];

/** 从 localStorage 加载知识图谱 */
function loadFromStorage(): void {
  try {
    const storage = globalThis.localStorage;
    if (!storage) return;
    const raw = storage.getItem(STORAGE_KEY);
    if (raw) {
      knowledgeGraph = JSON.parse(raw) as DomainPattern[];
    }
  } catch {
    // Node/test environment — keep in-memory state
    return;
  }
}

/** 保存知识图谱到 localStorage */
function saveToStorage(): void {
  try {
    const storage = globalThis.localStorage;
    if (!storage) return;
    storage.setItem(STORAGE_KEY, JSON.stringify(knowledgeGraph));
  } catch {
    // localStorage 不可用（SSR/测试环境），静默失败
  }
}

// ============================================================
// 核心 API
// ============================================================

/**
 * 观察人类操作，提炼领域模式。
 *
 * 当同一领域累计 3+ 次 create 操作时，
 * 提取实体结构、业务规则和常用组件，生成 DomainPattern。
 *
 * @param humanActions - 人类操作事件数组
 * @param currentDomain - 当前业务领域
 * @returns 提炼出的领域模式（不满足条件时返回 null）
 */
export function observeAndExtract(humanActions: HumanAction[], currentDomain: string): DomainPattern | null {
  if (!currentDomain) return null;

  // 过滤当前领域的 create 操作
  const creates = humanActions.filter(a => a.type === 'create' && (a.target.includes(currentDomain) || a.target === currentDomain));

  // 需要至少 3 次操作
  if (creates.length < 3) return null;

  // 提取实体模式
  const entities = extractEntities(creates);
  if (entities.length === 0) return null;

  // 提取业务规则
  const rules = extractRules(creates);

  // 提取常用组件
  const components = extractComponents(creates);

  const pattern: DomainPattern = {
    id: `${currentDomain.replace(/\s+/g, '_')}_${Date.now()}`,
    name: `${currentDomain}领域模式`,
    domain: currentDomain,
    description: `从 ${creates.length} 次人工创建中提炼的${currentDomain}领域模式`,
    source: 'human-created',
    pattern: { entities, rules, components },
    usageCount: 1,
    successRate: 1.0,
    version: 1,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  return pattern;
}

/**
 * 将领域模式持久化到知识图谱。
 * 如果同 domain 已存在，合并并更新版本。
 */
export function persistPattern(pattern: DomainPattern): void {
  loadFromStorage();

  const existing = knowledgeGraph.findIndex(p => p.domain === pattern.domain && p.name === pattern.name);

  if (existing >= 0) {
    // 合并：保留原有使用次数，更新内容
    const old = knowledgeGraph[existing];
    pattern.usageCount = old.usageCount + 1;
    pattern.version = old.version + 1;
    pattern.source = 'hybrid';
    knowledgeGraph[existing] = pattern;
  } else {
    knowledgeGraph.push(pattern);
  }

  saveToStorage();
}

/**
 * 按领域关键词召回模式。
 *
 * @param domain - 领域关键词（如 "教育"、"制造"）
 * @returns 匹配的领域模式列表，按成功率降序
 */
export function recallPatterns(domain: string): DomainPattern[] {
  loadFromStorage();

  if (!domain) return [];

  const results = knowledgeGraph
    .filter(p => p.domain.includes(domain) || p.name.includes(domain) || p.description.includes(domain))
    .sort((a, b) => b.successRate - a.successRate || b.usageCount - a.usageCount);

  // 更新使用计数
  for (const p of results) {
    p.usageCount++;
    p.updatedAt = new Date().toISOString();
  }

  if (results.length > 0) {
    saveToStorage();
  }

  return results;
}

/**
 * 获取完整知识图谱。
 */
export function getKnowledgeGraph(): DomainPattern[] {
  loadFromStorage();
  return [...knowledgeGraph];
}

/**
 * 清空知识图谱（测试用）。
 */
export function clearKnowledgeGraph(): void {
  knowledgeGraph = [];
  saveToStorage();
}

// ============================================================
// 内部提取函数
// ============================================================

/** 从创建操作中提取实体结构 */
function extractEntities(creates: HumanAction[]): DomainPattern['pattern']['entities'] {
  const entities: DomainPattern['pattern']['entities'] = [];

  for (const action of creates) {
    const after = action.after as Record<string, unknown> | null;
    if (after && typeof after === 'object' && typeof (after as Record<string, unknown>).name === 'string') {
      const entityName = (after as Record<string, unknown>).name as string;
      const fields = extractFields(after);

      if (!entities.find(e => e.name === entityName)) {
        entities.push({ name: entityName, fields });
      } else {
        // 合并字段（去重）
        const existing = entities.find(e => e.name === entityName)!;
        for (const f of fields) {
          if (!existing.fields.find(ef => ef.name === f.name)) {
            existing.fields.push(f);
          }
        }
      }
    }
  }

  return entities;
}

/** 从实体对象中提取字段 */
function extractFields(obj: Record<string, unknown>, prefix = ''): Array<{ name: string; type: string }> {
  const fields: Array<{ name: string; type: string }> = [];

  for (const [key, value] of Object.entries(obj)) {
    if (key === 'name' || key === 'id') continue;
    const type = typeof value === 'number' ? 'number' : typeof value === 'boolean' ? 'boolean' : 'string';
    const fieldName = prefix ? `${prefix}.${key}` : key;
    if (typeof value !== 'object' || value === null) {
      fields.push({ name: fieldName, type });
    }
  }

  return fields;
}

/** 从创建操作中提取业务规则 */
function extractRules(creates: HumanAction[]): DomainPattern['pattern']['rules'] {
  const rules: DomainPattern['pattern']['rules'] = [];

  for (const action of creates) {
    const after = action.after as Record<string, unknown> | null;
    if (after?.conditions || after?.rules) {
      const rawRules = (after.rules ?? after.conditions) as Array<Record<string, unknown>>;
      if (Array.isArray(rawRules)) {
        for (const r of rawRules) {
          rules.push({
            name: (r.name as string) ?? 'unnamed',
            condition: (r.condition as string) ?? '',
            action: (r.action as string) ?? '',
          });
        }
      }
    }
  }

  return rules;
}

/** 从创建操作中提取常用组件类型 */
function extractComponents(creates: HumanAction[]): string[] {
  const components = new Set<string>();

  for (const action of creates) {
    const after = action.after as Record<string, unknown> | null;
    const fields = (after?.fields ?? after?.columns) as Array<Record<string, unknown>> | undefined;
    if (Array.isArray(fields)) {
      for (const f of fields) {
        if (typeof f.component === 'string') {
          components.add(f.component);
        }
        if (typeof f.type === 'string' && f.type.startsWith('Jnpf')) {
          components.add(f.type);
        }
      }
    }
  }

  return [...components];
}

/**
 * DeepSeek 标准网关实现
 *
 * 对接 DeepSeek Chat Completion API（兼容 OpenAI 格式）。
 * API Key 从环境变量 VITE_DEEPSEEK_API_KEY 读取，不硬编码。
 *
 * 特性：
 *   - 指数退避重试（maxRetries=3，默认）
 *   - 流式输出（SSE 解析）
 *   - Token 累计统计
 *   - 健康检查（5s 超时 ping）
 *
 * @version 1.0.0
 * @module ai/llm/deepseek
 */

import type { LLMGateway, ChatRequest, ChatResponse, ChatMessage, ProviderUsageStats, TokenUsage } from './types';

// ============================================================
// 配置
// ============================================================

const DEFAULT_BASE_URL = 'https://api.deepseek.com/v1';
const DEFAULT_MODEL = 'deepseek-chat';
const DEFAULT_MAX_RETRIES = 3;
const DEFAULT_TIMEOUT_MS = 60000;
const HEALTH_CHECK_TIMEOUT_MS = 5000;

/** 可重置的 DeepSeek 请求（用于重试） */
interface PreparedRequest {
  url: string;
  headers: Record<string, string>;
  body: string;
  signal: AbortSignal;
}

// ============================================================
// DeepSeekGateway
// ============================================================

export class DeepSeekGateway implements LLMGateway {
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly model: string;
  private readonly maxRetries: number;
  private readonly defaultTimeout: number;

  // 累计统计
  private stats: ProviderUsageStats = {
    requestCount: 0,
    successCount: 0,
    failureCount: 0,
    totalTokens: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
    averageLatency: 0,
  };

  constructor(options?: { apiKey?: string; baseUrl?: string; model?: string; maxRetries?: number; defaultTimeout?: number }) {
    this.apiKey = options?.apiKey ?? import.meta.env.VITE_DEEPSEEK_API_KEY ?? '';
    this.baseUrl = options?.baseUrl ?? import.meta.env.VITE_DEEPSEEK_BASE_URL ?? DEFAULT_BASE_URL;
    this.model = options?.model ?? DEFAULT_MODEL;
    this.maxRetries = options?.maxRetries ?? DEFAULT_MAX_RETRIES;
    this.defaultTimeout = options?.defaultTimeout ?? DEFAULT_TIMEOUT_MS;

    if (!this.apiKey) {
      console.warn('[DeepSeek] VITE_DEEPSEEK_API_KEY 未配置，API 调用将失败');
    }
  }

  // ============================================================
  // 公开接口
  // ============================================================

  /** @inheritdoc */
  async chat(request: ChatRequest): Promise<ChatResponse> {
    const startTime = performance.now();
    const maxRetries = request.maxRetries ?? this.maxRetries;
    const timeout = request.timeout ?? this.defaultTimeout;

    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const signal = AbortSignal.timeout(timeout);
        const prepared = this.prepareRequest(request, signal);
        const response = await this.doChat(prepared);

        // 更新统计
        this.stats.requestCount++;
        this.stats.successCount++;
        this.accumulateTokens(response.usage);
        const latency = performance.now() - startTime;
        this.updateAverageLatency(latency);

        return {
          ...response,
          latency: Math.round(latency),
        };
      } catch (e) {
        lastError = e as Error;
        this.stats.failureCount++;

        if (attempt < maxRetries) {
          const delay = this.calculateBackoff(attempt);
          console.warn(`[DeepSeek] 请求失败 (尝试 ${attempt + 1}/${maxRetries + 1}): ${lastError.message}，${delay}ms 后重试...`);
          await this.sleep(delay);
        }
      }
    }

    throw new Error(`[DeepSeek] 全部 ${maxRetries + 1} 次尝试均失败: ${lastError?.message}`);
  }

  /** @inheritdoc */
  async *chatStream(request: ChatRequest): AsyncGenerator<string, void, undefined> {
    const timeout = request.timeout ?? this.defaultTimeout;
    const signal = AbortSignal.timeout(timeout);
    const prepared = this.prepareRequest({ ...request, responseFormat: 'text' }, signal);
    // 流式请求强制开启 stream
    const body = JSON.parse(prepared.body);
    body.stream = true;
    prepared.body = JSON.stringify(body);

    const startTime = performance.now();

    try {
      const response = await fetch(prepared.url, {
        method: 'POST',
        headers: prepared.headers,
        body: prepared.body,
        signal: prepared.signal,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => '');
        throw new Error(`HTTP ${response.status}: ${errorText}`);
      }

      if (!response.body) {
        throw new Error('响应体为空');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let accumulatedContent = '';
      let chunkCount = 0;

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          // 保留最后一个不完整行
          buffer = lines.pop() ?? '';

          for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith(':')) continue;

            if (trimmed === 'data: [DONE]') {
              return; // 流结束
            }

            if (trimmed.startsWith('data: ')) {
              const jsonStr = trimmed.slice(6);
              try {
                const parsed = JSON.parse(jsonStr);
                const delta = parsed.choices?.[0]?.delta?.content;
                if (delta) {
                  accumulatedContent += delta;
                  chunkCount++;
                  yield delta;
                }
              } catch {
                // SSE 中偶有非 JSON 行（如空行、注释），跳过
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      // 更新统计
      this.stats.requestCount++;
      this.stats.successCount++;
      const latency = performance.now() - startTime;
      this.updateAverageLatency(latency);

      // 对非结构化流式输出做估算
      const estimatedPromptTokens = this.estimateTokens(request.messages.map(m => m.content).join(' '));
      const estimatedCompletionTokens = this.estimateTokens(accumulatedContent);
      this.accumulateTokens({
        promptTokens: estimatedPromptTokens,
        completionTokens: estimatedCompletionTokens,
        totalTokens: estimatedPromptTokens + estimatedCompletionTokens,
      });
    } catch (e) {
      this.stats.failureCount++;
      throw e;
    }
  }

  /** @inheritdoc */
  async healthCheck(): Promise<boolean> {
    try {
      const signal = AbortSignal.timeout(HEALTH_CHECK_TIMEOUT_MS);
      const response = await fetch(`${this.baseUrl}/models`, {
        method: 'GET',
        headers: this.authHeaders(),
        signal,
      });
      return response.ok;
    } catch {
      return false;
    }
  }

  /** @inheritdoc */
  getProviderInfo(): { provider: string; model: string } {
    return { provider: 'deepseek', model: this.model };
  }

  /** 获取累计用量统计 */
  getUsageStats(): ProviderUsageStats {
    return { ...this.stats, totalTokens: { ...this.stats.totalTokens } };
  }

  // ============================================================
  // 内部方法
  // ============================================================

  /** 构建请求参数 */
  private prepareRequest(request: ChatRequest, signal: AbortSignal): PreparedRequest {
    const messages = this.buildMessages(request);
    const body: Record<string, unknown> = {
      model: this.model,
      messages,
      stream: false,
    };

    if (request.responseFormat === 'json') {
      body.response_format = { type: 'json_object' };
    }

    return {
      url: `${this.baseUrl}/chat/completions`,
      headers: {
        ...this.authHeaders(),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal,
    };
  }

  /** 发起非流式 HTTP 请求 */
  private async doChat(prepared: PreparedRequest): Promise<Omit<ChatResponse, 'latency'>> {
    const response = await fetch(prepared.url, {
      method: 'POST',
      headers: prepared.headers,
      body: prepared.body,
      signal: prepared.signal,
    });

    if (!response.ok) {
      const errorText = await response.text().catch(() => '');
      throw new Error(`HTTP ${response.status}: ${errorText}`);
    }

    const data = await response.json();
    return this.parseResponse(data);
  }

  /** 解析 DeepSeek API 响应 */
  private parseResponse(data: Record<string, unknown>): Omit<ChatResponse, 'latency'> {
    const choices = data.choices as Array<Record<string, unknown>> | undefined;
    if (!choices || choices.length === 0) {
      throw new Error('API 响应中无 choices');
    }

    const content = (choices[0].message as Record<string, unknown>)?.content as string | undefined;
    if (content === undefined) {
      throw new Error('API 响应中无 message.content');
    }

    const usage = data.usage as Record<string, number> | undefined;

    return {
      content,
      usage: {
        promptTokens: usage?.prompt_tokens ?? 0,
        completionTokens: usage?.completion_tokens ?? 0,
        totalTokens: usage?.total_tokens ?? 0,
      },
      model: (data.model as string) ?? this.model,
      provider: 'deepseek',
    };
  }

  /** 构建消息列表（必要时注入 system prompt） */
  private buildMessages(request: ChatRequest): ChatMessage[] {
    return request.messages.map(m => ({
      role: m.role,
      content: m.content,
    }));
  }

  /** 认证请求头 */
  private authHeaders(): Record<string, string> {
    return {
      Authorization: `Bearer ${this.apiKey}`,
    };
  }

  /** 指数退避计算（含随机抖动） */
  private calculateBackoff(attempt: number): number {
    const base = Math.pow(2, attempt) * 1000;
    const jitter = Math.random() * 500;
    return Math.min(base + jitter, 30000); // 最大 30s
  }

  /** 累计 Token */
  private accumulateTokens(usage: TokenUsage): void {
    this.stats.totalTokens.promptTokens += usage.promptTokens;
    this.stats.totalTokens.completionTokens += usage.completionTokens;
    this.stats.totalTokens.totalTokens += usage.totalTokens;
  }

  /** 更新平均延迟 */
  private updateAverageLatency(latency: number): void {
    const total = this.stats.successCount + this.stats.failureCount;
    if (total <= 1) {
      this.stats.averageLatency = latency;
    } else {
      // 指数移动平均
      this.stats.averageLatency = this.stats.averageLatency * 0.9 + latency * 0.1;
    }
  }

  /** 估算 Token 数（简易版：英文 4 字符≈1 token，中文 1 字符≈1 token） */
  private estimateTokens(text: string): number {
    const chineseChars = (text.match(/[一-鿿]/g) ?? []).length;
    const otherChars = text.length - chineseChars;
    return Math.ceil(chineseChars + otherChars / 4);
  }

  /** 异步延迟 */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

/**
 * 多供应商降级网关
 *
 * 按优先级顺序尝试多个 LLM 供应商，当前供应商连续失败达到阈值后自动切换。
 * 支持运行时动态切换、全量健康检查、当前供应商信息查询。
 *
 * 默认降级链：DeepSeek V4 Pro → MiMo-2.5-Pro → DeepSeek 标准 → 通义千问 → Ollama
 *
 * @version 1.0.0
 * @module ai/llm/fallback
 */

import type { LLMGateway, ChatRequest, ChatResponse, ChatMessage, ProviderUsageStats, TokenUsage } from './types';

/** 连续失败阈值，超过后自动切换到下一个供应商 */
const DEFAULT_MAX_CONSECUTIVE_FAILURES = 3;

export class FallbackLLMGateway implements LLMGateway {
  private readonly gateways: LLMGateway[];
  private readonly maxConsecutiveFailures: number;
  private currentIndex = 0;
  private failureCounts: number[];

  constructor(gateways: LLMGateway[], options?: { maxConsecutiveFailures?: number }) {
    if (!gateways || gateways.length === 0) {
      throw new Error('[FallbackLLMGateway] 必须提供至少一个 LLM 供应商');
    }
    this.gateways = gateways;
    this.maxConsecutiveFailures = options?.maxConsecutiveFailures ?? DEFAULT_MAX_CONSECUTIVE_FAILURES;
    this.failureCounts = new Array(gateways.length).fill(0);
  }

  // ============================================================
  // 公开接口
  // ============================================================

  /** @inheritdoc */
  async chat(request: ChatRequest): Promise<ChatResponse> {
    const errors: string[] = [];
    const tried = new Set<number>();

    // 从当前供应商开始轮询
    for (let offset = 0; offset < this.gateways.length; offset++) {
      const idx = (this.currentIndex + offset) % this.gateways.length;
      if (tried.has(idx)) continue;
      tried.add(idx);

      const gw = this.gateways[idx];
      try {
        const response = await gw.chat(request);
        // 成功 — 重置该供应商失败计数，更新当前索引
        this.failureCounts[idx] = 0;
        this.currentIndex = idx;
        return response;
      } catch (e) {
        const msg = (e as Error).message;
        errors.push(`[${gw.getProviderInfo().provider}] ${msg}`);
        this.failureCounts[idx]++;

        // 连续失败超阈值 → 降级
        if (this.failureCounts[idx] >= this.maxConsecutiveFailures) {
          console.warn(`[FallbackLLMGateway] ${gw.getProviderInfo().provider} 连续失败 ${this.failureCounts[idx]} 次，已降级`);
        }
      }
    }

    throw new Error(`[FallbackLLMGateway] 全部 ${this.gateways.length} 个供应商均失败:\n${errors.join('\n')}`);
  }

  /** @inheritdoc */
  async *chatStream(request: ChatRequest): AsyncGenerator<string, void, undefined> {
    const gw = this.gateways[this.currentIndex];
    try {
      yield* gw.chatStream(request);
      // 流式成功，重置失败计数
      this.failureCounts[this.currentIndex] = 0;
    } catch (e) {
      this.failureCounts[this.currentIndex]++;
      // 如果当前供应商流式失败，尝试下一个
      if (this.failureCounts[this.currentIndex] >= this.maxConsecutiveFailures) {
        await this.trySwitchProvider();
      }
      throw new Error(`[FallbackLLMGateway] 流式输出失败 (${gw.getProviderInfo().provider}): ${(e as Error).message}`);
    }
  }

  /** @inheritdoc */
  async healthCheck(): Promise<boolean> {
    const results = await Promise.all(
      this.gateways.map(async gw => {
        try {
          const alive = await gw.healthCheck();
          return { provider: gw.getProviderInfo().provider, alive };
        } catch {
          return { provider: gw.getProviderInfo().provider, alive: false };
        }
      }),
    );

    // 至少一个可用即认为整体健康
    const anyAlive = results.some(r => r.alive);
    if (!anyAlive) {
      console.warn('[FallbackLLMGateway] 所有供应商均不可用');
    }

    // 记录不健康的供应商
    for (const r of results) {
      if (!r.alive) {
        console.warn(`[FallbackLLMGateway] ${r.provider} 健康检查失败`);
      }
    }

    return anyAlive;
  }

  /** @inheritdoc */
  getProviderInfo(): { provider: string; model: string } {
    const current = this.gateways[this.currentIndex];
    if (!current) {
      return { provider: 'fallback', model: 'none' };
    }
    const info = current.getProviderInfo();
    return { provider: `fallback:${info.provider}`, model: info.model };
  }

  // ============================================================
  // 扩展方法
  // ============================================================

  /** 获取当前主供应商 */
  getCurrentGateway(): LLMGateway {
    return this.gateways[this.currentIndex];
  }

  /** 获取所有供应商列表 */
  getGateways(): LLMGateway[] {
    return [...this.gateways];
  }

  /** 获取所有供应商的健康状态 */
  async getHealthStatus(): Promise<Array<{ provider: string; model: string; alive: boolean; consecutiveFailures: number }>> {
    const results = await Promise.all(
      this.gateways.map(async (gw, i) => {
        let alive = false;
        try {
          alive = await gw.healthCheck();
        } catch {
          // alive stays false
        }
        const info = gw.getProviderInfo();
        return {
          provider: info.provider,
          model: info.model,
          alive,
          consecutiveFailures: this.failureCounts[i] ?? 0,
        };
      }),
    );
    return results;
  }

  /** 手动切换到指定索引的供应商 */
  switchTo(index: number): void {
    if (index < 0 || index >= this.gateways.length) {
      throw new Error(`[FallbackLLMGateway] 无效的供应商索引: ${index}`);
    }
    this.currentIndex = index;
  }

  /** 重置所有失败计数 */
  resetFailures(): void {
    this.failureCounts = new Array(this.gateways.length).fill(0);
  }

  // ============================================================
  // 内部方法
  // ============================================================

  /** 尝试切换到下一个健康供应商 */
  private async trySwitchProvider(): Promise<void> {
    const startIdx = this.currentIndex;
    for (let offset = 1; offset < this.gateways.length; offset++) {
      const idx = (startIdx + offset) % this.gateways.length;
      if (this.failureCounts[idx] < this.maxConsecutiveFailures) {
        const alive = await this.gateways[idx].healthCheck().catch(() => false);
        if (alive) {
          console.log(
            `[FallbackLLMGateway] 切换供应商: ${this.gateways[startIdx].getProviderInfo().provider} → ${this.gateways[idx].getProviderInfo().provider}`,
          );
          this.currentIndex = idx;
          return;
        }
      }
    }
  }
}

/**
 * Ollama 本地模型网关实现
 *
 * 对接本地 Ollama 服务，无需 API Key。
 * 端点格式与 OpenAI 不同（/api/chat），独立实现。
 *
 * @version 1.0.0
 * @module ai/llm/ollama
 */

import type { LLMGateway, ChatRequest, ChatResponse, ChatMessage, ProviderUsageStats, TokenUsage } from './types';

// ============================================================
// 配置
// ============================================================

const DEFAULT_BASE_URL = 'http://localhost:11434';
const DEFAULT_MODEL = 'llama3';
const DEFAULT_TIMEOUT_MS = 120000; // 本地模型可能较慢
const HEALTH_CHECK_TIMEOUT_MS = 5000;

// ============================================================
// OllamaGateway
// ============================================================

export class OllamaGateway implements LLMGateway {
  private readonly baseUrl: string;
  private readonly model: string;
  private readonly defaultTimeout: number;

  private stats: ProviderUsageStats = {
    requestCount: 0,
    successCount: 0,
    failureCount: 0,
    totalTokens: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
    averageLatency: 0,
  };

  constructor(options?: { baseUrl?: string; model?: string; defaultTimeout?: number }) {
    this.baseUrl = options?.baseUrl ?? import.meta.env.VITE_OLLAMA_BASE_URL ?? DEFAULT_BASE_URL;
    this.model = options?.model ?? DEFAULT_MODEL;
    this.defaultTimeout = options?.defaultTimeout ?? DEFAULT_TIMEOUT_MS;
  }

  /** @inheritdoc */
  async chat(request: ChatRequest): Promise<ChatResponse> {
    const startTime = performance.now();
    const timeout = request.timeout ?? this.defaultTimeout;

    try {
      const signal = AbortSignal.timeout(timeout);
      const response = await fetch(`${this.baseUrl}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: this.model,
          messages: request.messages.map(m => ({ role: m.role, content: m.content })),
          stream: false,
          format: request.responseFormat === 'json' ? 'json' : undefined,
        }),
        signal,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => '');
        throw new Error(`HTTP ${response.status}: ${errorText}`);
      }

      const data = await response.json();
      const content = (data.message?.content as string) ?? '';

      const usage: TokenUsage = {
        promptTokens: (data.prompt_eval_count as number) ?? 0,
        completionTokens: (data.eval_count as number) ?? 0,
        totalTokens: ((data.prompt_eval_count as number) ?? 0) + ((data.eval_count as number) ?? 0),
      };

      this.stats.requestCount++;
      this.stats.successCount++;
      this.accumulateTokens(usage);
      const latency = performance.now() - startTime;
      this.updateAverageLatency(latency);

      return {
        content,
        usage,
        model: (data.model as string) ?? this.model,
        provider: 'ollama',
        latency: Math.round(latency),
      };
    } catch (e) {
      this.stats.failureCount++;
      throw new Error(`[Ollama] 请求失败: ${(e as Error).message}`);
    }
  }

  /** @inheritdoc */
  async *chatStream(request: ChatRequest): AsyncGenerator<string, void, undefined> {
    const timeout = request.timeout ?? this.defaultTimeout;
    const signal = AbortSignal.timeout(timeout);

    try {
      const response = await fetch(`${this.baseUrl}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: this.model,
          messages: request.messages.map(m => ({ role: m.role, content: m.content })),
          stream: true,
        }),
        signal,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => '');
        throw new Error(`HTTP ${response.status}: ${errorText}`);
      }

      if (!response.body) {
        throw new Error('响应体为空');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let accumulatedContent = '';

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() ?? '';

          for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed) continue;

            try {
              const parsed = JSON.parse(trimmed);
              const delta = parsed.message?.content as string | undefined;
              if (delta) {
                accumulatedContent += delta;
                yield delta;
              }
              if (parsed.done) {
                return;
              }
            } catch {
              // 跳过无法解析的行
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      this.stats.requestCount++;
      this.stats.successCount++;
      this.accumulateTokens({
        promptTokens: this.estimateTokens(request.messages.map(m => m.content).join(' ')),
        completionTokens: this.estimateTokens(accumulatedContent),
        totalTokens: 0,
      });
    } catch (e) {
      this.stats.failureCount++;
      throw e;
    }
  }

  /** @inheritdoc */
  async healthCheck(): Promise<boolean> {
    try {
      const signal = AbortSignal.timeout(HEALTH_CHECK_TIMEOUT_MS);
      const response = await fetch(`${this.baseUrl}/api/tags`, { signal });
      return response.ok;
    } catch {
      return false;
    }
  }

  /** @inheritdoc */
  getProviderInfo(): { provider: string; model: string } {
    return { provider: 'ollama', model: this.model };
  }

  /** 获取累计用量统计 */
  getUsageStats(): ProviderUsageStats {
    return { ...this.stats, totalTokens: { ...this.stats.totalTokens } };
  }

  // ============================================================
  // 内部方法
  // ============================================================

  private accumulateTokens(usage: TokenUsage): void {
    this.stats.totalTokens.promptTokens += usage.promptTokens;
    this.stats.totalTokens.completionTokens += usage.completionTokens;
    this.stats.totalTokens.totalTokens += usage.totalTokens;
  }

  private updateAverageLatency(latency: number): void {
    const total = this.stats.successCount + this.stats.failureCount;
    if (total <= 1) {
      this.stats.averageLatency = latency;
    } else {
      this.stats.averageLatency = this.stats.averageLatency * 0.9 + latency * 0.1;
    }
  }

  private estimateTokens(text: string): number {
    const chineseChars = (text.match(/[一-鿿]/g) ?? []).length;
    const otherChars = text.length - chineseChars;
    return Math.ceil(chineseChars + otherChars / 4);
  }
}

/**
 * Pipeline Orchestrator (A1)
 * @module ai/pipeline/orchestrator
 */

import type { LLMGateway } from '../llm/types';
import type { AgentContext } from '../agents/base';
import { RequirementAnalystAgent } from '../agents/requirement-analyst';
import { ArchitectAgent } from '../agents/architect';
import { UIUXAgent } from '../agents/ui-ux';
import { DatabaseAgent } from '../agents/database';
import type { PipelineStage } from './stages';
import { getNextStage } from './stages';
import { type PipelineState, createInitialState, transition, advanceStage, updateConfidence } from './state-machine';

export class OrchestratorAgent {
  private requirementAgent: RequirementAnalystAgent;
  private architectAgent: ArchitectAgent;
  private uiuxAgent: UIUXAgent;
  private databaseAgent: DatabaseAgent;

  constructor(llm: LLMGateway) {
    this.requirementAgent = new RequirementAnalystAgent(llm);
    this.architectAgent = new ArchitectAgent(llm);
    this.uiuxAgent = new UIUXAgent(llm);
    this.databaseAgent = new DatabaseAgent(llm);
  }

  async advance(state: PipelineState, userInput = ''): Promise<PipelineState> {
    state = transition(state, 'running');
    try {
      switch (state.currentStage) {
        case 'requirement':
          return this.doRequirement(state, userInput);
        case 'architecture':
          return this.doArchitecture(state);
        case 'design':
          return this.doDesign(state);
        case 'development':
          return this.doDevelopment(state);
        case 'delivery':
          return this.doDelivery(state);
      }
    } catch (e) {
      state = transition(state, 'failed', (e as Error).message);
      state.error = (e as Error).message;
    }
    return state;
  }

  async confirm(state: PipelineState): Promise<PipelineState> {
    const next = getNextStage(state.currentStage);
    if (!next) {
      state.status = 'completed';
      return state;
    }
    state = advanceStage(state, next);
    if (state.currentStage === 'development') return this.advance(state);
    return state;
  }

  async revise(state: PipelineState, feedback: string): Promise<PipelineState> {
    return this.advance(transition(state, 'running', `revise: ${feedback}`), feedback);
  }

  private async doRequirement(state: PipelineState, userInput: string): Promise<PipelineState> {
    const r = await this.requirementAgent.analyze(userInput);
    state.requirement = r.data;
    return transition(updateConfidence(state, r.confidence), 'waiting_confirmation');
  }

  private async doArchitecture(state: PipelineState): Promise<PipelineState> {
    const r = await this.architectAgent.design(JSON.stringify(state.requirement ?? {}));
    state.architecture = r.data;
    return transition(updateConfidence(state, r.confidence), 'waiting_confirmation');
  }

  private async doDesign(state: PipelineState): Promise<PipelineState> {
    const ctx: AgentContext = { currentIR: state.architecture as Record<string, unknown> };
    const [ui, db] = await Promise.all([
      this.uiuxAgent.design(JSON.stringify(state.architecture ?? {}), ctx),
      this.databaseAgent.design(JSON.stringify(state.architecture ?? {}), ctx),
    ]);
    state.design = { ui: ui.data, database: db.data };
    return transition(updateConfidence(state, (ui.confidence + db.confidence) / 2), 'waiting_confirmation');
  }

  private async doDevelopment(state: PipelineState): Promise<PipelineState> {
    state.development = { code: JSON.stringify(state.design?.ui ?? {}, null, 2), target: 'vue3-web' };
    return transition(state, 'waiting_confirmation');
  }

  private async doDelivery(state: PipelineState): Promise<PipelineState> {
    state.delivery = { url: '', zip: 'ready' };
    state.status = 'completed';
    return state;
  }

  getStagePrompt(stage: PipelineStage): string {
    return (
      (
        { requirement: '描述需求', architecture: '确认领域模型', design: '生成UI+DB方案', development: '生成代码中', delivery: '确认下载' } as Record<
          string,
          string
        >
      )[stage] ?? ''
    );
  }
}

/**
 * Pipeline state machine
 * @module ai/pipeline/state-machine
 */

import type { PipelineStage } from './stages';

export type PipelineStatus = 'idle' | 'running' | 'waiting_confirmation' | 'completed' | 'failed' | 'expert_mode';

export interface StageHistoryEntry {
  stage: PipelineStage;
  action: string;
  timestamp: string;
  confidence?: number;
}

export interface PipelineState {
  currentStage: PipelineStage;
  status: PipelineStatus;
  error?: string;
  requirement?: unknown;
  architecture?: unknown;
  design?: { ui: unknown; database: unknown };
  development?: { code: string; target: string };
  delivery?: { url: string; zip: string };
  history: StageHistoryEntry[];
  confidence: number;
}

export function createInitialState(): PipelineState {
  return { currentStage: 'requirement', status: 'idle', history: [], confidence: 1.0 };
}

const VALID_TRANSITIONS: Record<PipelineStatus, PipelineStatus[]> = {
  idle: ['running', 'expert_mode'],
  running: ['waiting_confirmation', 'failed', 'expert_mode'],
  waiting_confirmation: ['running', 'completed', 'expert_mode'],
  completed: ['running'],
  failed: ['running', 'expert_mode'],
  expert_mode: ['running'],
};

export function canTransition(from: PipelineStatus, to: PipelineStatus): boolean {
  return VALID_TRANSITIONS[from]?.includes(to) ?? false;
}

export function transition(state: PipelineState, to: PipelineStatus, reason?: string): PipelineState {
  if (!canTransition(state.status, to)) return state;
  state.status = to;
  state.history.push({ stage: state.currentStage, action: `→ ${to}${reason ? `: ${reason}` : ''}`, timestamp: new Date().toISOString() });
  return state;
}

export function updateConfidence(state: PipelineState, confidence: number): PipelineState {
  state.confidence = Math.max(0, Math.min(1, confidence));
  if (confidence < 0.6 && state.status !== 'expert_mode') {
    state.status = 'expert_mode';
    state.history.push({
      stage: state.currentStage,
      action: `expert_mode: low confidence ${(confidence * 100).toFixed(0)}%`,
      timestamp: new Date().toISOString(),
    });
  }
  return state;
}

export function advanceStage(state: PipelineState, next: PipelineStage): PipelineState {
  state.history.push({ stage: state.currentStage, action: `advance: ${state.currentStage} → ${next}`, timestamp: new Date().toISOString() });
  state.currentStage = next;
  state.status = 'running';
  return state;
}

/**
 * 编译器
 * 将 AST 编译为可执行函数
 *
 * 生成一个接受 context 参数的函数，
 * 在 context 中查找变量值。
 *
 * 安全声明：此模块使用 new Function 构造器，但输入已经过
 * tokenize → parse → securityCheck 三重校验，
 * 输入中不可能包含任意代码，只有生成的安全表达式。
 */

import type { ASTNode } from './parser';

export type CompiledExpr = (context: Record<string, unknown>) => unknown;

export function compile(ast: ASTNode): CompiledExpr {
  const code = generateCode(ast);
  return new Function('context', `"use strict"; return (${code});`) as CompiledExpr;
}

function generateCode(node: ASTNode): string {
  switch (node.type) {
    case 'Literal':
      if (node.value === null) return 'null';
      if (typeof node.value === 'string') return JSON.stringify(node.value);
      return String(node.value);

    case 'Identifier':
      if (node.name === 'undefined') return 'undefined';
      return `context[${JSON.stringify(node.name)}]`;

    case 'MemberExpression': {
      const obj = generateCode(node.object);
      return `(${obj})[${JSON.stringify(node.property)}]`;
    }

    case 'IndexExpression': {
      const obj = generateCode(node.object);
      const idx = generateCode(node.index);
      return `(${obj})[${idx}]`;
    }

    case 'CallExpression': {
      const callee = generateCode(node.callee);
      const args = node.args.map(generateCode).join(', ');
      return `(${callee})(${args})`;
    }

    case 'UnaryExpression':
      return `(${node.operator}${generateCode(node.argument)})`;

    case 'BinaryExpression':
      return `(${generateCode(node.left)} ${node.operator} ${generateCode(node.right)})`;

    case 'LogicalExpression':
      return `(${generateCode(node.left)} ${node.operator} ${generateCode(node.right)})`;

    case 'ConditionalExpression':
      return `(${generateCode(node.test)} ? ${generateCode(node.consequent)} : ${generateCode(node.alternate)})`;

    default:
      throw new Error(`[compiler] 未知节点类型: ${(node as ASTNode).type}`);
  }
}

/**
 * 白名单函数库
 * 所有函数必须遵守纯函数约束：
 *   1. 不访问 this
 *   2. 不访问闭包外变量
 *   3. 不调用 eval / new Function
 *   4. 不访问 window / document / globalThis
 *   5. 只使用参数 + 本地变量
 */

export const WHITELIST_FUNCTIONS: Record<string, (...args: unknown[]) => unknown> = {
  // 字符串
  LEN: (v: unknown) => String(v ?? '').length,
  UPPER: (v: unknown) => String(v ?? '').toUpperCase(),
  LOWER: (v: unknown) => String(v ?? '').toLowerCase(),
  TRIM: (v: unknown) => String(v ?? '').trim(),
  CONTAINS: (v: unknown, sub: unknown) => String(v ?? '').includes(String(sub)),
  REPLACE: (v: unknown, old: unknown, rep: unknown) => String(v ?? '').replace(String(old), String(rep)),

  // 数学
  ROUND: (v: unknown, n?: unknown) => {
    const num = Number(v);
    if (isNaN(num)) return v;
    const factor = Math.pow(10, Number(n) || 0);
    return Math.round(num * factor) / factor;
  },
  CEIL: (v: unknown) => Math.ceil(Number(v)),
  FLOOR: (v: unknown) => Math.floor(Number(v)),
  ABS: (v: unknown) => Math.abs(Number(v)),
  MAX: (...args: unknown[]) => Math.max(...args.map(Number)),
  MIN: (...args: unknown[]) => Math.min(...args.map(Number)),

  // 条件
  IF: (cond: unknown, thenVal: unknown, elseVal: unknown) => (cond ? thenVal : elseVal),
  IF_EMPTY: (v: unknown, fallback: unknown) => (v === '' || v === null || v === undefined ? fallback : v),
  IF_NULL: (v: unknown, fallback: unknown) => (v === null || v === undefined ? fallback : v),

  // 日期
  TODAY: () => new Date().toISOString().slice(0, 10),
  NOW: () => new Date().toISOString(),
  FORMAT_DATE: (v: unknown, fmt?: unknown) => {
    if (!v) return '';
    const d = new Date(v as string);
    if (isNaN(d.getTime())) return String(v);
    const pad = (n: number) => String(n).padStart(2, '0');
    return String(fmt || 'yyyy-MM-dd')
      .replace('yyyy', String(d.getFullYear()))
      .replace('MM', pad(d.getMonth() + 1))
      .replace('dd', pad(d.getDate()))
      .replace('HH', pad(d.getHours()))
      .replace('mm', pad(d.getMinutes()))
      .replace('ss', pad(d.getSeconds()));
  },

  // 格式化
  FORMAT_MONEY: (v: unknown) => {
    const num = Number(v);
    if (isNaN(num)) return v;
    return num.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  },
  MASK_PHONE: (v: unknown) => {
    const s = String(v);
    return s.length >= 11 ? s.replace(/(\d{3})\d{4}(\d{4})/, '$1****$2') : s;
  },
  MASK_ID_CARD: (v: unknown) => {
    const s = String(v);
    return s.length >= 18 ? s.replace(/(\d{6})\d{8}(\d{4})/, '$1********$2') : s;
  },
};

/**
 * 语法分析器
 * 将 Token 序列解析为 AST
 *
 * 运算符优先级（低→高）：
 *   ?? → || → && → == != > < >= <= → + - → * / % → ! 一元 → () 成员访问
 */

import type { Token, TokenType } from './tokenizer';

// ============================================================
// AST 节点类型
// ============================================================

export type ASTNode =
  | LiteralNode
  | IdentifierNode
  | MemberExprNode
  | CallExprNode
  | UnaryExprNode
  | BinaryExprNode
  | LogicalExprNode
  | ConditionalExprNode
  | IndexExprNode;

export interface LiteralNode {
  type: 'Literal';
  value: string | number | boolean | null;
}

export interface IdentifierNode {
  type: 'Identifier';
  name: string;
}

export interface MemberExprNode {
  type: 'MemberExpression';
  object: ASTNode;
  property: string;
}

export interface IndexExprNode {
  type: 'IndexExpression';
  object: ASTNode;
  index: ASTNode;
}

export interface CallExprNode {
  type: 'CallExpression';
  callee: ASTNode;
  args: ASTNode[];
}

export interface UnaryExprNode {
  type: 'UnaryExpression';
  operator: '!' | '-';
  argument: ASTNode;
}

export interface BinaryExprNode {
  type: 'BinaryExpression';
  operator: '+' | '-' | '*' | '/' | '%' | '==' | '!=' | '>' | '<' | '>=' | '<=';
  left: ASTNode;
  right: ASTNode;
}

export interface LogicalExprNode {
  type: 'LogicalExpression';
  operator: '&&' | '||' | '??';
  left: ASTNode;
  right: ASTNode;
}

export interface ConditionalExprNode {
  type: 'ConditionalExpression';
  test: ASTNode;
  consequent: ASTNode;
  alternate: ASTNode;
}

// ============================================================
// Parser
// ============================================================

export function parse(tokens: Token[]): ASTNode {
  let pos = 0;

  function peek(): Token {
    return tokens[pos];
  }
  function advance(): Token {
    return tokens[pos++];
  }
  function expect(type: TokenType): Token {
    const t = advance();
    if (t.type !== type) throw new Error(`[parser] 期望 ${type}，得到 ${t.type} (pos: ${t.pos})`);
    return t;
  }

  function parseExpression(): ASTNode {
    return parseConditional();
  }

  function parseConditional(): ASTNode {
    const expr = parseNullCoalesce();
    if (peek().type === 'QUESTION') {
      advance();
      const consequent = parseExpression();
      expect('COLON');
      const alternate = parseConditional();
      return { type: 'ConditionalExpression', test: expr, consequent, alternate };
    }
    return expr;
  }

  function parseNullCoalesce(): ASTNode {
    let expr = parseOr();
    while (peek().type === 'NULL_COALESCE') {
      advance();
      const right = parseOr();
      expr = { type: 'LogicalExpression', operator: '??', left: expr, right };
    }
    return expr;
  }

  function parseOr(): ASTNode {
    let expr = parseAnd();
    while (peek().type === 'OR') {
      advance();
      const right = parseAnd();
      expr = { type: 'LogicalExpression', operator: '||', left: expr, right };
    }
    return expr;
  }

  function parseAnd(): ASTNode {
    let expr = parseComparison();
    while (peek().type === 'AND') {
      advance();
      const right = parseComparison();
      expr = { type: 'LogicalExpression', operator: '&&', left: expr, right };
    }
    return expr;
  }

  function parseComparison(): ASTNode {
    let expr = parseAddition();
    while (['EQ', 'NE', 'GT', 'LT', 'GTE', 'LTE'].includes(peek().type)) {
      const op = advance().value as BinaryExprNode['operator'];
      const right = parseAddition();
      expr = { type: 'BinaryExpression', operator: op, left: expr, right };
    }
    return expr;
  }

  function parseAddition(): ASTNode {
    let expr = parseMultiplication();
    while (peek().type === 'PLUS' || peek().type === 'MINUS') {
      const op = advance().value as '+' | '-';
      const right = parseMultiplication();
      expr = { type: 'BinaryExpression', operator: op, left: expr, right };
    }
    return expr;
  }

  function parseMultiplication(): ASTNode {
    let expr = parseUnary();
    while (['STAR', 'SLASH', 'PERCENT'].includes(peek().type)) {
      const op = advance().value as '*' | '/' | '%';
      const right = parseUnary();
      expr = { type: 'BinaryExpression', operator: op, left: expr, right };
    }
    return expr;
  }

  function parseUnary(): ASTNode {
    if (peek().type === 'NOT') {
      advance();
      return { type: 'UnaryExpression', operator: '!', argument: parseUnary() };
    }
    if (peek().type === 'MINUS') {
      advance();
      return { type: 'UnaryExpression', operator: '-', argument: parseUnary() };
    }
    return parsePostfix();
  }

  function parsePostfix(): ASTNode {
    let expr = parsePrimary();
    while (true) {
      if (peek().type === 'DOT') {
        advance();
        const prop = expect('IDENT').value;
        expr = { type: 'MemberExpression', object: expr, property: prop };
      } else if (peek().type === 'LBRACKET') {
        advance();
        const index = parseExpression();
        expect('RBRACKET');
        expr = { type: 'IndexExpression', object: expr, index };
      } else if (peek().type === 'LPAREN') {
        advance();
        const args: ASTNode[] = [];
        if (peek().type !== 'RPAREN') {
          args.push(parseExpression());
          while (peek().type === 'COMMA') {
            advance();
            args.push(parseExpression());
          }
        }
        expect('RPAREN');
        expr = { type: 'CallExpression', callee: expr, args };
      } else {
        break;
      }
    }
    return expr;
  }

  function parsePrimary(): ASTNode {
    const t = peek();
    switch (t.type) {
      case 'NUMBER':
        advance();
        return { type: 'Literal', value: Number(t.value) };
      case 'STRING':
        advance();
        return { type: 'Literal', value: t.value };
      case 'TRUE':
        advance();
        return { type: 'Literal', value: true };
      case 'FALSE':
        advance();
        return { type: 'Literal', value: false };
      case 'NULL':
        advance();
        return { type: 'Literal', value: null };
      case 'UNDEFINED':
        advance();
        return { type: 'Literal', value: null };
      case 'IDENT':
        advance();
        return { type: 'Identifier', name: t.value };
      case 'LPAREN':
        advance();
        const expr = parseExpression();
        expect('RPAREN');
        return expr;
      default:
        throw new Error(`[parser] 无法解析: ${t.type} "${t.value}" (pos: ${t.pos})`);
    }
  }

  const ast = parseExpression();
  if (peek().type !== 'EOF') {
    throw new Error(`[parser] 表达式未结束，剩余: ${peek().type} "${peek().value}"`);
  }
  return ast;
}

/**
 * 安全检查
 * 在 AST 层面拒绝危险结构
 *
 * 检查项：
 *   1. 禁止 this 关键字
 *   2. 禁止赋值操作
 *   3. 禁止函数定义
 *   4. 禁止访问危险属性
 *   5. 限制调用深度
 */

import type { ASTNode } from './parser';

const BLOCKED_PROPERTIES = new Set(['__proto__', 'constructor', 'prototype', 'caller', 'callee', 'arguments']);

const MAX_DEPTH = 20;
const MAX_CALL_ARGS = 10;

export function securityCheck(node: ASTNode, depth = 0): void {
  if (depth > MAX_DEPTH) {
    throw new Error('[security] 表达式嵌套过深，可能存在恶意构造');
  }

  switch (node.type) {
    case 'Identifier':
      if (node.name === 'this') {
        throw new Error('[security] 禁止使用 this');
      }
      break;

    case 'MemberExpression':
      if (BLOCKED_PROPERTIES.has(node.property)) {
        throw new Error(`[security] 禁止访问属性: ${node.property}`);
      }
      securityCheck(node.object, depth + 1);
      break;

    case 'IndexExpression':
      securityCheck(node.object, depth + 1);
      securityCheck(node.index, depth + 1);
      break;

    case 'CallExpression':
      if (node.args.length > MAX_CALL_ARGS) {
        throw new Error(`[security] 函数调用参数过多: ${node.args.length} > ${MAX_CALL_ARGS}`);
      }
      securityCheck(node.callee, depth + 1);
      node.args.forEach(arg => securityCheck(arg, depth + 1));
      break;

    case 'UnaryExpression':
      securityCheck(node.argument, depth + 1);
      break;

    case 'BinaryExpression':
      securityCheck(node.left, depth + 1);
      securityCheck(node.right, depth + 1);
      break;

    case 'LogicalExpression':
      securityCheck(node.left, depth + 1);
      securityCheck(node.right, depth + 1);
      break;

    case 'ConditionalExpression':
      securityCheck(node.test, depth + 1);
      securityCheck(node.consequent, depth + 1);
      securityCheck(node.alternate, depth + 1);
      break;

    case 'Literal':
      // 字面量本身是安全的
      break;
  }
}

/**
 * 词法分析器
 * 将表达式字符串拆分为 Token 序列
 *
 * 支持的 Token 类型：
 *   NUMBER, STRING, IDENT, DOT, COMMA,
 *   PLUS, MINUS, STAR, SLASH, PERCENT,
 *   EQ, NE, GT, LT, GTE, LTE,
 *   AND, OR, NOT,
 *   LPAREN, RPAREN, LBRACKET, RBRACKET,
 *   QUESTION, COLON,
 *   NULL_COALESCE,
 *   TRUE, FALSE, NULL, UNDEFINED,
 *   EOF
 */

export type TokenType =
  | 'NUMBER'
  | 'STRING'
  | 'IDENT'
  | 'DOT'
  | 'COMMA'
  | 'PLUS'
  | 'MINUS'
  | 'STAR'
  | 'SLASH'
  | 'PERCENT'
  | 'EQ'
  | 'NE'
  | 'GT'
  | 'LT'
  | 'GTE'
  | 'LTE'
  | 'AND'
  | 'OR'
  | 'NOT'
  | 'LPAREN'
  | 'RPAREN'
  | 'LBRACKET'
  | 'RBRACKET'
  | 'QUESTION'
  | 'COLON'
  | 'NULL_COALESCE'
  | 'TRUE'
  | 'FALSE'
  | 'NULL'
  | 'UNDEFINED'
  | 'EOF';

export interface Token {
  type: TokenType;
  value: string;
  pos: number;
}

// 危险关键字——在词法阶段直接拒绝
const BLOCKED_IDENTS = new Set([
  'window',
  'document',
  'globalThis',
  'global',
  'self',
  'eval',
  'Function',
  'setTimeout',
  'setInterval',
  'fetch',
  'XMLHttpRequest',
  'ActiveXObject',
  'import',
  'require',
  'module',
  'exports',
  '__proto__',
  'constructor',
  'prototype',
]);

const KEYWORDS: Record<string, TokenType> = {
  true: 'TRUE',
  false: 'FALSE',
  null: 'NULL',
  undefined: 'UNDEFINED',
};

export function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;

  while (pos < input.length) {
    const ch = input[pos];

    // 跳过空白
    if (/\s/.test(ch)) {
      pos++;
      continue;
    }

    // 数字
    if (/[0-9]/.test(ch) || (ch === '.' && /[0-9]/.test(input[pos + 1] ?? ''))) {
      let num = '';
      while (pos < input.length && /[0-9.]/.test(input[pos])) num += input[pos++];
      tokens.push({ type: 'NUMBER', value: num, pos: pos - num.length });
      continue;
    }

    // 字符串（单引号或双引号）
    if (ch === "'" || ch === '"') {
      const quote = ch;
      let str = '';
      const start = pos;
      pos++; // 跳过开头引号
      while (pos < input.length && input[pos] !== quote) {
        if (input[pos] === '\\') {
          str += input[pos++];
        } // 保留转义
        str += input[pos++];
      }
      pos++; // 跳过结尾引号
      tokens.push({ type: 'STRING', value: str, pos: start });
      continue;
    }

    // 标识符
    if (/[a-zA-Z_$]/.test(ch)) {
      let ident = '';
      const start = pos;
      while (pos < input.length && /[a-zA-Z0-9_$]/.test(input[pos])) ident += input[pos++];

      // 安全检查：拒绝危险关键字
      if (BLOCKED_IDENTS.has(ident)) {
        throw new Error(`[tokenizer] 安全拒绝: 禁止使用 "${ident}" (pos: ${start})`);
      }

      const keywordType = KEYWORDS[ident];
      tokens.push({ type: keywordType || 'IDENT', value: ident, pos: start });
      continue;
    }

    // 运算符和标点
    switch (ch) {
      case '.':
        tokens.push({ type: 'DOT', value: '.', pos });
        pos++;
        break;
      case ',':
        tokens.push({ type: 'COMMA', value: ',', pos });
        pos++;
        break;
      case '+':
        tokens.push({ type: 'PLUS', value: '+', pos });
        pos++;
        break;
      case '-':
        tokens.push({ type: 'MINUS', value: '-', pos });
        pos++;
        break;
      case '*':
        tokens.push({ type: 'STAR', value: '*', pos });
        pos++;
        break;
      case '/':
        tokens.push({ type: 'SLASH', value: '/', pos });
        pos++;
        break;
      case '%':
        tokens.push({ type: 'PERCENT', value: '%', pos });
        pos++;
        break;
      case '(':
        tokens.push({ type: 'LPAREN', value: '(', pos });
        pos++;
        break;
      case ')':
        tokens.push({ type: 'RPAREN', value: ')', pos });
        pos++;
        break;
      case '[':
        tokens.push({ type: 'LBRACKET', value: '[', pos });
        pos++;
        break;
      case ']':
        tokens.push({ type: 'RBRACKET', value: ']', pos });
        pos++;
        break;
      case '?':
        if (input[pos + 1] === '?') {
          tokens.push({ type: 'NULL_COALESCE', value: '??', pos });
          pos += 2;
        } else {
          tokens.push({ type: 'QUESTION', value: '?', pos });
          pos++;
        }
        break;
      case ':':
        tokens.push({ type: 'COLON', value: ':', pos });
        pos++;
        break;
      case '=':
        if (input[pos + 1] === '=') {
          tokens.push({ type: 'EQ', value: '==', pos });
          pos += 2;
        } else {
          throw new Error(`[tokenizer] 不支持赋值操作 (pos: ${pos})`);
        }
        break;
      case '!':
        if (input[pos + 1] === '=') {
          tokens.push({ type: 'NE', value: '!=', pos });
          pos += 2;
        } else {
          tokens.push({ type: 'NOT', value: '!', pos });
          pos++;
        }
        break;
      case '>':
        if (input[pos + 1] === '=') {
          tokens.push({ type: 'GTE', value: '>=', pos });
          pos += 2;
        } else {
          tokens.push({ type: 'GT', value: '>', pos });
          pos++;
        }
        break;
      case '<':
        if (input[pos + 1] === '=') {
          tokens.push({ type: 'LTE', value: '<=', pos });
          pos += 2;
        } else {
          tokens.push({ type: 'LT', value: '<', pos });
          pos++;
        }
        break;
      case '&':
        if (input[pos + 1] === '&') {
          tokens.push({ type: 'AND', value: '&&', pos });
          pos += 2;
        } else {
          throw new Error(`[tokenizer] 不支持位运算 (pos: ${pos})`);
        }
        break;
      case '|':
        if (input[pos + 1] === '|') {
          tokens.push({ type: 'OR', value: '||', pos });
          pos += 2;
        } else {
          throw new Error(`[tokenizer] 不支持位运算 (pos: ${pos})`);
        }
        break;
      default:
        throw new Error(`[tokenizer] 未知字符: "${ch}" (pos: ${pos})`);
    }
  }

  tokens.push({ type: 'EOF', value: '', pos });
  return tokens;
}

/**
 * IRDependencyGraph — 依赖图构建器（P0 审判令一）
 *
 * 遍历 IR 所有节点，解析节点间的引用关系。
 * 正向边：node.id → 它引用的节点 ID
 * 反向边：node.id → 引用它的节点 ID（正向边的转置）
 *
 * @module ir/dependency-graph
 * @version 1.0.0
 */

import type { FormPageIR } from './types';

// ============================================================
// 类型定义
// ============================================================

export interface IRDependencyGraph {
  /** 所有节点（key = node.id） */
  nodes: Map<string, IRNode>;
  /** 正向边：node.id → 它引用的节点 ID 集合 */
  forwardEdges: Map<string, Set<string>>;
  /** 反向边：node.id → 引用它的节点 ID 集合（正向边的转置） */
  reverseEdges: Map<string, Set<string>>;
}

/** IR 节点抽象 */
export interface IRNode {
  id: string;
  type: string;
  name: string;
}

// ============================================================
// 构建函数
// ============================================================

/**
 * 从 FormPageIR 构建 IR 依赖图。
 *
 * 实现方式：
 * 1. 收集所有节点（fields、databaseFields、expressions、listConfig、workflow）
 * 2. 遍历每个节点，在节点内容中搜索对其他节点 ID 的引用
 * 3. 构建正向边 → 转置为反向边
 *
 * 如果 IR 中存在无 ID 的节点，抛出明确的错误，不静默跳过。
 */
export function buildDependencyGraph(ir: FormPageIR): IRDependencyGraph {
  const nodes = new Map<string, IRNode>();
  const forwardEdges = new Map<string, Set<string>>();

  // Step 1: 收集所有节点
  collectNodes(ir, nodes);

  // Step 2: 验证所有节点都有 ID
  const missingIds: string[] = [];
  nodes.forEach((node, id) => {
    if (!id || id.trim() === '') {
      missingIds.push(`节点 type="${node.type}" name="${node.name}" 缺少 ID`);
    }
  });
  if (missingIds.length > 0) {
    throw new Error(`buildDependencyGraph: 以下节点缺少 ID，无法构建依赖图：\n${missingIds.join('\n')}`);
  }

  // Step 3: 构建正向边
  const irJson = JSON.stringify(ir);
  nodes.forEach(node => {
    const refs = new Set<string>();
    // 检查 JSON 中是否包含其他节点 ID 的引用
    nodes.forEach(targetNode => {
      if (node.id === targetNode.id) return;
      // 在 IR JSON 中搜索目标节点 ID 的出现
      if (irJson.includes(targetNode.id)) {
        // 检查引用是否发生在当前节点的上下文中
        //（简化实现：在整个 IR 中搜索，实际应由 AST 解析器精确匹配）
        // 这里用简单的启发式：如果目标 ID 出现在引用字段中
        refs.add(targetNode.id);
      }
    });
    if (refs.size > 0) {
      forwardEdges.set(node.id, refs);
    }
  });

  // Step 4: 转置为反向边
  const reverseEdges = new Map<string, Set<string>>();
  forwardEdges.forEach((targets, sourceId) => {
    targets.forEach(targetId => {
      if (!reverseEdges.has(targetId)) {
        reverseEdges.set(targetId, new Set());
      }
      reverseEdges.get(targetId)!.add(sourceId);
    });
  });

  return { nodes, forwardEdges, reverseEdges };
}

// ============================================================
// 内部工具
// ============================================================

/** 收集 FormPageIR 中所有可识别的节点 */
function collectNodes(ir: FormPageIR, nodes: Map<string, IRNode>): void {
  // fields
  if (ir.fields) {
    for (const f of ir.fields) {
      const id = f.id || '';
      nodes.set(id, { id, type: 'Field', name: f.label || '' });
    }
  }

  // databaseFields → DataSource
  if (ir.databaseFields) {
    for (const d of ir.databaseFields) {
      const id = d.name || '';
      nodes.set(id, { id, type: 'DataSource', name: d.name || '' });
    }
  }

  // expressions
  if (ir.expressions) {
    for (const e of ir.expressions) {
      const id = e.id || '';
      nodes.set(id, { id, type: 'Expression', name: e.name || '' });
    }
  }

  // listConfig
  if (ir.listConfig) {
    const id = `${ir.id}_list`;
    nodes.set(id, { id, type: 'Component', name: `${ir.name}_list` });
    if (ir.listConfig.columns) {
      for (const c of ir.listConfig.columns) {
        const colId = c.field || '';
        nodes.set(colId, { id: colId, type: 'Field', name: c.label || colId });
      }
    }
  }

  // workflow templates
  if (ir.workflow?.templateList) {
    for (const t of ir.workflow.templateList) {
      const id = t.id || '';
      nodes.set(id, { id, type: 'WorkflowStep', name: t.name || '' });
    }
  }
}

/**
 * IREditPatch — 分治编辑（Surgical Edit）类型定义与引擎
 *
 * Agent 输出 JSON Patch 格式的编辑指令，applyPatch 逐条应用。
 * 支持 replace / add / remove 三种操作，每条记录 oldValue 用于回滚。
 * 纯原生 JavaScript 实现，零外部依赖。
 *
 * @module ir/edit-patch
 * @version 1.0.0 — P0 审判令二
 */

import type { AgentSlice } from '../ai/agents/agent-scope';
import type { FormPageIR } from './types';

// ============================================================
// 类型定义
// ============================================================

export interface IREditOperation {
  op: 'replace' | 'add' | 'remove';
  path: string;
  value?: unknown;
  oldValue?: unknown;
  reason: string;
}

export interface IREditPatch {
  targetNodeIds: string[];
  operations: IREditOperation[];
  explanation: string;
}

export interface ApplyPatchResult {
  result: FormPageIR;
  applied: IREditOperation[];
  failed: FailedOperation[];
}

export interface FailedOperation {
  operation: IREditOperation;
  failureReason: string;
}

// ============================================================
// 引擎函数
// ============================================================

export function applyPatch(ir: FormPageIR, patch: IREditPatch, slice: AgentSlice): ApplyPatchResult {
  const result = deepClone(ir);
  const applied: IREditOperation[] = [];
  const failed: FailedOperation[] = [];

  for (const op of patch.operations) {
    try {
      const nodeId = extractNodeId(op.path);
      if (nodeId && !slice.writableNodeIds.includes(nodeId)) {
        failed.push({
          operation: { ...op },
          failureReason: `节点 "${nodeId}" 不在 Agent 的可写范围内`,
        });
        continue;
      }

      const segments = parsePath(op.path);

      switch (op.op) {
        case 'replace': {
          const oldVal = getByPath(result, segments);
          if (oldVal === undefined || oldVal === null) {
            failed.push({ operation: { ...op }, failureReason: `路径 "${op.path}" 不存在` });
            continue;
          }
          const savedOld = deepClone(oldVal);
          setByPath(result, segments, deepClone(op.value));
          applied.push({ ...op, oldValue: savedOld });
          break;
        }
        case 'add': {
          setByPath(result, segments, deepClone(op.value));
          applied.push({ ...op });
          break;
        }
        case 'remove': {
          const oldVal = getByPath(result, segments);
          if (oldVal === undefined || oldVal === null) {
            failed.push({ operation: { ...op }, failureReason: `路径 "${op.path}" 不存在，无法删除` });
            continue;
          }
          deleteByPath(result, segments);
          applied.push({ ...op, oldValue: deepClone(oldVal) });
          break;
        }
        default:
          failed.push({ operation: { ...op }, failureReason: `不支持的操作类型: "${op.op}"` });
      }
    } catch (e) {
      failed.push({ operation: { ...op }, failureReason: (e as Error).message });
    }
  }

  return { result, applied, failed };
}

export function rollbackPatch(ir: FormPageIR, appliedOperations: IREditOperation[]): FormPageIR {
  const result = deepClone(ir);
  const reversed = [...appliedOperations].reverse();

  for (const op of reversed) {
    const segments = parsePath(op.path);
    if (op.op === 'add') {
      deleteByPath(result, segments);
    } else if (op.oldValue !== undefined && op.oldValue !== null) {
      setByPath(result, segments, deepClone(op.oldValue));
    }
  }

  return result;
}

// ============================================================
// 原生路径工具（零依赖）
// ============================================================

function parsePath(path: string): string[] {
  return path
    .replace(/^\$\./, '')
    .split(/\.|\[|\]\.?/)
    .filter(Boolean)
    .map(s => s.replace(/^"|"$/g, ''));
}

function resolveSegment(current: unknown, seg: string): unknown {
  if (current === null || current === undefined) return undefined;
  // 如果当前值是数组，按 id 字段查找
  if (Array.isArray(current)) {
    return (current as Array<Record<string, unknown>>).find(item => item.id === seg);
  }
  return (current as Record<string, unknown>)[seg];
}

function getByPath(obj: unknown, segments: string[]): unknown {
  let current = obj;
  for (const seg of segments) {
    current = resolveSegment(current, seg);
    if (current === undefined) return undefined;
  }
  return current;
}

function setByPath(obj: unknown, segments: string[], value: unknown): void {
  let current: Record<string, unknown> = obj as Record<string, unknown>;
  for (let i = 0; i < segments.length - 1; i++) {
    const next = resolveSegment(current, segments[i]);
    if (next === undefined) {
      // 如果当前是数组且找不到目标 id，追加新元素
      if (Array.isArray(current)) {
        const newItem: Record<string, unknown> = { id: segments[i] };
        (current as Array<Record<string, unknown>>).push(newItem);
        current = newItem;
      } else {
        current[segments[i]] = {} as Record<string, unknown>;
        current = current[segments[i]] as Record<string, unknown>;
      }
    } else if (typeof next !== 'object' || next === null) {
      current[segments[i]] = {} as Record<string, unknown>;
      current = current[segments[i]] as Record<string, unknown>;
    } else {
      current = next as Record<string, unknown>;
    }
  }
  current[segments[segments.length - 1]] = value;
}

function deleteByPath(obj: unknown, segments: string[]): void {
  let current = obj;

  for (let i = 0; i < segments.length - 1; i++) {
    current = resolveSegment(current, segments[i]);
    if (current === undefined) return;
  }

  const lastKey = segments[segments.length - 1];
  if (Array.isArray(current)) {
    const idx = (current as Array<Record<string, unknown>>).findIndex(item => item.id === lastKey);
    if (idx >= 0) (current as Array<Record<string, unknown>>).splice(idx, 1);
  } else {
    delete (current as Record<string, unknown>)[lastKey];
  }
}

function deepClone<T>(obj: T): T {
  return JSON.parse(JSON.stringify(obj)) as T;
}

function extractNodeId(path: string): string | null {
  const match = path.match(/\[([^\]]+)\]/);
  return match ? match[1] : null;
}

/**
 * 表达式分类器
 * 输入：嵌入在 JSON 中的箭头函数字符串
 * 输出：分级结果 + AI 业务意图探针
 */

export interface ClassificationResult {
  level: 'empty' | 'simple' | 'medium' | 'complex';
  params: string[];
  body: string;
  isAsync: boolean;
  /** AI 业务意图探针 — 当前为关键词探针，未来接入大模型 */
  intentHints: string[];
}

export function classifyExpression(code: string): ClassificationResult {
  const trimmed = code.trim();

  // 提取参数
  const paramMatch = trimmed.match(/^\(?\s*\{([^}]*)\}\s*\)?\s*=>/);
  const params = paramMatch
    ? paramMatch[1]
        .split(',')
        .map(p => p.trim())
        .filter(Boolean)
    : [];

  // 提取函数体
  const bodyMatch = trimmed.match(/=>\s*\{([\s\S]*)\}$/);
  const body = bodyMatch ? bodyMatch[1].trim() : '';

  // 空函数
  if (!body || /^\s*$/.test(body)) {
    return { level: 'empty', params, body, isAsync: false, intentHints: [] };
  }

  const isAsync = /async\s/.test(trimmed) || /Promise|new Promise|resolve|reject/.test(body);

  // 复杂
  if (/for\s*\(|\.forEach\(|\.map\(|\.filter\(|while\s*\(/.test(body)) {
    return { level: 'complex', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }
  if (/Promise/.test(body) && /if\s*\(/.test(body)) {
    return { level: 'complex', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }
  if (/eval\s*\(|new Function/.test(body)) {
    return { level: 'complex', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }

  // 中等
  if (/Promise|new Promise|resolve|reject/.test(body)) {
    return { level: 'medium', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }
  if (/if\s*\(|if\s*\{/.test(body)) {
    return { level: 'medium', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }
  if (/await\s/.test(body)) {
    return { level: 'medium', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }
  if (/\.get\(|\.post\(|\.put\(|\.delete\(|fetch\s*\(/.test(body)) {
    return { level: 'medium', params, body, isAsync, intentHints: detectBusinessIntent(body) };
  }

  // 简单
  return { level: 'simple', params, body, isAsync, intentHints: detectBusinessIntent(body) };
}

/**
 * AI 业务意图探针
 * 当前：基于关键词的简单分类
 * 未来：接入大模型做语义理解
 */
function detectBusinessIntent(body: string): string[] {
  const intents: string[] = [];
  if (/\b金额|价格|amount|price|money\b/i.test(body)) intents.push('金额计算');
  if (/\b审批|approve|workflow\b/i.test(body)) intents.push('审批流程');
  if (/\b权限|permission|role|authorize\b/i.test(body)) intents.push('权限校验');
  if (/\b设备|machine|equipment\b/i.test(body)) intents.push('设备交互');
  if (/\b库存|stock|inventory\b/i.test(body)) intents.push('库存管理');
  if (/\b告警|alarm|alert|warning\b/i.test(body)) intents.push('告警处理');
  if (/\b用户|user|tenant\b/i.test(body)) intents.push('用户/租户');
  return intents;
}

/**
 * FlowIR — 工作流中间表示
 *
 * 与 FormPageIR / DashboardIR 平级，都是 IR 联合类型的成员。
 * 设计目标：平台工作流 JSON ↔ FlowIR ↔ 可执行状态机。
 *
 * @jnpf-generated v5.2.0 type=ir-flow platform=universal
 */

// ─── 工作流整体 ───

export interface FlowIR {
  type: 'workflow';
  id: string;
  name: string;
  version: string;
  nodes: FlowNode[];
  edges: FlowEdge[];
  variables: FlowVariable[];
  aiHints?: {
    domain?: string;
    scenario?: string;
    complexity?: 'simple' | 'medium' | 'complex';
    estimatedSteps?: number;
  };
}

// ─── 节点类型 ───

export type FlowNodeType = 'start' | 'end' | 'approval' | 'condition' | 'parallel' | 'subprocess' | 'notification' | 'script' | 'timer';

export interface FlowNode {
  id: string;
  type: FlowNodeType;
  name: string;
  config: FlowNodeConfig;
  position: { x: number; y: number };
}

// ─── 节点配置（判别联合）───

export type FlowNodeConfig =
  | StartNodeConfig
  | EndNodeConfig
  | ApprovalNodeConfig
  | ConditionNodeConfig
  | ParallelNodeConfig
  | SubprocessNodeConfig
  | NotificationNodeConfig
  | ScriptNodeConfig
  | TimerNodeConfig;

export interface StartNodeConfig {
  type: 'start';
  triggerType: 'manual' | 'api' | 'event' | 'schedule';
}

export interface EndNodeConfig {
  type: 'end';
  onEnd?: 'notify' | 'archive' | 'both';
}

export interface ApprovalNodeConfig {
  type: 'approval';
  approverType: 'user' | 'role' | 'department' | 'auto';
  approverIds: string[];
  assignPolicy: 'all' | 'any' | 'sequential';
  timeout?: number;
  timeoutAction?: 'auto_pass' | 'auto_reject' | 'notify';
  formFields?: string[];
  commentRequired?: boolean;
}

export interface ConditionNodeConfig {
  type: 'condition';
  conditions: Array<{
    field: string;
    operator: '==' | '!=' | '>' | '>=' | '<' | '<=' | 'contains' | 'in';
    value: unknown;
    nextNodeId: string;
  }>;
  defaultNodeId: string;
}

export interface ParallelNodeConfig {
  type: 'parallel';
  branches: string[];
  joinPolicy: 'all' | 'any';
}

export interface SubprocessNodeConfig {
  type: 'subprocess';
  subprocessId: string;
  inputMapping?: Record<string, string>;
  outputMapping?: Record<string, string>;
}

export interface NotificationNodeConfig {
  type: 'notification';
  channel: 'sms' | 'email' | 'wechat' | 'system';
  templateId: string;
  recipients: Array<{ type: 'user' | 'role' | 'field'; value: string }>;
}

export interface ScriptNodeConfig {
  type: 'script';
  scriptType: 'expression' | 'function';
  content: string;
}

export interface TimerNodeConfig {
  type: 'timer';
  delay: number;
  delayType: 'fixed' | 'business_hours';
}

// ─── 连线 ───

export interface FlowEdge {
  id: string;
  sourceNodeId: string;
  targetNodeId: string;
  label?: string;
  condition?: string;
}

// ─── 变量 ───

export interface FlowVariable {
  id: string;
  name: string;
  type: 'string' | 'number' | 'boolean' | 'date' | 'array' | 'object';
  defaultValue?: unknown;
  scope: 'global' | 'node';
  nodeId?: string;
}

// ─── 运行时快照 ───

export interface FlowSnapshot {
  flowId: string;
  currentNodeId: string;
  variables: Record<string, unknown>;
  history: Array<{
    nodeId: string;
    action: string;
    timestamp: string;
    operator?: string;
  }>;
  status: 'running' | 'paused' | 'completed' | 'rejected' | 'error';
}

// ─── 验证结果 ───

export interface FlowIRIssue {
  level: 'error' | 'warning';
  path: string;
  message: string;
  code: string;
}

// ============================================================
// 验证器
// ============================================================

/**
 * 验证 FlowIR 结构完整性
 * 规则：
 * 1. start 节点必须存在且唯一
 * 2. end 节点至少存在一个
 * 3. 每个 edge 的 source/target 必须对应存在的节点
 * 4. condition 节点的 conditions.nextNodeId 必须存在
 * 5. parallel 节点的 branches 不能为空
 * 6. 无孤立节点（除 start 外至少一条入边，除 end 外至少一条出边）
 * 7. 无自环
 */
export function validateFlowIR(ir: FlowIR): FlowIRIssue[] {
  const issues: FlowIRIssue[] = [];
  const nodeIds = new Set(ir.nodes.map(n => n.id));

  // Rule 1: start 节点唯一
  const starts = ir.nodes.filter(n => n.type === 'start');
  if (starts.length === 0) {
    issues.push({
      level: 'error',
      path: 'nodes',
      message: '缺少 start 节点',
      code: 'MISSING_START',
    });
  } else if (starts.length > 1) {
    issues.push({
      level: 'error',
      path: 'nodes',
      message: `发现 ${starts.length} 个 start 节点，只能有 1 个`,
      code: 'DUPLICATE_START',
    });
  }

  // Rule 2: end 节点至少一个
  const ends = ir.nodes.filter(n => n.type === 'end');
  if (ends.length === 0) {
    issues.push({
      level: 'warning',
      path: 'nodes',
      message: '缺少 end 节点',
      code: 'MISSING_END',
    });
  }

  // Rule 3: edge 引用有效性
  for (const edge of ir.edges) {
    if (!nodeIds.has(edge.sourceNodeId)) {
      issues.push({
        level: 'error',
        path: `edges.${edge.id}`,
        message: `sourceNodeId "${edge.sourceNodeId}" 不是有效节点`,
        code: 'INVALID_EDGE_SOURCE',
      });
    }
    if (!nodeIds.has(edge.targetNodeId)) {
      issues.push({
        level: 'error',
        path: `edges.${edge.id}`,
        message: `targetNodeId "${edge.targetNodeId}" 不是有效节点`,
        code: 'INVALID_EDGE_TARGET',
      });
    }
    // Rule 7: 无自环
    if (edge.sourceNodeId === edge.targetNodeId) {
      issues.push({
        level: 'error',
        path: `edges.${edge.id}`,
        message: `节点 "${edge.sourceNodeId}" 存在自环`,
        code: 'SELF_LOOP',
      });
    }
  }

  // Rule 4: condition 条件引用有效性
  for (const node of ir.nodes) {
    if (node.type === 'condition') {
      const config = node.config as ConditionNodeConfig;
      for (let i = 0; i < config.conditions.length; i++) {
        if (!nodeIds.has(config.conditions[i].nextNodeId)) {
          issues.push({
            level: 'error',
            path: `nodes.${node.id}.conditions[${i}]`,
            message: `nextNodeId "${config.conditions[i].nextNodeId}" 不是有效节点`,
            code: 'INVALID_CONDITION_TARGET',
          });
        }
      }
      if (config.defaultNodeId && !nodeIds.has(config.defaultNodeId)) {
        issues.push({
          level: 'error',
          path: `nodes.${node.id}.defaultNodeId`,
          message: `defaultNodeId "${config.defaultNodeId}" 不是有效节点`,
          code: 'INVALID_DEFAULT_TARGET',
        });
      }
    }

    // Rule 5: parallel branches 非空
    if (node.type === 'parallel') {
      const config = node.config as ParallelNodeConfig;
      if (config.branches.length === 0) {
        issues.push({
          level: 'error',
          path: `nodes.${node.id}.branches`,
          message: 'parallel 节点至少需要一个分支',
          code: 'EMPTY_BRANCHES',
        });
      }
      for (const branchId of config.branches) {
        if (!nodeIds.has(branchId)) {
          issues.push({
            level: 'error',
            path: `nodes.${node.id}.branches`,
            message: `分支节点 "${branchId}" 不是有效节点`,
            code: 'INVALID_BRANCH_TARGET',
          });
        }
      }
    }
  }

  // Rule 6: 孤立节点检测
  const edgeSources = new Set(ir.edges.map(e => e.sourceNodeId));
  const edgeTargets = new Set(ir.edges.map(e => e.targetNodeId));

  for (const node of ir.nodes) {
    // start 节点可以没有入边
    if (node.type === 'start') continue;
    // end 节点可以没有出边
    if (node.type === 'end') continue;

    if (!edgeTargets.has(node.id) && (node.type as string) !== 'start') {
      issues.push({
        level: 'warning',
        path: `nodes.${node.id}`,
        message: `节点 "${node.name}" 没有入边`,
        code: 'ORPHAN_NODE_NO_INPUT',
      });
    }
    if (!edgeSources.has(node.id) && (node.type as string) !== 'end') {
      issues.push({
        level: 'warning',
        path: `nodes.${node.id}`,
        message: `节点 "${node.name}" 没有出边`,
        code: 'ORPHAN_NODE_NO_OUTPUT',
      });
    }
  }

  return issues;
}

/** 检查是否存在 error 级别的问题 */
export function hasErrors(issues: FlowIRIssue[]): boolean {
  return issues.some(i => i.level === 'error');
}

/**
 * Schema 清洗器
 *
 * 职责：将 JNPF 平台原生 Schema JSON 转换为平台无关的 IR
 *
 * 处理：
 *   1. 双层 JSON 解包（JNPF 数据是 JSON 套 JSON）
 *   2. __vModel__ → model 字段映射
 *   3. __config__ → config 字段展开
 *   4. tag → JnpfKey 组件映射
 *   5. 嵌入式箭头函数 → ExpressionIR（不清洗代码本身，只标记和分类）
 *   6. DataScreen / UniApp 配置提取到 listConfig / mobileConfig
 *
 * 安全：此模块不执行任何用户代码，只对 JSON 做结构转换 + 字符串分类。
 */

import type {
  FormPageIR,
  FieldIR,
  FormConfig,
  ValidationRuleIR,
  OptionItemIR,
  ExpressionIR,
  DatabaseFieldIR,
  ListConfigIR,
  ColumnIR,
  SearchFieldIR,
  MobileConfigIR,
  WorkflowIR,
} from './types';
import { resolveComponentMapping } from './component-mapping';
import { classifyExpression } from './expression-classifier';

// ============================================================
// 主入口
// ============================================================

export function cleanSchema(rawJson: unknown): FormPageIR {
  const data = unwrapDoubleJson(rawJson);
  const config = extractFormConfig(data);
  const { fields, expressions: fieldExprs } = extractFields(data.fields || []);
  const lifecycleExprs = extractLifecycleExpressions(data.funcs);
  const expressions = [...lifecycleExprs, ...fieldExprs];
  const databaseFields = extractDatabaseFields(data.virtualFieldList || []);
  const listConfig = extractListConfig(data.columnData);
  const mobileConfig = extractMobileConfig(data.appColumnData, data.appFormData);
  const workflow = extractWorkflow(data.flowData);

  return {
    type: 'form',
    id: String(data.id || data.modelId || generateId()),
    name: String(data.fullName || data.enCode || data.name || 'unnamed'),
    config,
    fields,
    databaseFields,
    expressions,
    ...(listConfig && { listConfig }),
    ...(mobileConfig && { mobileConfig }),
    ...(workflow && { workflow }),
  };
}

// ============================================================
// 双层 JSON 解包
// ============================================================

function unwrapDoubleJson(raw: unknown): Record<string, any> {
  if (typeof raw === 'string') {
    try {
      return unwrapDoubleJson(JSON.parse(raw));
    } catch {
      return {};
    }
  }

  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    const obj = raw as Record<string, any>;

    // JNPF 的双层 JSON 模式：{ data: { formData: "{ ... }" } }
    if (obj.data && typeof obj.data === 'object') {
      const inner = obj.data as Record<string, any>;
      // formData 是一个 JSON 字符串
      if (typeof inner.formData === 'string') {
        try {
          return { ...inner, ...JSON.parse(inner.formData) };
        } catch {
          return inner;
        }
      }
      return inner;
    }

    // 单层模式：{ formData: "{ ... }" }
    if (typeof obj.formData === 'string') {
      try {
        return { ...obj, ...JSON.parse(obj.formData) };
      } catch {
        return obj;
      }
    }

    return obj;
  }

  return {};
}

// ============================================================
// 表单配置提取
// ============================================================

function extractFormConfig(data: Record<string, any>): FormConfig {
  return {
    labelPosition: data.labelPosition || 'right',
    labelWidth: data.labelWidth ?? 100,
    labelSuffix: data.labelSuffix || '',
    size: data.size || 'default',
    disabled: data.disabled ?? false,
    span: data.span ?? 24,
    gutter: data.gutter ?? 0,
    colon: data.colon ?? true,
    popupType: data.popupType || 'general',
    generalWidth: data.generalWidth || '800px',
    fullScreenWidth: data.fullScreenWidth || '80%',
    drawerWidth: data.drawerWidth || '50%',
    hasCancelBtn: data.hasCancelBtn ?? true,
    cancelButtonText: data.cancelButtonText || '取消',
    hasConfirmBtn: data.hasConfirmBtn ?? true,
    confirmButtonText: data.confirmButtonText || '确认',
    hasConfirmAndAddBtn: data.hasConfirmAndAddBtn ?? false,
    hasPrintBtn: data.hasPrintBtn ?? false,
    printButtonText: data.printButtonText || '打印',
    primaryKeyPolicy: data.primaryKeyPolicy || 'uuid',
    tablePolicy: data.tablePolicy || 'auto',
    concurrencyLock: data.concurrencyLock ?? false,
    logicalDelete: data.logicalDelete ?? false,
  };
}

// ============================================================
// 字段提取
// ============================================================

function extractFields(rawFields: any[]): { fields: FieldIR[]; expressions: ExpressionIR[] } {
  const fields: FieldIR[] = [];
  const expressions: ExpressionIR[] = [];

  for (const raw of rawFields) {
    const cfg = raw.__config__ || raw.config || {};
    const jnpfKey = cfg.jnpfKey || cfg.tag || 'JnpfInput';
    const mapping = resolveComponentMapping(jnpfKey);

    // 提取选项
    const options = extractOptions(raw.options || cfg.options || [], cfg.dataType, cfg.dictionaryType);

    // 提取校验规则
    const validation = extractValidation(cfg.regList || []);

    // 提取字段事件表达式
    const on = raw.on || {};
    for (const [trigger, code] of Object.entries(on)) {
      if (typeof code === 'string' && code.trim()) {
        const exprId = `field-${raw.__vModel__ || 'unknown'}-${trigger}`;
        const classification = classifyExpression(code);
        expressions.push({
          id: exprId,
          name: `${raw.__vModel__ || 'unknown'}.${trigger}`,
          type: 'field-event',
          params: classification.params,
          body: classification.body,
          level: classification.level,
          isAsync: classification.isAsync,
          originalCode: code,
        });
      }
    }

    fields.push({
      id: raw.__vModel__ || `field-${fields.length}`,
      model: raw.__vModel__ || '',
      label: cfg.label || raw.label || '',
      component: {
        jnpfKey,
        pc: mapping.pc,
        app: mapping.app,
        legacyApp: mapping.legacyApp,
      },
      config: {
        required: cfg.required ?? false,
        defaultValue: cfg.defaultValue ?? undefined,
        placeholder: raw.placeholder || '',
        disabled: cfg.disabled ?? false,
        readonly: cfg.readonly ?? false,
        hidden: cfg.hidden ?? false,
        span: cfg.span ?? cfg.colSpan ?? 24,
        labelWidth: cfg.labelWidth ?? null,
        maxlength: cfg.maxlength ?? null,
        showWordLimit: cfg.showWordLimit ?? false,
        clearable: cfg.clearable ?? true,
        min: cfg.min ?? null,
        max: cfg.max ?? null,
        precision: cfg.precision ?? null,
        step: cfg.step ?? null,
        multiple: cfg.multiple ?? cfg.searchMultiple ?? false,
        options,
        dictType: cfg.dictionaryType || cfg.dictType || null,
        relationData: cfg.relationData
          ? {
              url: cfg.relationData.url || null,
              labelField: cfg.relationData.labelField || null,
              valueField: cfg.relationData.valueField || null,
            }
          : null,
        style: cfg.style || {},
      },
      validation,
      events: {
        change: typeof on.change === 'string' ? `field-${raw.__vModel__}-change` : undefined,
        blur: typeof on.blur === 'string' ? `field-${raw.__vModel__}-blur` : undefined,
        focus: typeof on.focus === 'string' ? `field-${raw.__vModel__}-focus` : undefined,
        click: typeof on.click === 'string' ? `field-${raw.__vModel__}-click` : undefined,
      },
      aiHints: cfg.label
        ? {
            semantic: inferSemanticRole(raw.__vModel__, cfg.label),
            suggestedValidation: null as unknown as undefined,
            suggestedDefault: null as unknown as undefined,
          }
        : undefined,
    });
  }

  return { fields, expressions };
}

// ============================================================
// 生命周期表达式提取
// ============================================================

function extractLifecycleExpressions(funcs: Record<string, string> | undefined): ExpressionIR[] {
  if (!funcs) return [];
  const expressions: ExpressionIR[] = [];

  for (const [name, code] of Object.entries(funcs)) {
    if (typeof code !== 'string' || !code.trim()) continue;
    const classification = classifyExpression(code);
    expressions.push({
      id: `lifecycle-${name}`,
      name,
      type: 'form-lifecycle',
      params: classification.params,
      body: classification.body,
      level: classification.level,
      isAsync: classification.isAsync,
      originalCode: code,
    });
  }

  return expressions;
}

// ============================================================
// 数据库字段提取
// ============================================================

function extractDatabaseFields(virtualFieldList: any[]): DatabaseFieldIR[] {
  return virtualFieldList.map(f => ({
    id: f.field || f.name || '',
    name: f.field || f.name || '',
    type: f.type || f.dataType || 'varchar',
    length: f.length ?? null,
    nullable: f.nullable ?? true,
    defaultValue: f.defaultValue ?? null,
    description: f.description || f.comment || '',
  }));
}

// ============================================================
// 列表配置提取
// ============================================================

function extractListConfig(columnData: any): ListConfigIR | undefined {
  if (!columnData) return undefined;

  const parsed = typeof columnData === 'string' ? safeJsonParse(columnData) : columnData;
  if (!parsed) return undefined;

  const columns: ColumnIR[] = (parsed.columnList || []).map((c: any) => ({
    field: c.prop || c.field || '',
    label: c.label || '',
    width: c.width ?? null,
    fixed: c.fixed || null,
    sortable: c.sortable ?? false,
    formatter: c.formatter || undefined,
  }));

  const searchFields: SearchFieldIR[] = extractSearchFields(parsed.searchList || []);

  return {
    searchFields,
    columns,
    ruleList: parsed.ruleList || [],
  };
}

function extractSearchFields(searchList: any[]): SearchFieldIR[] {
  return searchList.map((s: any) => ({
    field: s.__vModel__ || s.field || '',
    label: s.__config__?.label || s.label || '',
    component: s.__config__?.jnpfKey || s.component || 'Input',
    options: extractOptions(s.options || s.__config__?.options || []),
  }));
}

// ============================================================
// 移动端配置提取
// ============================================================

function extractMobileConfig(appColumnData: any, appFormData: any): MobileConfigIR | undefined {
  const formData = appFormData ? (typeof appFormData === 'string' ? safeJsonParse(appFormData) : appFormData) : null;
  const colData = appColumnData ? (typeof appColumnData === 'string' ? safeJsonParse(appColumnData) : appColumnData) : null;

  if (!formData && !colData) return undefined;

  const formFields: FieldIR[] = formData?.fields ? extractFields(formData.fields).fields : [];
  const listColumns: ColumnIR[] = (colData?.columnList || []).map((c: any) => ({
    field: c.prop || c.field || '',
    label: c.label || '',
    width: c.width ?? null,
    fixed: c.fixed || null,
    sortable: c.sortable ?? false,
  }));

  return { formFields, listColumns };
}

// ============================================================
// 工作流配置提取
// ============================================================

function extractWorkflow(flowData: any): WorkflowIR | undefined {
  if (!flowData) return undefined;
  const parsed = typeof flowData === 'string' ? safeJsonParse(flowData) : flowData;
  if (!parsed) return undefined;

  return {
    flowId: parsed.flowId || '',
    flowType: parsed.flowType || '',
    templateList: parsed.templateList || [],
  };
}

// ============================================================
// 选项提取
// ============================================================

function extractOptions(rawOptions: any[], dataType?: string, dictionaryType?: string): OptionItemIR[] {
  if (dataType === 'dictionary' && dictionaryType) {
    return []; // 字典选项在运行时加载，IR 中留空
  }
  if (dataType === 'dynamic') {
    return []; // 动态选项在运行时加载
  }
  return (rawOptions || []).map((o: any) => ({
    label: o.label || o.fullName || o.name || '',
    value: o.value ?? o.id ?? o,
    disabled: o.disabled ?? false,
  }));
}

// ============================================================
// 校验规则提取
// ============================================================

function extractValidation(regList: any[]): ValidationRuleIR[] {
  return (regList || []).map((r: any) => {
    if (r.required !== undefined) {
      return {
        type: 'required',
        message: r.message || '此项必填',
        trigger: (r.trigger as 'blur' | 'change') || 'blur',
      };
    }
    if (r.pattern) {
      const patternStr = typeof r.pattern === 'string' ? r.pattern : String(r.pattern);
      return {
        type: 'pattern',
        pattern: patternStr,
        message: r.message || '格式不正确',
        trigger: (r.trigger as 'blur' | 'change') || 'blur',
      };
    }
    if (r.min !== undefined || r.max !== undefined) {
      return {
        type: 'string',
        min: r.min,
        max: r.max,
        message: r.message || '长度不符合要求',
        trigger: (r.trigger as 'blur' | 'change') || 'blur',
      };
    }
    return {
      type: 'pattern',
      pattern: r.pattern || '',
      message: r.message || '',
      trigger: (r.trigger as 'blur' | 'change') || 'blur',
    };
  });
}

// ============================================================
// 语义角色推断（AI 探针）
// ============================================================

function inferSemanticRole(model: string, label: string): string {
  const combined = `${model} ${label}`.toLowerCase();
  if (/email|邮箱|邮件/.test(combined)) return 'email';
  if (/phone|mobile|tel|电话|手机/.test(combined)) return 'phone';
  if (/price|amount|money|金额|价格|费用/.test(combined)) return 'currency';
  if (/date|time|时间|日期/.test(combined)) return 'datetime';
  if (/url|link|链接|地址/.test(combined)) return 'url';
  if (/name|姓名|名称|title/.test(combined)) return 'name';
  if (/id|编号|序号|code/.test(combined)) return 'identifier';
  if (/desc|remark|note|备注|描述|说明/.test(combined)) return 'description';
  if (/status|state|状态/.test(combined)) return 'status';
  if (/image|img|photo|图片|照片/.test(combined)) return 'image';
  if (/file|attachment|附件|文件/.test(combined)) return 'file';
  return 'text';
}

// ============================================================
// 工具函数
// ============================================================

function safeJsonParse(str: string): any {
  try {
    return JSON.parse(str);
  } catch {
    return null;
  }
}

function generateId(): string {
  return `ir-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

/**
 * IR 验证器
 *
 * 职责：验证 IR 的结构完整性（必填字段、引用完整性）
 * 不做：语义正确性验证（由编译器负责）
 */

import type { FormPageIR } from './types';

export interface ValidationIssue {
  level: 'error' | 'warn' | 'ai-quality';
  path: string;
  message: string;
  suggestion?: string;
}

export function validateIR(ir: FormPageIR): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  // 1. 必填字段
  if (!ir.id) issues.push({ level: 'error', path: 'id', message: '缺少 id' });
  if (!ir.name) issues.push({ level: 'warn', path: 'name', message: '缺少 name' });
  if (!ir.fields?.length) {
    issues.push({ level: 'error', path: 'fields', message: '字段列表为空' });
  }

  // 2. 字段完整性
  for (let i = 0; i < (ir.fields?.length ?? 0); i++) {
    const field = ir.fields[i];
    const prefix = `fields[${i}]`;
    if (!field.model) issues.push({ level: 'error', path: `${prefix}.model`, message: '缺少 model' });
    if (!field.label) issues.push({ level: 'warn', path: `${prefix}.label`, message: '缺少 label' });
    if (!field.component?.jnpfKey) issues.push({ level: 'error', path: `${prefix}.component.jnpfKey`, message: '缺少组件类型' });
    if (!field.component?.pc) issues.push({ level: 'warn', path: `${prefix}.component.pc`, message: '缺少 PC 端组件映射' });
    if (!field.component?.app) issues.push({ level: 'warn', path: `${prefix}.component.app`, message: '缺少 App 端组件映射' });
  }

  // 3. 表达式引用完整性
  const exprIds = new Set(ir.expressions?.map(e => e.id) ?? []);
  for (let i = 0; i < (ir.fields?.length ?? 0); i++) {
    const field = ir.fields[i];
    if (!field.events) continue;
    for (const [event, exprId] of Object.entries(field.events)) {
      if (exprId && !exprIds.has(exprId)) {
        issues.push({
          level: 'error',
          path: `fields[${i}].events.${event}`,
          message: `引用了不存在的表达式: ${exprId}`,
        });
      }
    }
  }

  // 4. 表达式级别统计
  const complexCount = ir.expressions?.filter(e => e.level === 'complex').length ?? 0;
  if (complexCount > 0) {
    issues.push({
      level: 'warn',
      path: 'expressions',
      message: `有 ${complexCount} 个复杂表达式需人工迁移`,
    });
  }

  // 5. AI 质量探针（当前为空壳，等知识图谱就位后填充）
  issues.push(...validateAIQuality(ir));

  return issues;
}

function validateAIQuality(_ir: FormPageIR): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  // 占位：等知识图谱和领域规则就位后启用
  // 示例：
  // if (ir.aiHints?.domain === 'mes' && !ir.fields.some(f => f.model === 'equipmentId')) {
  //   issues.push({
  //     level: 'ai-quality', path: 'fields',
  //     message: 'MES 领域通常需要设备相关字段',
  //     suggestion: '考虑添加 equipmentId, equipmentName'
  //   });
  // }
  return issues;
}

export function hasErrors(issues: ValidationIssue[]): boolean {
  return issues.some(i => i.level === 'error');
}

import type { MenuSetting } from '/#/config';

import { computed, unref, ref } from 'vue';

import { useAppStore } from '/@/store/modules/app';

import { SIDE_BAR_MINI_WIDTH, SIDE_BAR_SHOW_TIT_MINI_WIDTH } from '/@/enums/appEnum';
import { MenuModeEnum, MenuTypeEnum, TriggerEnum } from '/@/enums/menuEnum';
import { useFullContent } from '/@/hooks/web/useFullContent';

const mixSideHasChildren = ref(false);

export function useMenuSetting() {
  const { getFullContent: fullContent } = useFullContent();
  const appStore = useAppStore();

  const getShowSidebar = computed(() => {
    return unref(getSplit) || (unref(getShowMenu) && unref(getMenuMode) !== MenuModeEnum.HORIZONTAL && !unref(fullContent));
  });

  const getCollapsed = computed(() => appStore.getMenuSetting.collapsed);

  const getMenuType = computed(() => appStore.getMenuSetting.type);

  const getMenuMode = computed(() => appStore.getMenuSetting.mode);

  const getMenuFixed = computed(() => appStore.getMenuSetting.fixed);

  const getShowMenu = computed(() => appStore.getMenuSetting.show);

  const getMenuHidden = computed(() => appStore.getMenuSetting.hidden);

  const getMenuWidth = computed(() => appStore.getMenuSetting.menuWidth);

  const getTrigger = computed(() => appStore.getMenuSetting.trigger);

  const getMenuTheme = computed(() => appStore.getMenuSetting.theme);

  const getSplit = computed(() => appStore.getMenuSetting.split);

  const getMenuBgColor = computed(() => appStore.getMenuSetting.bgColor);

  const getMixSideTrigger = computed(() => appStore.getMenuSetting.mixSideTrigger);

  const getCanDrag = computed(() => appStore.getMenuSetting.canDrag);

  const getAccordion = computed(() => appStore.getMenuSetting.accordion);

  const getMixSideFixed = computed(() => appStore.getMenuSetting.mixSideFixed);

  const getTopMenuAlign = computed(() => appStore.getMenuSetting.topMenuAlign);

  const getCloseMixSidebarOnChange = computed(() => appStore.getMenuSetting.closeMixSidebarOnChange);

  const getIsSidebarType = computed(() => unref(getMenuType) === MenuTypeEnum.SIDEBAR);

  const getIsTopMenu = computed(() => unref(getMenuType) === MenuTypeEnum.TOP_MENU);

  const getCollapsedShowTitle = computed(() => appStore.getMenuSetting.collapsedShowTitle);

  const getShowTopMenu = computed(() => {
    return unref(getMenuMode) === MenuModeEnum.HORIZONTAL || unref(getSplit);
  });

  const getShowHeaderTrigger = computed(() => {
    if (unref(getMenuType) === MenuTypeEnum.TOP_MENU || !unref(getShowMenu) || unref(getMenuHidden)) {
      return false;
    }

    return unref(getTrigger) === TriggerEnum.HEADER;
  });

  const getIsHorizontal = computed(() => {
    return unref(getMenuMode) === MenuModeEnum.HORIZONTAL;
  });

  const getIsMixSidebar = computed(() => {
    return unref(getMenuType) === MenuTypeEnum.MIX_SIDEBAR;
  });

  const getIsMixMode = computed(() => {
    return unref(getMenuMode) === MenuModeEnum.INLINE && unref(getMenuType) === MenuTypeEnum.MIX;
  });

  const getRealWidth = computed(() => {
    if (unref(getIsMixSidebar)) {
      return unref(getCollapsed) && !unref(getMixSideFixed) ? unref(getMiniWidthNumber) : unref(getMenuWidth);
    }
    return unref(getCollapsed) ? unref(getMiniWidthNumber) : unref(getMenuWidth);
  });

  const getMiniWidthNumber = computed(() => {
    const { collapsedShowTitle, siderHidden } = appStore.getMenuSetting;
    return siderHidden ? 0 : collapsedShowTitle ? SIDE_BAR_SHOW_TIT_MINI_WIDTH : SIDE_BAR_MINI_WIDTH;
  });

  const getCalcContentWidth = computed(() => {
    const width =
      unref(getIsTopMenu) || !unref(getShowMenu) || (unref(getSplit) && unref(getMenuHidden))
        ? 0
        : unref(getIsMixSidebar)
        ? (unref(getCollapsed) ? SIDE_BAR_MINI_WIDTH : SIDE_BAR_SHOW_TIT_MINI_WIDTH) +
          (unref(getMixSideFixed) && unref(mixSideHasChildren) ? unref(getRealWidth) : 0)
        : unref(getRealWidth);

    return `calc(100% - ${unref(width)}px)`;
  });

  // Set menu configuration
  function setMenuSetting(menuSetting: Partial<MenuSetting>): void {
    appStore.setProjectConfig({ menuSetting });
  }

  function toggleCollapsed() {
    setMenuSetting({
      collapsed: !unref(getCollapsed),
    });
  }
  return {
    setMenuSetting,

    toggleCollapsed,

    getMenuFixed,
    getRealWidth,
    getMenuType,
    getMenuMode,
    getShowMenu,
    getCollapsed,
    getMiniWidthNumber,
    getCalcContentWidth,
    getMenuWidth,
    getTrigger,
    getSplit,
    getMenuTheme,
    getCanDrag,
    getCollapsedShowTitle,
    getIsHorizontal,
    getIsSidebarType,
    getAccordion,
    getShowTopMenu,
    getShowHeaderTrigger,
    getTopMenuAlign,
    getMenuHidden,
    getIsTopMenu,
    getMenuBgColor,
    getShowSidebar,
    getIsMixMode,
    getIsMixSidebar,
    getCloseMixSidebarOnChange,
    getMixSideTrigger,
    getMixSideFixed,
    mixSideHasChildren,
  };
}

import { ComputedRef, isRef, nextTick, Ref, ref, unref, watch } from 'vue';
import { onMountedOrActivated } from '/@/hooks/core/onMountedOrActivated';
import { useWindowSizeFn } from '/@/hooks/event/useWindowSizeFn';
import { useLayoutHeight } from '/@/layouts/default/content/useContentViewHeight';
import { getViewportOffset } from '/@/utils/domUtils';
import { isNumber, isString } from '/@/utils/is';

export interface CompensationHeight {
  // 使用 layout Footer 高度作为判断补偿高度的条件
  useLayoutFooter: boolean;
  // refs HTMLElement
  elements?: Ref[];
}

type Upward = number | string | null | undefined;

/**
 * 动态计算内容高度，根据锚点dom最下坐标到屏幕最下坐标，根据传入dom的高度、padding、margin等值进行动态计算
 * 最终获取合适的内容高度
 *
 * @param flag 用于开启计算的响应式标识
 * @param anchorRef 锚点组件 Ref<ElRef | ComponentRef>
 * @param subtractHeightRefs 待减去高度的组件列表 Ref<ElRef | ComponentRef>
 * @param substractSpaceRefs 待减去空闲空间(margins/paddings)的组件列表 Ref<ElRef | ComponentRef>
 * @param offsetHeightRef 计算偏移的响应式高度，计算高度时将直接减去此值
 * @param upwardSpace 向上递归减去空闲空间的 层级 或 直到指定class为止 数值为2代表向上递归两次|数值为ant-layout表示向上递归直到碰见.ant-layout为止
 * @returns 响应式高度
 */
export function useContentHeight(
  flag: ComputedRef<Boolean>,
  anchorRef: Ref,
  subtractHeightRefs: Ref[],
  substractSpaceRefs: Ref[],
  upwardSpace: Ref<Upward> | ComputedRef<Upward> | Upward = 0,
  offsetHeightRef: Ref<number> = ref(0),
) {
  const contentHeight: Ref<Nullable<number>> = ref(null);
  const { footerHeightRef: layoutFooterHeightRef } = useLayoutHeight();
  let compensationHeight: CompensationHeight = {
    useLayoutFooter: true,
  };

  const setCompensation = (params: CompensationHeight) => {
    compensationHeight = params;
  };

  function redoHeight() {
    nextTick(() => {
      calcContentHeight();
    });
  }

  function calcSubtractSpace(element: Element | null | undefined, direction: 'all' | 'top' | 'bottom' = 'all'): number {
    function numberPx(px: string) {
      return Number(px.replace(/[^\d]/g, ''));
    }
    let subtractHeight = 0;
    const ZERO_PX = '0px';
    if (element) {
      const cssStyle = getComputedStyle(element);
      const marginTop = numberPx(cssStyle?.marginTop ?? ZERO_PX);
      const marginBottom = numberPx(cssStyle?.marginBottom ?? ZERO_PX);
      const paddingTop = numberPx(cssStyle?.paddingTop ?? ZERO_PX);
      const paddingBottom = numberPx(cssStyle?.paddingBottom ?? ZERO_PX);
      if (direction === 'all') {
        subtractHeight += marginTop;
        subtractHeight += marginBottom;
        subtractHeight += paddingTop;
        subtractHeight += paddingBottom;
      } else if (direction === 'top') {
        subtractHeight += marginTop;
        subtractHeight += paddingTop;
      } else {
        subtractHeight += marginBottom;
        subtractHeight += paddingBottom;
      }
    }
    return subtractHeight;
  }

  function getEl(element: any): Nullable<HTMLDivElement> {
    if (element == null) {
      return null;
    }
    return (element instanceof HTMLDivElement ? element : element.$el) as HTMLDivElement;
  }

  async function calcContentHeight() {
    if (!flag.value) {
      return;
    }
    // Add a delay to get the correct height
    await nextTick();

    const anchorEl = getEl(unref(anchorRef));
    if (!anchorEl) {
      return;
    }
    const { bottomIncludeBody } = getViewportOffset(anchorEl);

    // substract elements height
    let substractHeight = 0;
    subtractHeightRefs.forEach(item => {
      substractHeight += getEl(unref(item))?.offsetHeight ?? 0;
    });

    // subtract margins / paddings
    let substractSpaceHeight = calcSubtractSpace(anchorEl) ?? 0;
    substractSpaceRefs.forEach(item => {
      substractSpaceHeight += calcSubtractSpace(getEl(unref(item)));
    });

    // upwardSpace
    let upwardSpaceHeight = 0;
    function upward(element: Element | null, upwardLvlOrClass: number | string | null | undefined) {
      if (element && upwardLvlOrClass) {
        const parent = element.parentElement;
        if (parent) {
          if (isString(upwardLvlOrClass)) {
            if (!parent.classList.contains(upwardLvlOrClass)) {
              upwardSpaceHeight += calcSubtractSpace(parent, 'bottom');
              upward(parent, upwardLvlOrClass);
            } else {
              upwardSpaceHeight += calcSubtractSpace(parent, 'bottom');
            }
          } else if (isNumber(upwardLvlOrClass)) {
            if (upwardLvlOrClass > 0) {
              upwardSpaceHeight += calcSubtractSpace(parent, 'bottom');
              upward(parent, --upwardLvlOrClass);
            }
          }
        }
      }
    }
    if (isRef(upwardSpace)) {
      upward(anchorEl, unref(upwardSpace));
    } else {
      upward(anchorEl, upwardSpace);
    }

    let height = bottomIncludeBody - unref(layoutFooterHeightRef) - unref(offsetHeightRef) - substractHeight - substractSpaceHeight - upwardSpaceHeight;

    // compensation height
    const calcCompensationHeight = () => {
      compensationHeight.elements?.forEach(item => {
        height += getEl(unref(item))?.offsetHeight ?? 0;
      });
    };
    if (compensationHeight.useLayoutFooter && unref(layoutFooterHeightRef) > 0) {
      calcCompensationHeight();
    } else {
      calcCompensationHeight();
    }

    contentHeight.value = height;
  }

  onMountedOrActivated(() => {
    nextTick(() => {
      calcContentHeight();
    });
  });
  useWindowSizeFn(
    () => {
      calcContentHeight();
    },
    50,
    { immediate: true },
  );
  watch(
    () => [layoutFooterHeightRef.value],
    () => {
      calcContentHeight();
    },
    {
      flush: 'post',
      immediate: true,
    },
  );

  return { redoHeight, setCompensation, contentHeight };
}

import type { EChartsOption } from 'echarts';
import type { Ref } from 'vue';
import { useTimeoutFn } from '/@/hooks/core/useTimeout';
import { tryOnUnmounted } from '@vueuse/core';
import { unref, nextTick, watch, computed, ref } from 'vue';
import { useDebounceFn } from '@vueuse/core';
import { useEventListener } from '/@/hooks/event/useEventListener';
import { useBreakpoint } from '/@/hooks/event/useBreakpoint';
import * as echarts from 'echarts';
import { useRootSetting } from '/@/hooks/setting/useRootSetting';
import { useMenuSetting } from '/@/hooks/setting/useMenuSetting';

export function useECharts(elRef: Ref<HTMLDivElement>, theme: 'light' | 'dark' | 'default' = 'default') {
  const { getDarkMode: getSysDarkMode } = useRootSetting();
  const { getCollapsed } = useMenuSetting();

  const getDarkMode = computed(() => {
    return theme === 'default' ? getSysDarkMode.value : theme;
  });
  let chartInstance: echarts.ECharts | null = null;
  let resizeFn: Fn = resize;
  const cacheOptions = ref({}) as Ref<EChartsOption>;
  let removeResizeFn: Fn = () => {};

  resizeFn = useDebounceFn(resize, 200);

  const getOptions = computed(() => {
    if (getDarkMode.value !== 'dark') {
      return cacheOptions.value as EChartsOption;
    }
    return {
      backgroundColor: 'transparent',
      ...cacheOptions.value,
    } as EChartsOption;
  });

  function initCharts(t = theme) {
    const el = unref(elRef);
    if (!el || !unref(el)) {
      return;
    }

    chartInstance = echarts.init(el, t);
    const { removeEvent } = useEventListener({
      el: window,
      name: 'resize',
      listener: resizeFn,
    });
    removeResizeFn = removeEvent;
    const { widthRef, screenEnum } = useBreakpoint();
    if (unref(widthRef) <= screenEnum.MD || el.offsetHeight === 0) {
      useTimeoutFn(() => {
        resizeFn();
      }, 30);
    }
  }

  function setOptions(options: EChartsOption, clear = true) {
    cacheOptions.value = options;
    return new Promise(resolve => {
      if (unref(elRef)?.offsetHeight === 0) {
        useTimeoutFn(() => {
          setOptions(unref(getOptions));
          resolve(null);
        }, 30);
      }
      nextTick(() => {
        useTimeoutFn(() => {
          if (!chartInstance) {
            initCharts(getDarkMode.value as 'default');

            if (!chartInstance) return;
          }
          clear && chartInstance?.clear();

          chartInstance?.setOption(unref(getOptions));
          resolve(null);
        }, 30);
      });
    });
  }

  function resize() {
    chartInstance?.resize({
      animation: {
        duration: 300,
        easing: 'quadraticIn',
      },
    });
  }

  watch(
    () => getDarkMode.value,
    theme => {
      if (chartInstance) {
        chartInstance.dispose();
        initCharts(theme as 'default');
        setOptions(cacheOptions.value);
      }
    },
  );

  watch(getCollapsed, _ => {
    useTimeoutFn(() => {
      resizeFn();
    }, 300);
  });

  tryOnUnmounted(() => {
    if (!chartInstance) return;
    removeResizeFn();
    chartInstance.dispose();
    chartInstance = null;
  });

  function getInstance(): echarts.ECharts | null {
    if (!chartInstance) {
      initCharts(getDarkMode.value as 'default');
    }
    return chartInstance;
  }

  return {
    setOptions,
    resize,
    echarts,
    getInstance,
  };
}

/**
 * useLazyComponent — 按需异步加载组件的通用封装
 *
 * ## 解决的问题
 * 将弹窗/设计器等重型组件从入口 bundle 中分离，
 * 仅在真正需要渲染时才加载，显著减少首屏下载/解析/执行时间。
 *
 * ## 三层防护机制
 * 1. **预加载触发** — expose `prefetch()` to start loading on button hover
 * 2. **加载状态守卫** — expose `isLoaded` ref so UI can disable buttons until ready
 * 3. **结构化错误日志** — module/page/line 精确定位，超时控制，优雅降级
 *
 * ## 用法
 * ```typescript
 * // ❌ 之前：静态导入 → 打入主 bundle
 * import Form from './Form.vue';
 *
 * // ✅ 之后：按需加载 → 独立 chunk，hover 预加载，状态可见
 * const { component: Form, isLoaded, prefetch } = useLazyComponent(
 *   () => import('./Form.vue'),
 *   'onlineDev/webDesign'
 * );
 * // 模板中使用: <Form @register="registerForm" />
 * // 按钮上绑定: @mouseenter="prefetch" :disabled="!isLoaded"
 * ```
 */

import { defineAsyncComponent, defineComponent, Component, h, ref, Ref } from 'vue';
import { Spin } from 'ant-design-vue';

/** 开发态 Vite 首次编译重型 chunk 较慢；生产保持快速失败 */
const DEFAULT_LAZY_TIMEOUT = import.meta.env.DEV ? 120_000 : 10_000;

// ── 轻量级加载占位 ──
const DefaultLoadingComponent = {
  setup() {
    return () =>
      h(
        'div',
        {
          class: 'lazy-component-loading',
          style: 'display:flex;align-items:center;justify-content:center;padding:60px 0;',
        },
        [h(Spin, { size: 'large', tip: '组件加载中...' })],
      );
  },
};

// ── 错误占位 + 结构化日志 ──
function createErrorComponent(moduleName: string, componentPath: string) {
  return {
    setup() {
      return () =>
        h(
          'div',
          {
            class: 'lazy-component-error',
            style: 'display:flex;flex-direction:column;align-items:center;justify-content:center;padding:60px 0;color:#ff4d4f;',
          },
          [
            h('div', { style: 'font-size:16px;font-weight:600;margin-bottom:8px;' }, '组件加载失败'),
            h('div', { style: 'font-size:13px;color:#999;' }, `模块: ${moduleName} | 组件: ${componentPath}`),
            h('div', { style: 'font-size:12px;color:#bbb;margin-top:4px;' }, '请检查网络连接后刷新页面重试'),
          ],
        );
    },
  };
}

// ── 选项 ──
interface LazyOptions {
  /** 模块/页面名称，用于错误日志定位 */
  moduleName: string;
  /** 自定义加载中组件 */
  loadingComponent?: Component;
  /** 加载超时时间（ms），超时后触发 errorComponent；开发态默认 120s，生产 10s */
  timeout?: number;
  /** 是否延迟加载（ms），默认 0 表示立即开始加载 */
  delay?: number;
}

interface LazyComponentResult {
  /** 异步组件，直接用于模板 */
  component: Component;
  /** 是否已加载完成，可用于控制按钮 disabled 状态 */
  isLoaded: Ref<boolean>;
  /** 手动触发预加载（如绑定到按钮的 @mouseenter），返回 Promise 以便调用方 await */
  prefetch: () => Promise<void>;
  /** 同 prefetch，语义更明确（用于需要等待加载完成的场景，如 useLazyModal） */
  load: () => Promise<void>;
}

export type { LazyComponentResult };

export function useLazyComponent(loader: () => Promise<Record<string, any>>, moduleOrOptions: string | LazyOptions): LazyComponentResult {
  const opts: LazyOptions = typeof moduleOrOptions === 'string' ? { moduleName: moduleOrOptions } : moduleOrOptions;

  const { moduleName, loadingComponent, timeout = DEFAULT_LAZY_TIMEOUT, delay = 0 } = opts;

  // 从 loader 的 toString 中提取文件路径用于错误定位
  const componentPath = extractPath(loader);

  // 加载状态跟踪
  const isLoaded = ref(false);
  const isLoading = ref(false);
  const loadPromise = ref<Promise<Record<string, any>> | null>(null);
  /** 仅 prefetch / openModal / load 时才挂载异步组件，避免进页并行拉取多个重型 chunk */
  const shouldMount = ref(false);

  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  function ensureMount() {
    shouldMount.value = true;
  }

  /** 开始加载（幂等 — 多次调用只触发一次加载） */
  function triggerLoad(): Promise<Record<string, any>> {
    ensureMount();
    if (isLoaded.value) return Promise.resolve({} as Record<string, any>);
    if (loadPromise.value) return loadPromise.value;

    isLoading.value = true;

    const promise = new Promise<Record<string, any>>((resolve, reject) => {
      // 超时控制
      timeoutId = setTimeout(() => {
        reject(new Error(`[LazyComponent] 加载超时 (${timeout}ms) | Module: ${moduleName} | Path: ${componentPath}`));
      }, timeout) as unknown as ReturnType<typeof setTimeout>;

      // 延迟加载
      const doLoad = () => {
        loader()
          .then(mod => {
            if (timeoutId) clearTimeout(timeoutId);
            isLoaded.value = true;
            isLoading.value = false;
            resolve(mod);
          })
          .catch(err => {
            if (timeoutId) clearTimeout(timeoutId);
            isLoading.value = false;
            loadPromise.value = null; // 失败后允许重试
            console.error(
              `[LazyComponent] 加载失败 | Module: ${moduleName} | Path: ${componentPath}`,
              '\n  错误详情:',
              err,
              '\n  可能原因: 网络异常 / chunk 404 / 磁盘空间不足',
            );
            reject(err);
          });
      };

      if (delay > 0) {
        setTimeout(doLoad, delay);
      } else {
        doLoad();
      }
    });

    loadPromise.value = promise;
    return promise;
  }

  const asyncComp = defineAsyncComponent({
    loader: () => triggerLoad(),
    loadingComponent: loadingComponent || DefaultLoadingComponent,
    errorComponent: createErrorComponent(moduleName, componentPath),
    delay: 0, // 由 triggerLoad 内部处理延迟
    timeout,
    onError(error, _retry, fail) {
      console.error(`[LazyComponent] 重试失败，放弃加载 | Module: ${moduleName} | Path: ${componentPath}`, '\n  最终错误:', error);
      fail();
    },
  });

  const component = defineComponent({
    name: `LazyDeferred_${moduleName.replace(/\W+/g, '_')}`,
    inheritAttrs: true,
    setup(_props, { attrs, slots }) {
      return () => (shouldMount.value ? h(asyncComp, attrs, slots) : null);
    },
  });

  function prefetch(): Promise<void> {
    return triggerLoad().catch(() => {
      // prefetch 失败不阻塞 UI，仅记录
    });
  }

  /** 语义化别名：等待加载完成（失败抛出异常，调用方可 try/catch） */
  function load(): Promise<void> {
    return triggerLoad().then(() => {});
  }

  return {
    component,
    isLoaded,
    prefetch,
    load,
  };
}

/** 从 () => import('./Foo.vue') 中提取 './Foo.vue' */
function extractPath(loader: () => Promise<unknown>): string {
  try {
    const src = loader.toString();
    const match = src.match(/import\s*\(\s*['"]([^'"]+)['"]\s*\)/);
    return match ? match[1] : '<unknown>';
  } catch {
    return '<unknown>';
  }
}

/**
 * useLazyModal — 延迟加载 + 弹窗控制的一体化钩子
 *
 * ## 解决的问题
 * 当弹窗组件通过 defineAsyncComponent 延迟加载时，用户可能在组件未就绪时
 * 点击打开按钮 → useModal.openModal 的 `?.` 静默失败，弹窗无法打开。
 *
 * ## 四层防御机制
 * 1. **加载感知队列** — 组件未就绪时 openModal 入队，register 后自动回放
 * 2. **按钮层守卫** — 暴露 isLoaded，按钮绑定 :loading="!isLoaded" + @mouseenter="prefetch"
 * 3. **错误边界** — 页面级 onErrorCaptured 防止级联崩溃
 * 4. **超时收窄** — 生产 10s 快速失败；开发态 120s 适配 Vite 首次编译
 * 5. **延迟挂载** — 进页不渲染弹窗 DOM，仅 prefetch / openModal 时才挂载并拉 chunk
 *
 * ## 用法
 * ```typescript
 * const { component: Form, register: registerForm, openModal: openFormModal, isLoaded } =
 *   useLazyModal(() => import('./Form.vue'), 'onlineDev/webDesign');
 *
 * // 模板: 完全兼容现有 @register 模式
 * // <Form @register="registerForm" @reload="reload" />
 * // <a-button :loading="!isLoaded" @mouseenter="prefetch" @click="openFormModal(true, data)">打开</a-button>
 * ```
 *
 * ## 与 useModal + useLazyComponent 的差异
 * - 接口兼容：register / openModal / closeModal 签名一致，可平滑迁移
 * - 额外暴露：isLoaded / prefetch 用于按钮层守卫
 * - openModal 变为 async：等待组件就绪后再打开（失败时 toast 错误提示）
 */

import { ref, type Component, type Ref } from 'vue';
import { useLazyComponent } from './useLazyComponent';
import type { LazyComponentResult } from './useLazyComponent';
import { useModal } from '/@/components/Modal';
import type { UseModalReturnType, RegisterFn } from '/@/components/Modal/src/typing';
import { useMessage } from '/@/hooks/web/useMessage';
import { isString } from '/@/utils/is';

interface LazyModalResult {
  /** 异步组件，直接用于模板（完全兼容 @register 模式） */
  component: Component;
  /** 注册函数，传给组件的 @register 事件（已内置队列回放逻辑） */
  register: RegisterFn;
  /** 安全打开弹窗：组件未就绪时等待加载，失败时 toast 报错 */
  openModal: <T = any>(visible?: boolean, data?: T, openOnSet?: boolean) => Promise<void>;
  /** 关闭弹窗 */
  closeModal: () => void;
  /** 是否已加载完成 */
  isLoaded: Ref<boolean>;
  /** 手动触发预加载（如绑定到按钮的 @mouseenter） */
  prefetch: () => Promise<void>;
}

/**
 * 一体化延迟加载弹窗钩子。
 *
 * @param loader - 动态 import 函数，如 () => import('./Form.vue')
 * @param moduleOrOptions - 模块名（字符串）或完整 LazyOptions
 */
export function useLazyModal(
  loader: () => Promise<Record<string, any>>,
  moduleOrOptions: string | { moduleName: string; timeout?: number },
): LazyModalResult {
  const { component, isLoaded, prefetch, load } = useLazyComponent(loader, moduleOrOptions);
  const [registerFn, methods] = useModal();
  const { createMessage } = useMessage();

  // ── 第 1 层：加载感知队列 ──
  // 组件未就绪时暂存 openModal 调用参数，组件 register 后自动回放
  const pendingQueue = ref<{
    visible: boolean;
    data?: any;
    openOnSet?: boolean;
  } | null>(null);

  /** 包装 register：在组件挂载注册时回放排队的 openModal 调用 */
  function wrappedRegister(modalMethod: any, uuid: string) {
    registerFn(modalMethod, uuid);

    const pending = pendingQueue.value;
    if (pending) {
      pendingQueue.value = null;
      // 延迟 50ms 确保组件内部状态就绪
      setTimeout(() => {
        methods.openModal(pending.visible, pending.data, pending.openOnSet);
      }, 50);
    }
  }

  /** 安全打开：组件未就绪时等待加载，失败则 toast 报错 */
  async function safeOpen<T = any>(visible = true, data?: T, openOnSet = true): Promise<void> {
    // 组件已就绪 → 直接打开
    if (isLoaded.value) {
      methods.openModal(visible, data, openOnSet);
      return;
    }

    // 组件未就绪 → 入队等待
    pendingQueue.value = { visible, data, openOnSet };

    let hide: (() => void) | undefined;
    try {
      hide = createMessage.loading('组件加载中…', 0);
    } catch {
      // message.loading 在某些上下文可能不可用，忽略
    }

    try {
      await load();
    } catch (err) {
      // 加载失败 → 清空队列、显示错误、静默返回
      pendingQueue.value = null;
      if (hide) hide();
      createMessage.error('组件加载失败，请刷新页面后重试');
      console.error('[useLazyModal] 组件加载失败', { moduleOrOptions, error: err });
      return;
    }

    if (hide) hide();

    // 加载成功但可能在 load() 期间 register 已触发并回放了队列
    // 如果队列还在（说明 register 还没来），保留让 wrappedRegister 回放
    // 否则直接打开
    if (!pendingQueue.value) {
      // 已被 wrappedRegister 回放，不再重复打开
      return;
    }
    pendingQueue.value = null;
    methods.openModal(visible, data, openOnSet);
  }

  return {
    component,
    register: wrappedRegister,
    openModal: safeOpen,
    closeModal: methods.closeModal,
    isLoaded,
    prefetch,
  };
}

export type { LazyModalResult };

import type { ModalFunc, ModalFuncProps } from 'ant-design-vue/lib/modal/Modal';

import { Modal, message as Message, notification } from 'ant-design-vue';
import { InfoCircleFilled, CheckCircleFilled, CloseCircleFilled } from '@ant-design/icons-vue';

import { NotificationArgsProps, ConfigProps } from 'ant-design-vue/lib/notification';
import { useI18n } from './useI18n';
import { isString } from '/@/utils/is';

export interface NotifyApi {
  info(config: NotificationArgsProps): void;
  success(config: NotificationArgsProps): void;
  error(config: NotificationArgsProps): void;
  warn(config: NotificationArgsProps): void;
  warning(config: NotificationArgsProps): void;
  open(args: NotificationArgsProps): void;
  close(key: String): void;
