import type { Router, RouteLocationNormalized } from 'vue-router';
import { useAppStoreWithOut } from '/@/store/modules/app';
import { useUserStoreWithOut } from '/@/store/modules/user';
import { useTransitionSetting } from '/@/hooks/setting/useTransitionSetting';
import { AxiosCanceler } from '/@/utils/http/axios/axiosCancel';
import { Modal, notification } from 'ant-design-vue';
import { warn } from '/@/utils/log';
import { unref } from 'vue';
import { setRouteChange } from '/@/logics/mitt/routeChange';
import { createPermissionGuard } from './permissionGuard';
import { createStateGuard } from './stateGuard';
import nProgress from 'nprogress';
import projectSetting from '/@/settings/projectSetting';
import { errorReporter } from '/@/utils/error-reporter';
// import { createParamMenuGuard } from './paramMenuGuard';

// Don't change the order of creation
export function setupRouterGuard(router: Router) {
  createPageGuard(router);
  createPageLoadingGuard(router);
  createHttpGuard(router);
  createScrollGuard(router);
  createMessageGuard(router);
  createProgressGuard(router);
  createPermissionGuard(router);
  // createParamMenuGuard(router); // must after createPermissionGuard (menu has been built.)
  createStateGuard(router);

  // 路由级错误捕获：异步组件加载失败、chunk 加载失败等
  router.onError(error => {
    errorReporter.report({
      message: `路由加载失败: ${error.message}`,
      stack: error.stack,
      source: 'vue',
    });

    // chunk 加载失败自动刷新（通常是版本更新后旧 chunk 被删除）
    if (/Loading chunk \d+ failed/.test(error.message) || /Failed to fetch dynamically imported module/.test(error.message)) {
      window.location.reload();
    }
  });
}

/**
 * Hooks for handling page state
 */
function createPageGuard(router: Router) {
  const loadedPageMap = new Map<string, boolean>();

  router.beforeEach(async to => {
    // The page has already been loaded, it will be faster to open it again, you don’t need to do loading and other processing
    to.meta.loaded = !!loadedPageMap.get(to.path);
    // Notify routing changes
    setRouteChange(to);

    return true;
  });

  router.afterEach(to => {
    loadedPageMap.set(to.path, true);
  });
}

// Used to handle page loading status
function createPageLoadingGuard(router: Router) {
  const userStore = useUserStoreWithOut();
  const appStore = useAppStoreWithOut();
  const { getOpenPageLoading } = useTransitionSetting();
  router.beforeEach(async to => {
    if (!userStore.getToken) {
      return true;
    }
    if (to.meta.loaded) {
      return true;
    }

    if (unref(getOpenPageLoading)) {
      appStore.setPageLoadingAction(true);
      return true;
    }

    return true;
  });
  router.afterEach(async () => {
    if (unref(getOpenPageLoading)) {
      // TODO Looking for a better way
      // The timer simulates the loading time to prevent flashing too fast,
      setTimeout(() => {
        appStore.setPageLoading(false);
      }, 220);
    }
    return true;
  });
}

/**
 * The interface used to close the current page to complete the request when the route is switched
 * @param router
 */
function createHttpGuard(router: Router) {
  const { removeAllHttpPending } = projectSetting;
  let axiosCanceler: Nullable<AxiosCanceler>;
  if (removeAllHttpPending) {
    axiosCanceler = new AxiosCanceler();
  }
  router.beforeEach(async () => {
    // Switching the route will delete the previous request
    axiosCanceler?.removeAllPending();
    return true;
  });
}

// Routing switch back to the top
function createScrollGuard(router: Router) {
  const isHash = (href: string) => {
    return /^#/.test(href);
  };

  const body = document.body;

  router.afterEach(async to => {
    // scroll top
    isHash((to as RouteLocationNormalized & { href: string })?.href) && body.scrollTo(0, 0);
    return true;
  });
}

/**
 * Used to close the message instance when the route is switched
 * @param router
 */
export function createMessageGuard(router: Router) {
  const { closeMessageOnSwitch } = projectSetting;

  router.beforeEach(async () => {
    try {
      if (closeMessageOnSwitch) {
        Modal.destroyAll();
        notification.destroy();
      }
    } catch (error) {
      warn('message guard error:' + error);
    }
    return true;
  });
}

export function createProgressGuard(router: Router) {
  const { getOpenNProgress } = useTransitionSetting();
  router.beforeEach(async to => {
    if (to.meta.loaded) {
      return true;
    }
    unref(getOpenNProgress) && nProgress.start();
    return true;
  });

  router.afterEach(async () => {
    unref(getOpenNProgress) && nProgress.done();
    return true;
  });
}

import type { Router, RouteRecordRaw } from 'vue-router';

import { usePermissionStoreWithOut } from '/@/store/modules/permission';

import { PageEnum } from '/@/enums/pageEnum';
import { useUserStoreWithOut } from '/@/store/modules/user';

import { PAGE_NOT_FOUND_ROUTE } from '/@/router/routes/basic';

const LOGIN_PATH = PageEnum.BASE_LOGIN;
const SSO_PATH = PageEnum.BASE_SSO;
const BASE_FORM_SHORT_LINK_PATH = PageEnum.BASE_FORM_SHORT_LINK;

const whitePathList: PageEnum[] = [LOGIN_PATH, SSO_PATH, BASE_FORM_SHORT_LINK_PATH];

// Founder path prefix (D-4: 2026-06-20 — TOTP session binding)
const FOUNDER_PATH_PREFIX = '/studio/founder';
const FOUNDER_TOTP_PATH = '/studio/founder/totp-verify';
const FOUNDER_SESSION_KEY = 'founder_totp_session';

function isFounderSessionValid(): boolean {
  try {
    const raw = localStorage.getItem(FOUNDER_SESSION_KEY);
    if (!raw) return false;
    const session = JSON.parse(raw);
    return session?.expiresAt && Date.now() < session.expiresAt;
  } catch {
    return false;
  }
}

export function createPermissionGuard(router: Router) {
  const userStore = useUserStoreWithOut();
  const permissionStore = usePermissionStoreWithOut();
  router.beforeEach(async (to, from, next) => {
    const token = userStore.getToken;

    // Founder TOTP guard (D-4): redirect to TOTP verify if session expired/missing
    if (to.path.startsWith(FOUNDER_PATH_PREFIX) && to.path !== FOUNDER_TOTP_PATH && !isFounderSessionValid()) {
      next({
        path: FOUNDER_TOTP_PATH,
        query: { redirect: to.fullPath },
        replace: true,
      });
      return;
    }

    // Founder session is valid and navigating to TOTP page → skip to target
    if (to.path === FOUNDER_TOTP_PATH && isFounderSessionValid()) {
      const redirect = (to.query.redirect as string) || '/studio/founder/console';
      next({ path: redirect, replace: true });
      return;
    }

    if (to.path == '/workFlowDetail' && to.query.token && token != to.query.token) {
      userStore.updateToken(to.query.token as string);
      next({ ...to, replace: true });
      return;
    }

    // Whitelist can be directly entered
    if (whitePathList.includes(to.path as PageEnum)) {
      if (to.path === LOGIN_PATH && token) {
        const isSessionTimeout = userStore.getSessionTimeout;
        try {
          await userStore.afterLoginAction();
          if (!isSessionTimeout) {
            next((to.query?.redirect as string) || '/');
            return;
          }
        } catch {}
      }
      next();
      return;
    }

    // token does not exist
    if (!token) {
      // You can access without permission. You need to set the routing meta.ignoreAuth to true
      if (to.meta.ignoreAuth) {
        next();
        return;
      }

      // redirect login page
      const redirectData: { path: string; replace: boolean; query?: Recordable<string> } = {
        path: LOGIN_PATH,
        replace: true,
      };
      if (to.path) {
        redirectData.query = {
          ...redirectData.query,
          redirect: to.path,
        };
      }
      next(redirectData);
      return;
    }

    // Jump to the 404 page after processing the login
    if (from.path === LOGIN_PATH && to.name === PAGE_NOT_FOUND_ROUTE.name && to.fullPath !== PageEnum.BASE_HOME) {
      next(PageEnum.BASE_HOME);
      return;
    }

    // get userinfo while last fetch time is empty
    if (userStore.getLastUpdateTime === 0) {
      try {
        await userStore.getUserInfoAction();
      } catch (err) {
        next();
        return;
      }
    }

    if (permissionStore.getIsDynamicAddedRoute) {
      next();
      return;
    }

    const routes = await permissionStore.buildRoutesAction();

    routes.forEach(route => {
      router.addRoute(route as unknown as RouteRecordRaw);
    });

    router.addRoute(PAGE_NOT_FOUND_ROUTE as unknown as RouteRecordRaw);

    permissionStore.setDynamicAddedRoute(true);

    if (to.name === PAGE_NOT_FOUND_ROUTE.name) {
      // 动态添加路由后，此处应当重定向到fullPath，否则会加载404页面内容
      next({ path: to.fullPath, replace: true, query: to.query });
    } else {
      const redirectPath = (from.query.redirect || to.path) as string;
      const redirect = decodeURIComponent(redirectPath);
      const nextData = to.path === redirect ? { ...to, replace: true } : { path: redirect };
      next(nextData);
    }
  });
}

import { AppRouteModule } from '/@/router/types';
import type { MenuModule, Menu, AppRouteRecordRaw } from '/@/router/types';
import { findPath, treeMap } from '/@/utils/helper/treeHelper';
import { cloneDeep } from 'lodash-es';
import { isUrl } from '/@/utils/is';
import { RouteParams } from 'vue-router';
import { toRaw } from 'vue';

export function getAllParentPath<T = Recordable>(treeData: T[], path: string) {
  const menuList = findPath(treeData, n => n.path === path) as Menu[];
  return (menuList || []).map(item => item.path);
}

// 路径处理
function joinParentPath(menus: Menu[], parentPath = '') {
  for (let index = 0; index < menus.length; index++) {
    const menu = menus[index];
    // https://next.router.vuejs.org/guide/essentials/nested-routes.html
    // Note that nested paths that start with / will be treated as a root path.
    // 请注意，以 / 开头的嵌套路径将被视为根路径。
    // This allows you to leverage the component nesting without having to use a nested URL.
    // 这允许你利用组件嵌套，而无需使用嵌套 URL。
    if (!(menu.path.startsWith('/') || isUrl(menu.path))) {
      // path doesn't start with /, nor is it a url, join parent path
      // 路径不以 / 开头，也不是 url，加入父路径
      menu.path = `${parentPath}/${menu.path}`;
    }
    if (menu?.children?.length) {
      joinParentPath(menu.children, menu.meta?.hidePathForChildren ? parentPath : menu.path);
    }
  }
}

// Parsing the menu module
export function transformMenuModule(menuModule: MenuModule): Menu {
  const { menu } = menuModule;

  const menuList = [menu];

  joinParentPath(menuList);
  return menuList[0];
}

// 将路由转换成菜单
export function transformRouteToMenu(routeModList: AppRouteModule[], routerMapping = false) {
  // 借助 lodash 深拷贝
  const cloneRouteModList = cloneDeep(routeModList);
  const routeList: AppRouteRecordRaw[] = [];

  // 对路由项进行修改
  cloneRouteModList.forEach(item => {
    if (routerMapping && item.meta.hideChildrenInMenu && typeof item.redirect === 'string') {
      item.path = item.redirect;
    }

    if (item.meta?.single) {
      const realItem = item?.children?.[0];
      realItem && routeList.push(realItem);
    } else {
      routeList.push(item);
    }
  });
  // 提取树指定结构
  const list = treeMap(routeList, {
    conversion: (node: AppRouteRecordRaw) => {
      const { meta: { title, hideMenu = false } = {} } = node;

      return {
        ...(node.meta || {}),
        meta: node.meta,
        name: title,
        hideMenu,
        path: node.path,
        ...(node.redirect ? { redirect: node.redirect } : {}),
      };
    },
  });
  // 路径处理
  joinParentPath(list as unknown as Menu[]);
  return cloneDeep(list);
}

/**
 * config menu with given params
 */
const menuParamRegex = /(?::)([\s\S]+?)((?=\/)|$)/g;

export function configureDynamicParamsMenu(menu: Menu, params: RouteParams) {
  const { path, paramPath } = toRaw(menu) as any;
  let realPath = paramPath ? paramPath : path;
  const matchArr = realPath.match(menuParamRegex);

  matchArr?.forEach(it => {
    const realIt = it.substr(1);
    if (params[realIt]) {
      realPath = realPath.replace(`:${realIt}`, params[realIt] as string);
    }
  });
  // save original param path.
  if (!paramPath && matchArr && matchArr.length > 0) {
    (menu as any).paramPath = path;
  }
  menu.path = realPath;
  // children
  menu.children?.forEach(item => configureDynamicParamsMenu(item, params));
}

import type { AppRouteModule, AppRouteRecordRaw } from '/@/router/types';
import type { Router, RouteRecordNormalized } from 'vue-router';
import { PageEnum } from '/@/enums/pageEnum';

import { getParentLayout, LAYOUT, EXCEPTION_COMPONENT } from '/@/router/constant';
import { cloneDeep, omit } from 'lodash-es';
import { warn } from '/@/utils/log';
import { createRouter, createWebHashHistory } from 'vue-router';
import { defineComponent, defineAsyncComponent, h } from 'vue';
import { useGlobSetting } from '/@/hooks/setting';
import { getRawToken } from '/@/utils/auth';
import { BackMenu } from '/@/api/basic/model/userModel';

export type LayoutMapKey = 'LAYOUT';
const IFRAME = () => import('/@/views/basic/iframe/FrameBlank.vue');
const ONLINE_MODEL = () => import('/@/views/common/dynamicModel/index.vue');
const ONLINE_DICT = () => import('/@/views/common/dynamicDictionary/index.vue');
const ONLINE_REPORT = () => import('/@/views/common/dynamicDataReport/index.vue');
const ONLINE_PORTAL = () => import('/@/views/common/dynamicPortal/index.vue');

const LayoutMap = new Map<string, () => Promise<typeof import('*.vue')>>();

LayoutMap.set('LAYOUT', LAYOUT);
LayoutMap.set('IFRAME', IFRAME);
LayoutMap.set('ONLINE_MODEL', ONLINE_MODEL);
LayoutMap.set('ONLINE_DICT', ONLINE_DICT);
LayoutMap.set('ONLINE_REPORT', ONLINE_REPORT);
LayoutMap.set('ONLINE_PORTAL', ONLINE_PORTAL);

let dynamicViewsModules: Record<string, () => Promise<Recordable>>;

/**
 * 将指定组件设置自定义名称
 *
 * @param {String} name 组件自定义名称
 * @param {AsyncComponent} component
 * @return {Component}
 */
function createCustomComponent(customName, asyncComponent) {
  return defineComponent({
    name: customName,
    setup() {
      return () => h(asyncComponent);
    },
  });
}

// Dynamic introduction
function asyncImportRoute(routes: AppRouteRecordRaw[] | undefined) {
  dynamicViewsModules = dynamicViewsModules || import.meta.glob('../../views/**/*.{vue,tsx}');
  if (!routes) return;
  routes.forEach(item => {
    if (!item.component && item.meta?.frameSrc) {
      item.component = 'IFRAME';
    }
    const { component, name } = item;
    const { children } = item;
    if (component) {
      const layoutFound = LayoutMap.get(component.toUpperCase());
      if (layoutFound) {
        item.component = ['LAYOUT', 'IFRAME'].includes(component) ? layoutFound : createCustomComponent(name, defineAsyncComponent(layoutFound));
      } else {
        item.component = dynamicImport(dynamicViewsModules, component as string);
      }
    } else if (name) {
      item.component = getParentLayout();
    }
    children && asyncImportRoute(children);
  });
}

function dynamicImport(dynamicViewsModules: Record<string, () => Promise<Recordable>>, component: string) {
  const keys = Object.keys(dynamicViewsModules);

  const matchKeys = keys.filter(key => {
    const k = key.replace('../../views', '');
    const startFlag = component.startsWith('/');
    const endFlag = component.endsWith('.vue') || component.endsWith('.tsx');
    const startIndex = startFlag ? 0 : 1;
    const lastIndex = endFlag ? k.length : k.lastIndexOf('.');
    return k.substring(startIndex, lastIndex) === component || k.substring(startIndex, lastIndex) === component + '/index';
  });
  if (matchKeys?.length === 1) {
    const matchKey = matchKeys[0];
    return dynamicViewsModules[matchKey];
  } else if (matchKeys?.length > 1) {
    warn(
      'Please do not create `.vue` and `.TSX` files with the same file name in the same hierarchical directory under the views folder. This will cause dynamic introduction failure',
    );
    return;
  } else {
    // warn('在src/views/下找不到`' + component + '.vue` 或 `' + component + '.tsx`, 请自行创建!');
    return EXCEPTION_COMPONENT;
  }
}

// Turn background objects into routing objects
// 将背景对象变成路由对象
export function transformObjToRoute<T = AppRouteModule>(routerList: BackMenu[]): T[] {
  const globSetting = useGlobSetting();
  const routeList: AppRouteModule[] = [];
  function getRouteList(routerList: any) {
    for (let i = 0; i < routerList.length; i++) {
      const e = routerList[i];
      const name = e.enCode.replace(/\./g, '-');
      if (e.type == 0 && e.hasChildren && e.children.length) {
        getRouteList(e.children);
      }
      if (e.type == 1) {
        e.path = '/' + e.enCode;
        if (e.hasChildren && e.children.length) {
          getRouteList(e.children);
        }
      }
      if (e.type == 2) {
        let path = e.urlAddress;
        if (path.indexOf('?') > -1) path = path.split('?')[0];
        e.path = '/' + e.urlAddress;
        const route: AppRouteModule = {
          path: '/' + path,
          component: path,
          name: name,
          meta: {
            title: 'routes.' + name,
            defaultTitle: e.fullName,
            icon: e.icon,
            modelId: e.id,
          },
        };
        routeList.push(route);
      }
      // 功能、字典、报表、门户
      if ([3, 4, 5, 8].indexOf(e.type) > -1) {
        let propertyJson = e.propertyJson ? JSON.parse(e.propertyJson) : null,
          relationId = '',
          isTree = 0,
          component = '';
        if (propertyJson) {
          relationId = propertyJson.moduleId || '';
          isTree = propertyJson.isTree || 0;
        }
        if (e.type == 3) {
          component = 'ONLINE_MODEL';
        } else if (e.type == 4) {
          component = 'ONLINE_DICT';
        } else if (e.type == 5) {
          component = 'ONLINE_REPORT';
        } else {
          component = 'ONLINE_PORTAL';
        }
        const componentName = component + '_' + name;
        e.path = '/' + e.urlAddress;
        const route: AppRouteModule = {
          path: '/' + e.urlAddress,
          component: component,
          name: componentName,
          meta: {
            title: 'routes.' + e.enCode.replaceAll(/\./g, '-'),
            defaultTitle: e.fullName,
            icon: e.icon,
            modelId: e.id,
            relationId,
            isTree,
          },
        };
        routeList.push(route);
      }
      // 大屏
      if (e.type == 6) {
        let propertyJson = e.propertyJson ? JSON.parse(e.propertyJson) : null,
          moduleId = '';
        if (propertyJson) moduleId = propertyJson.moduleId || '';
        e.path = `${globSetting.dataVUrl}view/${moduleId}?token=${getRawToken()}`;
      }
      // 外链
      if (e.type == 7) {
        const path = e.urlAddress.replace(/\${dataV}/g, globSetting.dataVUrl).replace(/\${jnpfToken}/g, getRawToken());
        if (e.linkTarget === '_self') {
          e.path = '/' + e.enCode;
          const route: AppRouteModule = {
            path: '/' + e.enCode,
            component: 'IFRAME',
            name: name,
            meta: {
              title: 'routes.' + name,
              defaultTitle: e.fullName,
              icon: e.icon,
              modelId: e.id,
              frameSrc: path,
            },
          };
          routeList.push(route);
        } else {
          e.path = path;
          const route: AppRouteModule = {
            path: path,
            component: 'IFRAME',
            name: name,
            meta: {
              title: 'routes.' + name,
              defaultTitle: e.fullName,
              icon: e.icon,
              modelId: e.id,
            },
          };
          routeList.push(route);
        }
      }
    }
  }
  getRouteList(routerList);
  asyncImportRoute(routeList);
  const RootRoute: AppRouteRecordRaw = {
    path: '/asyncRoutes',
    name: 'asyncRoutes',
    redirect: PageEnum.BASE_HOME,
    component: LAYOUT,
    meta: {
      title: 'asyncRoutes',
    },
    children: routeList,
  };
  const asyncRouteList: AppRouteRecordRaw[] = [RootRoute];

  return asyncRouteList as unknown as T[];
}

/**
 * Convert multi-level routing to level 2 routing
 * 将多级路由转换为 2 级路由
 */
export function flatMultiLevelRoutes(routeModules: AppRouteModule[]) {
  const modules: AppRouteModule[] = cloneDeep(routeModules);

  for (let index = 0; index < modules.length; index++) {
    const routeModule = modules[index];
    // 判断级别是否 多级 路由
    if (!isMultipleRoute(routeModule)) {
      // 声明终止当前循环， 即跳过此次循环，进行下一轮
      continue;
    }
    // 路由等级提升
    promoteRouteLevel(routeModule);
  }
  return modules;
}

// Routing level upgrade
// 路由等级提升
function promoteRouteLevel(routeModule: AppRouteModule) {
  // Use vue-router to splice menus
  // 使用vue-router拼接菜单
  // createRouter 创建一个可以被 Vue 应用程序使用的路由实例
  let router: Router | null = createRouter({
    routes: [routeModule as unknown as RouteRecordNormalized],
    history: createWebHashHistory(),
  });
  // getRoutes： 获取所有 路由记录的完整列表。
  const routes = router.getRoutes();
  // 将所有子路由添加到二级路由
  addToChildren(routes, routeModule.children || [], routeModule);
  router = null;

  // omit lodash的函数 对传入的item对象的children进行删除
  routeModule.children = routeModule.children?.map(item => omit(item, 'children'));
}

// Add all sub-routes to the secondary route
// 将所有子路由添加到二级路由
function addToChildren(routes: RouteRecordNormalized[], children: AppRouteRecordRaw[], routeModule: AppRouteModule) {
  for (let index = 0; index < children.length; index++) {
    const child = children[index];
    const route = routes.find(item => item.name === child.name);
    if (!route) {
      continue;
    }
    routeModule.children = routeModule.children || [];
    if (!routeModule.children.find(item => item.name === route.name)) {
      routeModule.children?.push(route as unknown as AppRouteModule);
    }
    if (child.children?.length) {
      addToChildren(routes, child.children, routeModule);
    }
  }
}

// Determine whether the level exceeds 2 levels
// 判断级别是否超过2级
function isMultipleRoute(routeModule: AppRouteModule) {
  // Reflect.has 与 in 操作符 相同, 用于检查一个对象(包括它原型链上)是否拥有某个属性
  if (!routeModule || !Reflect.has(routeModule, 'children') || !routeModule.children?.length) {
    return false;
  }

  const children = routeModule.children;

  let flag = false;
  for (let index = 0; index < children.length; index++) {
    const child = children[index];
    if (child.children?.length) {
      flag = true;
      break;
    }
  }
  return flag;
}

import type { ProjectConfig, HeaderSetting, MenuSetting, TransitionSetting, MultiTabsSetting } from '/#/config';
