import { reactive, defineAsyncComponent, markRaw } from 'vue';
import { getAuthPortal, UpdateCustomPortal } from '/@/api/onlineDev/portal';
import { getDataInterfaceRes } from '/@/api/systemData/dataInterface';
import { importViewsFile } from '/@/utils';
import { getParamList } from '/@/utils/jnpf';

interface State {
  portalId: string;
  layout: any[];
  type: number;
  linkType: number;
  currentView: string;
  url: string;
  ajaxing: boolean;
  loading: boolean;
  noData: boolean;
  refreshData: any;
  timerList: any[];
  formData: any;
  enabledLock: number;
  systemId: string;
}

const state = reactive<State>({
  portalId: '',
  layout: [],
  type: 0,
  linkType: 0,
  currentView: '',
  url: '',
  ajaxing: true,
  loading: false,
  noData: false,
  refreshData: {},
  timerList: [],
  formData: {},
  enabledLock: 1,
  systemId: '',
});

export function usePortal() {
  function initData() {
    state.loading = true;
    state.layout = [];
    state.noData = false;
    if (!state.portalId) {
      state.loading = false;
      state.ajaxing = false;
      state.noData = true;
      return;
    }
    getAuthPortal(state.portalId, { platform: 'Web', systemId: state.systemId })
      .then(res => {
        if (res.data) {
          state.type = res.data.type || 0;
          state.linkType = res.data.linkType || 0;
          state.url = res.data.customUrl || '';
          state.enabledLock = res.data.enabledLock || 0;
          if (res.data.type === 1) {
            if (res.data.customUrl && res.data.customUrl !== 1) {
              const formUrl = `${res.data.customUrl}`;
              state.currentView = markRaw(defineAsyncComponent(() => importViewsFile(formUrl)));
            }
          } else {
            if (res.data.formData) {
              state.formData = JSON.parse(res.data.formData);
              state.layout = filterList(JSON.parse(JSON.stringify(state.formData.layout)) || []);
              state.refreshData = state.formData.refresh || {};
            }
          }
        }
        state.ajaxing = false;
        state.loading = false;
        setTimeout(() => {
          initAutoRefresh();
        }, 500);
      })
      .catch(() => {
        state.loading = false;
        state.ajaxing = false;
        state.noData = true;
      });
  }
  function filterList(layout) {
    const loop = list => {
      for (let i = 0; i < list.length; i++) {
        const item = list[i];
        if (!(Array.isArray(item.visibility) && item.visibility.includes('pc')) && item.jnpfKey) {
          list.splice(i, 1);
          i--;
        }
        if (item.children && item.children.length) loop(item.children);
      }
    };
    loop(layout);
    return layout;
  }
  function initAutoRefresh() {
    if (!state.layout.length) return;
    state.timerList = [];
    const loop = (list, type = 1) => {
      list.forEach(ele => {
        if ((ele.refresh && ele.refresh.autoRefresh && ele.refresh.autoRefreshTime) || type == 2) {
          const timer = setInterval(
            () => {
              ele.renderKey = +new Date();
              autoRefresh(ele);
            },
            type == 2 ? state.refreshData.autoRefreshTime * 1000 * 60 : ele.refresh.autoRefreshTime * 1000 * 60,
          );
          state.timerList.push(timer);
        }
        if (ele.children && ele.children.length) loop(ele.children, type);
      });
    };
    if (state.refreshData.autoRefresh) {
      loop(state.layout, 2);
    } else {
      loop(state.layout);
    }
  }
  function autoRefresh(item) {
    const chartList = ['barChart', 'lineChart', 'pieChart', 'radarChart', 'mapChart'];
    if (item.dataType === 'dynamic' && chartList.includes(item.jnpfKey)) {
      item.option.defaultValue = [];
      if (!item.propsApi) return;
      const query = { paramList: getParamList(item.templateJson) };
      getDataInterfaceRes(item.propsApi, query).then(res => {
        const realData = res.data;
        item.option.defaultValue = Array.isArray(realData) ? realData : [];
      });
    }
  }
  function clearAutoRefresh() {
    if (state.timerList.length) {
      state.timerList.forEach(ele => {
        if (ele) clearInterval(ele);
      });
    }
  }
  function layoutUpdatedEvent() {
    state.formData.layout = state.layout;
    const query = { formData: JSON.stringify(state.formData), systemId: state.systemId };
    UpdateCustomPortal(state.portalId, query);
  }
  return {
    state: state,
    initData,
    filterList,
    initAutoRefresh,
    autoRefresh,
    clearAutoRefresh,
    layoutUpdatedEvent,
  };
}

import type { FormInstance } from 'ant-design-vue';
import type { Rule, RuleObject, NamePath } from 'ant-design-vue/lib/form/interface';
import { ref, computed, unref, Ref } from 'vue';
import { useI18n } from '/@/hooks/web/useI18n';

export enum LoginStateEnum {
  LOGIN,
  REGISTER,
  RESET_PASSWORD,
  MOBILE,
  QR_CODE,
}

const currentState = ref(LoginStateEnum.LOGIN);

export function useLoginState() {
  function setLoginState(state: LoginStateEnum) {
    currentState.value = state;
  }

  const getLoginState = computed(() => currentState.value);

  function handleBackLogin() {
    setLoginState(LoginStateEnum.LOGIN);
  }

  return { setLoginState, getLoginState, handleBackLogin };
}

export function useFormValid<T extends Object = any>(formRef: Ref<FormInstance>) {
  const validate = computed(() => {
    const form = unref(formRef);
    return form?.validate ?? ((_nameList?: NamePath) => Promise.resolve());
  });

  async function validForm() {
    const form = unref(formRef);
    if (!form) return;
    const data = await form.validate();
    return data as T;
  }

  return { validate, validForm };
}

export function useFormRules(formData?: Recordable) {
  const { t } = useI18n();

  const getAccountFormRule = computed(() => createRule(t('sys.login.accountPlaceholder')));
  const getPasswordFormRule = computed(() => createRule(t('sys.login.passwordPlaceholder')));
  const getCodeFormRule = computed(() => createRule(t('sys.login.codeTip')));
  const getSmsFormRule = computed(() => createRule(t('sys.login.smsPlaceholder')));
  const getMobileFormRule = computed(() => createRule(t('sys.login.mobilePlaceholder')));

  const validatePolicy = async (_: RuleObject, value: boolean) => {
    return !value ? Promise.reject(t('sys.login.policyPlaceholder')) : Promise.resolve();
  };

  const validateConfirmPassword = (password: string) => {
    return async (_: RuleObject, value: string) => {
      if (!value) {
        return Promise.reject(t('sys.login.passwordPlaceholder'));
      }
      if (value !== password) {
        return Promise.reject(t('sys.login.diffPwd'));
      }
      return Promise.resolve();
    };
  };

  const getFormRules = computed((): { [k: string]: Rule | Rule[] } => {
    const accountFormRule = unref(getAccountFormRule);
    const passwordFormRule = unref(getPasswordFormRule);
    const codeFormRule = unref(getCodeFormRule);
    const smsFormRule = unref(getSmsFormRule);
    const mobileFormRule = unref(getMobileFormRule);

    const mobileRule = {
      sms: smsFormRule,
      mobile: mobileFormRule,
    };
    switch (unref(currentState)) {
      // register form rules
      case LoginStateEnum.REGISTER:
        return {
          account: accountFormRule,
          password: passwordFormRule,
          confirmPassword: [{ validator: validateConfirmPassword(formData?.password), trigger: 'change' }],
          policy: [{ validator: validatePolicy, trigger: 'change' }],
          ...mobileRule,
        };

      // reset password form rules
      case LoginStateEnum.RESET_PASSWORD:
        return {
          account: accountFormRule,
          ...mobileRule,
        };

      // mobile form rules
      case LoginStateEnum.MOBILE:
        return mobileRule;

      // login form rules
      default:
        return {
          account: accountFormRule,
          password: passwordFormRule,
          code: codeFormRule,
        };
    }
  });
  return { getFormRules };
}

function createRule(message: string): RuleObject[] {
  return [
    {
      required: true,
      message,
      trigger: 'change',
    },
  ];
}

import type {
  AttachmentsReadyPayload,
  ChatStreamAction,
  GateErrorPayload,
  GateFailedPayload,
  GatePassedPayload,
  IdentifiedElement,
  MissingElement,
  SemanticFitnessResult,
} from '../types/gate';

function pick<T>(obj: any, ...keys: string[]): T | undefined {
  if (!obj) return undefined;
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null) return obj[k];
  }
  return undefined;
}

/** 强制转成可读字符串，避免 `[object Object]` / `arr+undefined` 拼进 Markdown */
function asText(value: unknown, fallback = ''): string {
  if (value === undefined || value === null) return fallback;
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    return value
      .map(v => asText(v))
      .filter(Boolean)
      .join('；');
  }
  if (typeof value === 'object') {
    const o = value as Record<string, unknown>;
    const nested =
      o.description ?? o.Description ?? o.text ?? o.Text ?? o.message ?? o.Message ?? o.howToFix ?? o.HowToFix;
    if (nested !== undefined && nested !== value) return asText(nested, fallback);
    try {
      return JSON.stringify(value);
    } catch {
      return fallback;
    }
  }
  return fallback;
}

function asArray(value: unknown): any[] {
  return Array.isArray(value) ? value : [];
}

export function normalizeIdentified(raw: any): IdentifiedElement {
  return {
    category: asText(pick(raw, 'category', 'Category')),
    description: asText(pick(raw, 'description', 'Description')),
    evidence: asText(pick(raw, 'evidence', 'Evidence')) || undefined,
  };
}

export function normalizeMissing(raw: any): MissingElement {
  return {
    category: asText(pick(raw, 'category', 'Category')),
    description: asText(pick(raw, 'description', 'Description')),
    severity: asText(pick(raw, 'severity', 'Severity'), 'warning') || 'warning',
    howToFix: asText(pick(raw, 'howToFix', 'HowToFix')),
  };
}

export function normalizeSemanticFitness(raw: any): SemanticFitnessResult | null {
  if (!raw) return null;
  const sf = raw.semanticFitness ?? raw.SemanticFitness ?? raw;
  const identified = asArray(pick(sf, 'identified', 'Identified')).map(normalizeIdentified);
  const missing = asArray(pick(sf, 'missing', 'Missing')).map(normalizeMissing);
  const levelRaw = pick(sf, 'level', 'Level');
  const level =
    typeof levelRaw === 'number'
      ? ['sufficient', 'partial', 'insufficient'][levelRaw] ?? 'insufficient'
      : asText(levelRaw, 'insufficient') || 'insufficient';
  return {
    passed: Boolean(pick(sf, 'passed', 'Passed') ?? false),
    score: Number(pick(sf, 'score', 'Score') ?? 0) || 0,
    level,
    identified,
    missing,
    nextStepGuidance: asText(pick(sf, 'nextStepGuidance', 'NextStepGuidance')) || undefined,
  };
}

export function parseGatePayload<T>(dataField: unknown): T | null {
  if (!dataField) return null;
  if (typeof dataField === 'string') {
    try {
      return JSON.parse(dataField) as T;
    } catch {
      return null;
    }
  }
  return dataField as T;
}

function escapeCell(text: unknown): string {
  return asText(text).replace(/\|/g, '\\|').replace(/\n/g, ' ');
}

function identifiedTable(items: IdentifiedElement[]): string {
  if (!items.length) return '';
  const rows = items.map(i => `| ${escapeCell(i.category)} | ${escapeCell(i.description)} | ${escapeCell(i.evidence ?? '—')} |`).join('\n');
  return `### ✅ 已识别的要素\n\n| 类别 | 描述 | 依据 |\n| --- | --- | --- |\n${rows}\n`;
}

function missingTable(items: MissingElement[]): string {
  if (!items.length) return '';
  const rows = items
    .map(m => {
      const category = escapeCell(m?.category);
      const description = escapeCell(m?.description);
      const howToFix = escapeCell(m?.howToFix);
      // 防御：若仍出现裸对象字符串化，强制 JSON，避免页面出现 [object Object]
      const safeCat = category.includes('[object Object]') ? escapeCell(JSON.stringify(m?.category ?? '')) : category;
      const safeDesc = description.includes('[object Object]') ? escapeCell(JSON.stringify(m?.description ?? '')) : description;
      const safeFix = howToFix.includes('[object Object]') ? escapeCell(JSON.stringify(m?.howToFix ?? '')) : howToFix;
      const sev = m.severity === 'critical' ? '**严重**' : '提示';
      return `| ${safeCat || '—'} | ${safeDesc || '—'} | ${sev} | ${safeFix || '—'} |`;
    })
    .join('\n');
  return `### ❌ 需要补充的关键要素\n\n| 类别 | 问题 | 严重程度 | 如何补充 |\n| --- | --- | --- | --- |\n${rows}\n`;
}

function levelLabel(level: string, score: number): string {
  if (level === 'partial') return '部分合格';
  if (level === 'sufficient') return '合格';
  return score >= 50 ? '接近合格' : '不合格';
}

export function buildGateFailedMarkdown(payload: GateFailedPayload, sf: SemanticFitnessResult): string {
  const lines: string[] = [
    '## ⚠️ 需求材料尚未达到进入流水线的标准',
    '',
    'SA 门控要求：原始需求必须能解析为**至少一个合格的业务事件**（非单纯增删改查），并具备可推断的**角色**与**数据实体**。',
    '',
  ];
  const reason = asText(payload.reason);
  const hint = asText(payload.hint);
  // GATE_LLM_ERR 等系统失败：reason=BuildSummary 会与下方表格重复，只保留简短 hint
  const isSystemGateErr = sf.missing.some(
    m => asText(m.description).includes('GATE_') || asText(m.category) === '系统',
  );
  if (!isSystemGateErr && reason) lines.push(`> ${reason.replace(/\n/g, '\n> ')}`, '');
  if (hint) lines.push(`> 💡 ${hint.replace(/\n/g, '\n> ')}`, '');
  lines.push(`**评估评分：${sf.score}/100** · 等级：${levelLabel(asText(sf.level), Number(sf.score) || 0)}`, '');
  if (sf.identified.length) lines.push(identifiedTable(sf.identified), '');
  if (sf.missing.length) lines.push(missingTable(sf.missing), '');
  const guidance = asText(sf.nextStepGuidance);
  if (guidance && guidance !== hint) {
    lines.push('### 📌 下一步建议', '', guidance, '');
  }
  const warnings = asArray(payload.warnings).map(w => asText(w)).filter(Boolean);
  if (warnings.length) {
    lines.push('### 附件/格式提示', '', ...warnings.map(w => `- ${w}`), '');
  }
  lines.push('---', '', '请在下方输入框**补充业务场景描述**后重新发送；也可点击消息中的快捷按钮填入参考范例。');
  return lines.join('\n');
}

export function buildGatePassedMarkdown(payload: GatePassedPayload, sf: SemanticFitnessResult): string {
  const lines: string[] = [
    '## ✅ 需求材料评估通过',
    '',
    `**评估评分：${sf.score}/100** · 已识别 **${
      sf.identified.filter(i => i.category === '业务事件').length || sf.identified.length
    }** 项关键要素，可以进入流水线。`,
    '',
  ];
  if (sf.identified.length) lines.push(identifiedTable(sf.identified), '');
  if (payload.warnings?.length) {
    lines.push('### 提示', '', ...payload.warnings.map(w => `- ${w}`), '');
  }
  lines.push('---', '', '系统将自动启动 **PM 骨架提取**；完成后请在对话流中确认 IR-0 业务事件骨架。');
  return lines.join('\n');
}

export function buildGateErrorMarkdown(payload: GateErrorPayload): string {
  return [
    '## ❌ 需求评估异常',
    '',
    payload.message ?? '需求评估过程中发生异常，请稍后重试。',
