export function buildAttachmentsReadyMarkdown(payload: AttachmentsReadyPayload): string {
  const lines: string[] = ['### 📎 附件入库结果', ''];
  const rawItems = (payload as any).items ?? (payload as any).Items ?? payload.items ?? [];
  const items = rawItems.map((it: any) => ({
    fileName: it.fileName ?? it.FileName ?? '—',
    processStatus: it.processStatus ?? it.ProcessStatus ?? 0,
    extractedLength: it.extractedLength ?? it.ExtractedLength ?? 0,
    error: it.error ?? it.Error,
  }));
  if (items.length === 0) {
    lines.push('未登记新附件。', '');
    return lines.join('\n');
  }
  lines.push('| 文件 | 状态 | 提取字数 | 备注 |', '| --- | --- | --- | --- |');
  for (const it of items) {
    const status = it.processStatus === 2 ? '✅ 已解析' : it.processStatus === 3 ? '❌ 失败' : '⏳ 处理中';
    const note = it.error ? escapeCell(it.error) : '—';
    lines.push(`| ${escapeCell(it.fileName ?? '—')} | ${status} | ${it.extractedLength ?? 0} | ${note} |`);
  }
  if (payload.warnings?.length) {
    lines.push('', '**提示：**', ...payload.warnings.map(w => `- ${w}`));
  }
  lines.push('');
  return lines.join('\n');
}

/** 将整段 Markdown 以打字机效果写入 msg.content（大段文本加大块、降频，减轻重渲染抖动） */
export async function streamTextToMessage(
  msg: { content: string },
  fullText: string,
  opts?: { chunkSize?: number; delayMs?: number; onChunk?: () => void },
): Promise<void> {
  // 长文（门控报告等）用更大块；短文保留轻微打字感
  const long = fullText.length > 800;
  const chunkSize = opts?.chunkSize ?? (long ? 96 : 32);
  const delayMs = opts?.delayMs ?? (long ? 0 : 8);
  msg.content = '';
  for (let i = 0; i < fullText.length; i += chunkSize) {
    msg.content += fullText.slice(i, i + chunkSize);
    opts?.onChunk?.();
    if (delayMs > 0) await new Promise(r => setTimeout(r, delayMs));
    else if (long && i % (chunkSize * 4) === 0) {
      // 每约 4 块让出一帧，避免同步堵死主线程
      await new Promise<void>(r => requestAnimationFrame(() => r()));
    }
  }
}

/**
 * 重进会话时把 DB 精简消息 + 附件/交付物 水合成主聊天可见结构。
 * 目标：用户看到的主对话与离开前一致（门控文案、附件状态、交付物下载），而非原始 JSON / 空白。
 */
import {
  buildAttachmentsReadyMarkdown,
  buildGateFailedMarkdown,
  buildGatePassedMarkdown,
  gateFailedActions,
  normalizeSemanticFitness,
} from './gateStreamFormatter';
import type { AttachmentsReadyPayload, ChatStreamAction } from '../types/gate';

export type HydratedChatMessage = {
  id: string | number;
  role: string;
  content: string;
  thinking: string;
  thinkingCollapsed: boolean;
  strategies: any[];
  document: null | {
    name: string;
    previewUrl?: string;
    downloadPdfUrl?: string;
    downloadWordUrl?: string;
    relativePath?: string;
  };
  deliverableLinks: Array<{ name: string; relativePath: string }>;
  ir: any;
  actions: ChatStreamAction[];
  stageConfirmable: boolean;
  stageConfirmed: boolean;
  clarification: any;
  amendmentProposal?: any;
};

function pickName(d: any): string {
  return String(d?.fileName ?? d?.FileName ?? d?.relativePath ?? d?.RelativePath ?? '交付物');
}

function pickPath(d: any): string {
  return String(d?.relativePath ?? d?.RelativePath ?? d?.fileName ?? d?.FileName ?? '');
}

function preferDeliverables(items: any[]): Array<{ name: string; relativePath: string }> {
  const ranked = [...items]
    .map(d => ({ name: pickName(d), relativePath: pickPath(d) }))
    .filter(d => d.relativePath);
  const order = ['02-requirement-spec', '01-skeleton', '00-merged-requirement', '00-gate-report'];
  ranked.sort((a, b) => {
    const ai = order.findIndex(k => a.relativePath.includes(k) || a.name.includes(k));
    const bi = order.findIndex(k => b.relativePath.includes(k) || b.name.includes(k));
    return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
  });
  // 主聊天最多挂 4 个，避免刷屏
  return ranked.slice(0, 4);
}

function buildAttachmentThinking(attachments: any[]): string {
  if (!attachments?.length) return '';
  const payload: AttachmentsReadyPayload = {
    processed: attachments.filter(a => Number(a.processStatus ?? a.ProcessStatus) === 2).length,
    failed: attachments.filter(a => Number(a.processStatus ?? a.ProcessStatus) === 3).length,
    items: attachments.map(a => ({
      fileName: a.fileName ?? a.FileName,
      processStatus: Number(a.processStatus ?? a.ProcessStatus ?? 0),
      extractedLength: Number(a.extractedLength ?? a.ExtractedLength ?? 0),
      error: a.processError ?? a.ProcessError ?? a.error,
    })),
  };
  return buildAttachmentsReadyMarkdown(payload);
}

function mapBase(m: any): HydratedChatMessage {
  return {
    id: m.id ?? m.Id ?? `${Date.now()}-${Math.random()}`,
    role: m.role ?? m.Role ?? 'system',
    content: m.content ?? m.Content ?? '',
    thinking: m.thinking ?? m.Thinking ?? '',
    thinkingCollapsed: true,
    strategies: m.strategies ?? m.Strategies ?? [],
    document: m.document ?? m.Document ?? null,
    deliverableLinks: [],
    ir: m.ir ?? m.Ir ?? null,
    actions: m.actions ?? m.Actions ?? [],
    stageConfirmable: m.stageConfirmable ?? m.StageConfirmable ?? false,
    stageConfirmed: m.stageConfirmed ?? m.StageConfirmed ?? false,
    clarification: m.clarification ?? m.Clarification ?? null,
  };
}

/** 将 gate 阶段的 system JSON 还原为可读门控消息 */
function hydrateGateSystemMessage(msg: HydratedChatMessage, stage: string | undefined): HydratedChatMessage {
  if (msg.role !== 'system' || stage !== 'gate') return msg;
  const raw = (msg.content || '').trim();
  if (!raw.startsWith('{')) return msg;
  try {
    const parsed = JSON.parse(raw);
    const passed = parsed.Passed === true || parsed.passed === true;
    const failed = parsed.Passed === false || parsed.passed === false;
    const sf =
      normalizeSemanticFitness(parsed) ??
      ({
        passed,
        score: Number(parsed.Score ?? parsed.score ?? 0) || 0,
        level: passed ? 'sufficient' : 'insufficient',
        identified: [],
        missing: [],
      } as const);
    if (passed) {
      return {
        ...msg,
        role: 'assistant',
        content: buildGatePassedMarkdown(parsed, sf as any),
        thinkingCollapsed: true,
      };
    }
    if (failed) {
      return {
        ...msg,
        role: 'assistant',
        content: buildGateFailedMarkdown(parsed, sf as any),
        actions: gateFailedActions(),
        thinkingCollapsed: true,
      };
    }
  } catch {
    /* 非 JSON 则原样 */
  }
  return msg;
}

export function hydrateChatSession(opts: {
  rawMessages: any[];
  attachments: any[];
  deliverables: any[];
}): { messages: HydratedChatMessage[]; stats: Record<string, number | boolean> } {
  const attachmentThinking = buildAttachmentThinking(opts.attachments);
  const links = preferDeliverables(opts.deliverables);

  let gateTransformed = 0;
  const messages = opts.rawMessages.map(raw => {
    const stage = raw.stage ?? raw.Stage;
    let msg = mapBase(raw);
    const beforeRole = msg.role;
    msg = hydrateGateSystemMessage(msg, stage);
    if (beforeRole === 'system' && msg.role === 'assistant') gateTransformed += 1;
    return msg;
  });

  // 附件摘要挂到首条 assistant 的 thinking（可折叠）
  const firstAssistant = messages.find(m => m.role === 'assistant');
  if (firstAssistant && attachmentThinking) {
    firstAssistant.thinking = [attachmentThinking, firstAssistant.thinking].filter(Boolean).join('\n');
    firstAssistant.thinkingCollapsed = true;
  }

  // 交付物下载挂到最后一条 assistant
  const lastAssistant = [...messages].reverse().find(m => m.role === 'assistant');
  if (lastAssistant && links.length) {
    lastAssistant.deliverableLinks = links;
    const primary = links[0];
    lastAssistant.document = {
      name: primary.name,
      relativePath: primary.relativePath,
    };
  }

  return {
    messages,
    stats: {
      rawCount: opts.rawMessages.length,
      outCount: messages.length,
      gateTransformed,
      attachmentCount: opts.attachments.length,
      deliverableLinkCount: links.length,
      hasAttachmentThinking: !!attachmentThinking,
    },
  };
}

// 文件：src/views/studio/composables/parseSseStream.ts
// 职责：SSE 规范解析器（架构组件，任何 SSE 场景可复用）

/**
 * 严格遵循 W3C SSE 规范的流解析器
 *
 * 支持：
 *   - 多行 data 事件（用 \n 连接）
 *   - event: 字段（事件类型）
 *   - : 注释行（忽略）
 *   - \r\n 和 \n 两种换行
 *
 * 不支持（暂不实现）：
 *   - id: 字段（Last-Event-ID 恢复）
 *   - retry: 字段（重连间隔）
 */
export function parseSseStream(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  signal: AbortSignal,
  onEvent: (eventType: string, data: string) => void,
): Promise<void> {
  const decoder = new TextDecoder();
  let buffer = '';
  let currentEvent = 'message';
  const dataLines: string[] = [];

  const dispatch = () => {
    if (dataLines.length > 0) {
      onEvent(currentEvent, dataLines.join('\n'));
    }
    currentEvent = 'message';
    dataLines.length = 0;
  };

  return (async () => {
    while (true) {
      if (signal.aborted) {
        dispatch();
        return;
      }

      const { done, value } = await reader.read();
      if (done) {
        dispatch();
        return;
      }

      buffer += decoder.decode(value, { stream: true });

      let newLineIdx: number;
      while ((newLineIdx = buffer.indexOf('\n')) >= 0) {
        const line = buffer.slice(0, newLineIdx).replace(/\r$/, '');
        buffer = buffer.slice(newLineIdx + 1);

        if (line === '') {
          dispatch();
          continue;
        }

        if (line.startsWith(':')) continue;

        const colonIdx = line.indexOf(':');
        const field = colonIdx >= 0 ? line.slice(0, colonIdx) : line;
        const valueStr = colonIdx >= 0 ? line.slice(colonIdx + 1).replace(/^ /, '') : '';

        if (field === 'event') {
          currentEvent = valueStr;
        } else if (field === 'data') {
          dataLines.push(valueStr);
        }
      }
    }
  })();
}

import { computed, ref, watch, type InjectionKey, type Ref } from 'vue';
import type { IrEventRecord, IrFragmentSnapshot } from '../types/ir';
import { confirmRequirementSpec, runRequirementAnalysis, type SkillRunResult } from '../api/studio/skills';

export interface EventSaProgress {
  eventId: string;
  fragmentId: string;
  completedSteps: string[];
  percent: number;
  isStable: boolean;
}

export interface RequirementSpecPmReview {
  score: number | null;
  gaps: string[];
  verdict: string;
}

export const ANALYST_SKILL_KEY: InjectionKey<ReturnType<typeof useAnalystSkill>> = Symbol('analystSkill');

const SA_STEPS = [
  'DomainModel',
  'AggregateDesign',
  'EventCatalog',
  'CommandQuery',
  'IntegrationPoints',
  'WorkflowSpec',
  'UISpec',
  'DataModel',
  'DeliveryChecklist',
];

function isS2StageConfirmed(events: IrEventRecord[]) {
  return events.some(e => {
    if (e.eventType !== 'StageConfirmed') return false;
    try {
      const raw = e.payloadPreview ?? '';
      const p = typeof raw === 'string' && raw.startsWith('{') ? JSON.parse(raw) : { stage: raw };
      return p?.stage === 'S2';
    } catch {
      return false;
    }
  });
}

function parsePayload(raw?: string): Record<string, any> | null {
  if (!raw || !raw.trim().startsWith('{')) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export function useAnalystSkill(pipelineId: Ref<number>, snapshots: Ref<IrFragmentSnapshot[]>, refreshAll: () => Promise<void>, events?: Ref<IrEventRecord[]>) {
  const analystLoading = ref(false);
  const analysisCompleted = ref(false);
  const confirmLoading = ref(false);
  let abortController: AbortController | null = null;

  watch(pipelineId, () => {
    abortController?.abort();
    abortController = null;
    analystLoading.value = false;
    analysisCompleted.value = false;
    confirmLoading.value = false;
  });

  const s2Confirmed = computed(() => (events?.value ? isS2StageConfirmed(events.value) : false));

  const hasAnalysisCompletedEvent = computed(() => (events?.value ?? []).some(e => e.eventType === 'AnalysisCompleted'));

  const pmReview = computed<RequirementSpecPmReview>(() => {
    const list = (events?.value ?? []).filter(e => e.eventType === 'RequirementSpecPmReviewed');
    const latest = list[list.length - 1];
    const payload = parsePayload(latest?.payloadPreview);
    if (!payload) return { score: null, gaps: [], verdict: '' };
    const rawScore = payload.score ?? payload.Score;
    const gaps = payload.gaps ?? payload.Gaps ?? [];
    return {
      score: typeof rawScore === 'number' ? rawScore : rawScore != null ? Number(rawScore) : null,
      gaps: Array.isArray(gaps) ? gaps.map(String) : [],
      verdict: String(payload.verdict ?? payload.Verdict ?? ''),
    };
  });

  const needsRequirementSpecConfirmation = computed(() => false);

  const eventProgressList = computed<EventSaProgress[]>(() => {
    const specs = snapshots.value.filter(s => s.fragmentType === 'IR1_EventSpec' || s.fragmentId?.startsWith('eventspec:'));
    return specs.map(snap => {
      const eventId = snap.fragmentId?.replace(/^eventspec:/, '') ?? snap.fragmentId;
      const completed = snap.saStepsCompleted ?? [];
      return {
        eventId,
        fragmentId: snap.fragmentId,
        completedSteps: completed,
        percent: Math.round((completed.length / SA_STEPS.length) * 100),
        isStable: snap.stabilityState === 'stable' || snap.stabilityState === 'locked',
      };
    });
  });

  const totalProgress = computed(() => {
    if (eventProgressList.value.length === 0) return 0;
    const sum = eventProgressList.value.reduce((acc, e) => acc + e.percent, 0);
    return Math.round(sum / eventProgressList.value.length);
  });

  async function runAnalyst(): Promise<SkillRunResult | null> {
    if (!pipelineId.value || analystLoading.value) return null;
    analystLoading.value = true;
    abortController = new AbortController();
    try {
      const res = await runRequirementAnalysis(pipelineId.value);
      await refreshAll();
      return res;
    } finally {
      analystLoading.value = false;
      abortController = null;
    }
  }

  async function confirmAndProceed(autoRunDesign = true, forceConfirm = false): Promise<void> {
    if (!pipelineId.value || confirmLoading.value) return;
    confirmLoading.value = true;
    try {
      await confirmRequirementSpec(pipelineId.value, { autoRunDesign, forceConfirm });
      await refreshAll();
    } finally {
      confirmLoading.value = false;
    }
  }

  function markAnalysisCompleted() {
    analysisCompleted.value = true;
    analystLoading.value = false;
  }

  function handleSkillProgress(payload: { skillId?: string; phase?: string; percent?: number; message?: string }) {
    const id = payload.skillId ?? '';
    if (id === 'analyst-skill' || id === 'requirement-analysis-orchestrator' || id.startsWith('requirement-analysis')) {
      analystLoading.value = payload.phase !== 'completed' && payload.phase !== 'failed';
    }
  }

  return {
    SA_STEPS,
    analystLoading,
    analysisCompleted,
    confirmLoading,
    s2Confirmed,
    pmReview,
    needsRequirementSpecConfirmation,
    eventProgressList,
    totalProgress,
    runAnalyst,
    confirmAndProceed,
    markAnalysisCompleted,
    handleSkillProgress,
  };
}

/** S2 正式交付物路径（PipelineDeliverableService 唯一源） */
export const REQUIREMENT_SPEC_PATH = '02-requirement-spec.md';

/** RequirementDocumentRenderer 封面标题 */
export const REQUIREMENT_SPEC_TITLE = '# 需求分析规格说明书';

/** RequirementDocumentRenderer 确认 CTA 固定文本 */
export const REQUIREMENT_SPEC_CTA = '请你确认需求分析说明书';

export type RequirementSpecPhase =
  | 'absent'
  | 'refining'
  | 'rendered'
  | 'confirmed'
  | 'pmreviewed'
  | 'finalized'
  | 'superseded';

export function isRequirementSpecPath(relativePath?: string | null): boolean {
  if (!relativePath) return false;
  const normalized = relativePath.replace(/\\/g, '/');
  return normalized === REQUIREMENT_SPEC_PATH || normalized.endsWith(`/${REQUIREMENT_SPEC_PATH}`);
}

/** 校验是否为正式渲染版（非 PM raw / 中间分析产物） */
export function isFormalRequirementSpec(text: string): boolean {
  return text.includes(REQUIREMENT_SPEC_TITLE) && text.includes(REQUIREMENT_SPEC_CTA);
}

/** 解包 defHttp RESTfulResult（{ code, data }）及业务 payload */
export function unwrapStudioApi<T>(res: unknown): T {
  const root = (res as any)?.data ?? res;
  if (root && typeof root === 'object' && ('code' in root || 'Code' in root) && ('data' in root || 'Data' in root)) {
    return (root.data ?? root.Data) as T;
  }
  return root as T;
}

export interface RequirementSpecContentPayload {
  markdown?: string;
  Markdown?: string;
  rendered?: boolean;
  Rendered?: boolean;
  relativePath?: string;
  RelativePath?: string;
  contentLength?: number;
  ContentLength?: number;
  phase?: string;
  Phase?: string;
  pipelineStage?: string;
  PipelineStage?: string;
  contentHash?: string;
  ContentHash?: string;
  canUserConfirm?: boolean;
  CanUserConfirm?: boolean;
  canUserFeedback?: boolean;
  CanUserFeedback?: boolean;
  awaitingUser?: boolean;
  AwaitingUser?: boolean;
}

export function pickRequirementSpecMarkdown(payload?: RequirementSpecContentPayload | Record<string, unknown> | null): string {
  const p = payload as RequirementSpecContentPayload | null | undefined;
  return (p?.markdown ?? p?.Markdown ?? '').trim();
}

export function pickRequirementSpecPhase(payload?: RequirementSpecContentPayload | Record<string, unknown> | null): RequirementSpecPhase | '' {
  const raw = (payload as RequirementSpecContentPayload | null | undefined)?.phase
    ?? (payload as RequirementSpecContentPayload | null | undefined)?.Phase
    ?? '';
  return String(raw).trim().toLowerCase() as RequirementSpecPhase | '';
}

export function isRequirementSpecRendered(payload?: RequirementSpecContentPayload | Record<string, unknown> | null): boolean {
  const phase = pickRequirementSpecPhase(payload);
  if (phase) {
    return ['rendered', 'confirmed', 'pmreviewed', 'finalized'].includes(phase);
  }
  const p = payload as RequirementSpecContentPayload | null | undefined;
  return p?.rendered === true || p?.Rendered === true;
}

export function pickRequirementSpecPath(payload?: RequirementSpecContentPayload | null): string {
  return payload?.relativePath ?? payload?.RelativePath ?? REQUIREMENT_SPEC_PATH;
}

import { reactive, computed, nextTick, unref } from 'vue';
import { useUserStore } from '/@/store/modules/user';
import type { FormInstance } from 'ant-design-vue';
import type { Ref } from 'vue';
import { getBillNumber } from '/@/api/system/billRule';
import { useMessage } from '/@/hooks/web/useMessage';
import { isEmpty } from '/@/utils/is';

interface State {
  config: any;
  loading: boolean;
  eventType: string;
  flowUrgent: number;
  formRef: string;
  tableRequiredData: any;
}
interface UseFlowFormContext {
  config: any;
  selfState: any;
  emit: EmitType;
  formRef: Ref<FormInstance | undefined>;
  beforeInit?: any;
  selfGetInfo?: any;
  selfInit?: any;
  beforeSubmit?: any;
  selfSubmit?: any;
  selfExist?: any;
}

const userStore = useUserStore();
const { createMessage } = useMessage();
const state = reactive<State>({
  config: {},
  loading: false,
  eventType: '',
  flowUrgent: 1,
  formRef: 'formRef',
  tableRequiredData: {},
});

const includeList = ['crmOrder', 'salesOrder', 'leaveApply'];

const getUserInfo = computed(() => userStore.getUserInfo || {});

export function useFlowForm(data: UseFlowFormContext) {
  const { config, emit, formRef, selfState } = data;

  function getForm() {
    const form = unref(formRef);
    if (!form) {
      throw new Error('form is null!');
    }
    return form;
  }

  function init() {
    selfState.dataForm.id = config.id || '';
    state.config = config;
    state.loading = true;
    updateDataRule();
    nextTick(() => {
      getForm().resetFields();
      // 自定义初始化前方法
      if (data.beforeInit && typeof data.beforeInit === 'function') data.beforeInit();
      if (config.id) {
        selfState.dataForm = config.draftData || config.formData;
        // 自定义获取详情方法
        if (data.selfGetInfo && typeof data.selfGetInfo === 'function') data.selfGetInfo(selfState.dataForm);
        if (includeList.includes(config.formEnCode) && selfState.dataForm.fileJson) selfState.fileList = JSON.parse(selfState.dataForm.fileJson);
        emit('setPageLoad');
        return;
      } else {
        selfState.dataForm.flowId = config.flowId;
        // 自定义初始化方法
        if (data.selfInit && typeof data.selfInit === 'function') data.selfInit(data);
        if (!selfState.billEnCode) return emit('setPageLoad');
        getBillNumber(selfState.billEnCode).then(res => {
          if (selfState.billEnCode === 'OrderNumber') {
            selfState.dataForm.orderCode = res.data;
          } else {
            selfState.dataForm.billNo = res.data;
          }
          emit('setPageLoad');
        });
      }
      state.loading = false;
      emit('setPageLoad');
    });
  }
  // 更新校验规则
  function updateDataRule() {
    if (!config.formOperates || !config.formOperates.length) return (selfState.dataRule = {});
    const newRules = {};
    for (let i = 0; i < config.formOperates.length; i++) {
      const item = config.formOperates[i];
      if (!item.id.includes('-')) {
        const newRulesItem = {
          required: item.required || false,
          message: item.name + '不能为空',
          trigger: item.trigger || 'blur',
        };
        if (!selfState.dataRule.hasOwnProperty(item.id)) {
          if (item.required) newRules[item.id] = [newRulesItem];
        } else {
          let withoutRequiredItem = true;
          for (let i = 0; i < selfState.dataRule[item.id].length; i++) {
            if (selfState.dataRule[item.id][i].hasOwnProperty('required')) {
              selfState.dataRule[item.id][i].required = item.required || false;
              withoutRequiredItem = false;
            }
          }
          if (withoutRequiredItem && item.required) selfState.dataRule[item.id].push(newRulesItem);
        }
      } else {
        const key = item.id.split('-')[0];
        const newId = item.id.split('-')[1];
        const newItem = {
          ...item,
          id: newId,
        };
        if (!state.tableRequiredData.hasOwnProperty(key)) {
          state.tableRequiredData[key] = [newItem];
        } else {
          state.tableRequiredData[key].push(newItem);
        }
      }
    }
    selfState.dataRule = { ...selfState.dataRule, ...newRules };
  }
  async function dataFormSubmit(eventType, flowUrgent) {
    try {
      const values = await getForm()?.validate();
      if (!values) return;
      selfState.dataForm = { ...selfState.dataForm, ...values };
      if (!exist()) return;
      if (data.selfExist && typeof data.selfExist === 'function' && !data.selfExist()) return;
      let formData: any = {};
      if (data.beforeSubmit && typeof data.beforeSubmit === 'function') {
        formData = data.beforeSubmit();
      } else {
        formData = selfState.dataForm;
      }
      if (includeList.includes(config.formEnCode)) formData.fileJson = JSON.stringify(selfState.fileList || []);
      if (eventType === 'save' || eventType === 'submit') {
        if (data.selfSubmit && typeof data.selfSubmit === 'function') {
          data.selfSubmit(formData, eventType, flowUrgent);
          return;
        }
      }
      emit('eventReceiver', { formData }, eventType);
    } catch (_) {}
  }
  function exist() {
    let isOk = true;
    if (JSON.stringify(state.tableRequiredData) === '{}') return isOk;
    for (const key in state.tableRequiredData) {
      if (selfState.dataForm[key] && Array.isArray(selfState.dataForm[key])) {
        for (let i = 0; i < selfState.dataForm[key].length; i++) {
          const item = selfState.dataForm[key][i];
          inner: for (const id in item) {
            const arr = state.tableRequiredData[key].filter(o => o.id === id) || [];
            if (!arr.length) continue inner;
            if (arr[0].required) {
              const msg = `${arr[0].name}不能为空`;
              const boo = (!item[id] && item[id] != 0) || isEmpty(item[id]);
              if (boo) {
                createMessage.error(msg);
                isOk = false;
                break;
              }
            }
          }
        }
      }
    }
    return isOk;
  }
  function judgeRequired(id) {
    if (!config.formOperates || !config.formOperates.length) return false;
    const arr = config.formOperates.filter(o => o.id === id) || [];
    if (!arr.length) return false;
    const item = arr[0];
    return item.required;
  }
  function judgeShow(id) {
    if (config.opType == 4) return true;
    if (!config.formOperates || !config.formOperates.length) return true;
    const arr = config.formOperates.filter(o => o.id === id) || [];
    if (!arr.length) return true;
    const item = arr[0];
    return item.read;
  }
  function judgeWrite(id) {
    if (config.disabled) return true;
    if (!config.formOperates || !config.formOperates.length) return false;
    const arr = config.formOperates.filter(o => o.id === id) || [];
    if (!arr.length) return true;
    const item = arr[0];
    return !item.write;
  }

  return {
    comState: state,
    init,
    getUserInfo,
    judgeRequired,
    judgeShow,
    judgeWrite,
    getForm,
    dataFormSubmit,
  };
}
